local config = {
  ui_story_5031_50310101_1_dialog_content = "皆さま、<color=#FFB400>マジックハンド・ビルのサーカス</color>へようこそ！\nあたしはこの公演の司会――<color=#FFB400>レインボー</color>です！",
  ui_story_5031_50310101_2_dialog_content = "この素晴らしい夜にエメラルド号へと乗船されている皆様は、\n誰もが私たちサーカス団の大切なお客様です。",
  ui_story_5031_50310101_3_dialog_content = "日頃の悩みや心配事を忘れ、心行くまで鮮やかなショーをお楽しみください。",
  ui_story_5031_50310101_4_dialog_content = "マジックハンド・ビルサーカス団の面々が、\n常識と想像を超える最高のショーをお届けします。",
  ui_story_5031_50310101_5_dialog_content = "これからお届けする素敵な時間は\n皆さまとあたし、そして全世界のものなのです。",
  ui_story_5031_50310101_6_dialog_content = "それでは、我らが天空のスペシャリスト、\n空中ブランコの奥義を極めた三姉妹、メルト――",
  ui_story_5031_50310101_7_dialog_content = "サプリ――",
  ui_story_5031_50310101_8_dialog_content = "ファムの――",
  ui_story_5031_50310101_9_dialog_content = "登場です――！",
  ui_story_5031_50310101_10_dialog_content = "あ、あの、レインボー姐さん…\n空中ブランコはメンテナンス中では…？",
  ui_story_5031_50310101_11_dialog_content = "そうだよ。いくら私たちでも、\n何もなしに宙に浮いてパフォーマンスするなんてムリ～。",
  ui_story_5031_50310101_12_dialog_content = "エヘヘ。実はファム、\n最近、サーカス団の大きい人たちとトレーニングしてたんだ。",
  ui_story_5031_50310101_13_dialog_content = "メル姉とサプ姉ぐらいなら、\n直接空中に投げられるかもよ～。",
  ui_story_5031_50310101_14_dialog_content = "やらなくていいわ…危ないでしょう。\n他の人をケガさせてしまうかもしれないし…",
  ui_story_5031_50310101_15_dialog_content = "ちょっと、団長も何とか言ってよ。",
  ui_story_5031_50310101_16_dialog_content = "道具の準備もできてないのに、\nリハーサルなんてできるはずないでしょ！",
  ui_story_5031_50310101_17_dialog_content = "それに、私たち3人の実力なら、\nリハーサルなんていらないわよ！",
  ui_story_5031_50310101_18_dialog_content = "サプ…ジェノ団長にそんなこと言わないの。",
  ui_story_5031_50310101_19_dialog_content = "何ですか？僕は今、手が離せません。",
  ui_story_5031_50310101_20_dialog_content = "エルビスから補給が届きました。\n舞台装置は最終メンテナンス中です。",
  ui_story_5031_50310101_21_dialog_content = "リハーサルをする気になれないのであれば、\nどこかで休んでいてください。",
  ui_story_5031_50310101_22_dialog_content = "レインボー、動物と話ができると言う\n臨時パフォーマーを呼んできてください。",
  ui_story_5031_50310101_23_dialog_content = "かき氷の食べ過ぎでお腹を壊した猛獣使いの代わりに\n彼女を出せるか、見てみましょう。",
  ui_story_5031_50310101_24_dialog_content = "了解～。",
  ui_story_5031_50310101_25_dialog_content = "フィアちゃん、準備できた？",
  ui_story_5031_50310101_26_dialog_content = "ちょ、ちょっと待って！",
  ui_story_5031_50310101_27_dialog_content = "ほら、ビッカー、こっちに来なさい…",
  ui_story_5031_50310101_28_dialog_content = "ハイ。",
  ui_story_5031_50310101_29_dialog_content = "あたしの言った通り、ジャンプと同時に宙返りするの。",
  ui_story_5031_50310101_30_dialog_content = "ハイ！",
  ui_story_5031_50310101_31_dialog_content = "お願い。いい子だから、1回でもあたしの言うことを聞いて…\nあの怖い団長がまだ下で見てるの！",
  ui_story_5031_50310101_32_dialog_content = "ハ～イ！！",
  ui_story_5031_50310101_33_dialog_content = "わっ！落ち着いて！\n謝ってるでしょ、もう噛まないで！",
  ui_story_5031_50310101_34_dialog_content = "止めなさい！！",
  ui_story_5031_50310101_35_dialog_content = "どういうことです？早くステージから降りてどうにかしてください！\nリハーサルの邪魔です！",
  ui_story_5031_50310101_36_dialog_content = "ジェノ団長！？",
  ui_story_5031_50310101_37_dialog_content = "何をしているのです？\n動物たちと話はできましたか？",
  ui_story_5031_50310101_38_dialog_content = "全然いうことを聞かないの！\n甘やかされすぎじゃない！？",
  ui_story_5031_50310101_39_dialog_content = "言うことを聞かない？",
  ui_story_5031_50310101_40_dialog_content = "そうだよ！しかも怖い顔して、\nあたしに噛みつこうとしてばっかり…",
  ui_story_5031_50310101_41_dialog_content = "ああ、それなら当然のことです。",
  ui_story_5031_50310101_42_dialog_content = "当然？",
  ui_story_5031_50310101_43_dialog_content = "動物たちには我がサーカス団で働きたい時に働き、\n働きたくない時は自由にする権利を与えられていますから。",
  ui_story_5031_50310101_44_dialog_content = "なにそれ…？",
  ui_story_5031_50310101_45_dialog_content = "あんたたちのサーカス団って、\nあたしが本で読んだのと全然違うんだね。",
  ui_story_5031_50310101_46_dialog_content = "サーカスって動物に厳しくして恐怖で従わせて、\nショーをさせてるって書いてあったけど？",
  ui_story_5031_50310101_47_dialog_content = "ひどい偏見です。",
  ui_story_5031_50310101_48_dialog_content = "そのように言われているとは聞いたこともありませんでした。\nなぜ動物たちに厳しくするのです？旅を共にする大事な仲間ですよ。",
  ui_story_5031_50310101_49_dialog_content = "ビッカーの毛を触ってみてください。\nとても癒されるでしょう。",
  ui_story_5031_50310101_50_dialog_content = "ハイ～。",
  ui_story_5031_50310101_51_dialog_content = "とにかく、僕のサーカス団では\n動物をそのように扱ったりはしません。",
  ui_story_5031_50310101_52_dialog_content = "これまでの猛獣使いは皆、問題なくショーができていました。\n自分に理由がないか考えてみてください。",
  ui_story_5031_50310101_53_dialog_content = "ホントに！？",
  ui_story_5031_50310101_54_dialog_content = "うぅ…あ、あたしは一人前の珍獣マスター！\n珍獣には無敵のカリスマをほこるフィア様なのに！",
  ui_story_5031_50310101_55_dialog_content = "こんなことで負けてられない！絶対に…",
  ui_story_5031_50310101_56_dialog_content = "安心しなさい、PlayerName。\nバレエを踊るぐらい、私には難しいことでもないわ。",
  ui_story_5031_50310101_57_dialog_content = "まさか、カレンのバレエを見られるなんてね。",
  ui_story_5031_50310101_58_dialog_content = "巨像で他の白夜城の光霊から聞いたけど、\nバレエの先生も驚くほどの天才なんだそうよ。",
  ui_story_5031_50310101_59_dialog_content = "本当？それを聞いたら、\n僕もすごく楽しみになってきたよ。",
  ui_story_5031_50310101_60_dialog_content = "PlayerName――！",
  ui_story_5031_50310101_61_dialog_content = "フィア？動物にショーをしてもらうんじゃないの？\nどうしてここに？",
  ui_story_5031_50310101_62_dialog_content = "うっ…ううぅ…あいつら、本当にムカつくの…\n働きたくない時は働かなくていいんだって…",
  ui_story_5031_50310101_63_dialog_content = "…あたしは師匠にいつもいつもこき使われてるのにって、\n思いだしたら…うわあああん！",
  ui_story_5031_50310101_64_dialog_content = "な、泣かないで！？",
  ui_story_5031_50310101_65_dialog_content = "忘れないで！\n君はすごい珍獣マスターなんだ！",
  ui_story_5031_50310101_66_dialog_content = "うぅっ、それならなんで、\nすごい珍獣マスターのあたしが一日中師匠のパシリなの！",
  ui_story_5031_50310101_67_dialog_content = "そんなことは考えちゃダメだ！\nいつものワガママぶりを見せてよ！",
  ui_story_5031_50310101_68_dialog_content = "何て言った？",
  ui_story_5031_50310101_69_dialog_content = "あっ、ええと…僕たちが一緒に乗り越えてきた困難、\nそして君の大きな目標を思い返してみてよ――！",
  ui_story_5031_50310101_70_dialog_content = "うぅっ…一緒に乗り越えてきた困難…\nあたしたちの目標…",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>ハーバーシティに到着直後…</color>",
  ui_story_5031_50310101_72_dialog_content = "カレン、僕とバイスを招待してくれてありがとう。",
  ui_story_5031_50310101_73_dialog_content = "ここは本当にステキな場所ね。\n静かで落ち着いてるし、すごくリラックスできそう。",
  ui_story_5031_50310101_74_dialog_content = "皆で一緒に来られて本当によかったわ。",
  ui_story_5031_50310101_75_dialog_content = "どういたしまして。最近、色々あったでしょう。\n皆も少し羽を伸ばした方が、体にも心にもいいと思って。",
  ui_story_5031_50310101_76_dialog_content = "ハーバーシティに来るのは子どもの時以来だわ。\nその時のことはよく覚えている…",
  ui_story_5031_50310101_77_dialog_content = "あれから何年かで、こんなに栄えるとは思いもしなかったわ。\nきっと今の領主が優秀なのでしょうね。",
  ui_story_5031_50310101_78_dialog_content = "<size=33>見つけた…</size>",
  ui_story_5031_50310101_79_dialog_content = "君のお父さんみたいに？",
  ui_story_5031_50310101_80_dialog_content = "見る人たち、みんな幸せそうな顔だ。\n僕もここを治めてる人がどんな人なのか、気になってきたよ。",
  ui_story_5031_50310101_81_dialog_content = "…あの人とは違うでしょうね。",
  ui_story_5031_50310101_82_dialog_content = "礼儀として、領主を訪問しておかないといけないの。\n一緒に行きましょう。",
  ui_story_5031_50310101_83_dialog_content = "さっきポスターを見かけたよ。大きな船の上で、\nカーニバルとかサーカスのショーをやるみたいだね。",
  ui_story_5031_50310101_84_dialog_content = "そこに行って、\n詳しく聞いてみない？",
  ui_story_5031_50310101_85_dialog_content = "せっかく羽を伸ばすんだし、夏らしいことに参加しようよ。\nリラックスするにはそれがいちばんだ！",
  ui_story_5031_50310101_86_dialog_content = "そうね！私もこのハーバーシティのおもしろいものや、\nおいしいものが知りたいわ。",
  ui_story_5031_50310101_87_dialog_content = "バイス、遊びに出るのなんて久しぶりだから、\nずいぶんうれしそうだね。",
  ui_story_5031_50310101_88_dialog_content = "<size=33>ロックオン――PlayerName！</size>",
  ui_story_5031_50310101_89_dialog_content = "じゃあ行こ――<size=50>うわっ！</size>",
  ui_story_5031_50310101_90_dialog_content = "イテテ、腰が！",
  ui_story_5031_50310101_91_dialog_content = "（この展開、最近あったような…）",
  ui_story_5031_50310101_92_dialog_content = "これ以上近づかないで！\nじゃないと、本当に助けを呼ぶよ！",
  ui_story_5031_50310101_93_dialog_content = "いっけーっ！",
  ui_story_5031_50310101_94_option_content = "強制…うわっ！！",
  ui_story_5031_50310101_95_dialog_content = "腰が…！",
  ui_story_5031_50310101_96_dialog_content = "ルルル～！",
  ui_story_5031_50310101_97_dialog_content = "よくやったわ、キャロ！\n作戦通り、森まで退くよ！",
  ui_story_5031_50310101_98_dialog_content = "あ、あたしはただ…\nお友だちが欲しかっただけなのに…",
  ui_story_5031_50310101_99_dialog_content = "ル…",
  ui_story_5031_50310101_100_dialog_content = "フィアを好きになるのなんて、珍獣ぐらいだって皆に言われて…\nあたしだって光霊や空の末裔とお友だちになれるって証明したかったのに…",
  ui_story_5031_50310101_101_dialog_content = "えへへ…じゃあ、PlayerNameは、\nあたしの初めてのお友だちだね！",
  ui_story_5031_50310101_102_dialog_content = "お友だちになってくれて、\n本当にうれしい！",
  ui_story_5031_50310101_103_dialog_content = "師匠…フィア、お友だちができたよ！",
  ui_story_5031_50310101_104_dialog_content = "や、やっぱり！？フィア！",
  ui_story_5031_50310101_105_dialog_content = "なんでゴミ箱の中で待ち伏せなんてしてるの！？",
  ui_story_5031_50310101_106_dialog_content = "ヘヘヘ…PlayerName！つかまえた！",
  ui_story_5031_50310101_107_dialog_content = "フィア？",
  ui_story_5031_50310101_108_dialog_content = "…そうだよ。この子がフィア。",
  ui_story_5031_50310101_109_dialog_content = "珍獣マスターと言ったかしら。\nこの子が？",
  ui_story_5031_50310101_110_dialog_content = "珍獣の専門家たちの話は聞いたことがあるけれど、\nこんなに小さい子がいるなんて…",
  ui_story_5031_50310101_111_dialog_content = "久しぶりね、フィアちゃん。",
  ui_story_5031_50310101_112_dialog_content = "久しぶり～、バイスお姉ちゃん。",
  ui_story_5031_50310101_113_dialog_content = "カレンお姉ちゃん！\nあたしは珍獣マスターのフィアって言います！",
  ui_story_5031_50310101_114_dialog_content = "師匠から卒業したばっかりで、まだ半人前の珍獣マスターです。\n迷惑をおかけするかもしれませんが、よろしくお願いいたします！",
  ui_story_5031_50310101_115_dialog_content = "白夜城のカレンよ。\n雰囲気がラファエルと似ているわね。",
  ui_story_5031_50310101_116_dialog_content = "機会があれば紹介してあげましょう。\n気が合うかもしれないわ。",
  ui_story_5031_50310101_117_dialog_content = "ちょっと待った。",
  ui_story_5031_50310101_118_dialog_content = "ねえ、急にネコを被ってどうしたの？",
  ui_story_5031_50310101_119_dialog_content = "な、何言ってんの！？フィアはいつも優しいいい子でしょ！\nPlayerName、他の人がいる前で根も葉もないこと言わないで！",
  ui_story_5031_50310101_120_dialog_content = "はいはい…じゃあ、フィアがいつまで\n「いい子」でいられるか、見せてもらうよ。",
  ui_story_5031_50310101_121_dialog_content = "それで、どうしてここにいるの？\nキャロは？",
  ui_story_5031_50310101_122_dialog_content = "シーッ！フィアはキャロと一緒に\n師匠の「<color=#FFB400>秘密の任務</color>」を任されてるの！",
  ui_story_5031_50310101_123_dialog_content = "キャロは近くの海で調査を始めてるよ。",
  ui_story_5031_50310101_124_dialog_content = "秘密の任務って…？\nまさか、この前みたいに色々やらされてるんじゃ…",
  ui_story_5031_50310101_125_dialog_content = "それにキャロってこの前、大きくなったよね。\n泳ぎ回ってたら目立つんじゃない？",
  ui_story_5031_50310101_126_dialog_content = "ふん、キャロを甘く見たらダメ！\n2つの姿に変身できるようになってるの。",
  ui_story_5031_50310101_127_dialog_content = "師匠は、キャロががんばって練習を続ければ、\n人の姿にもなれるかもしれないって言ってたよ。",
  ui_story_5031_50310101_128_dialog_content = "考えるとちょっと怖いような…",
  ui_story_5031_50310101_129_dialog_content = "大丈夫だよ。キャロを怒らせない限りね～。",
  ui_story_5031_50310101_130_dialog_content = "とにかく、今はキャロのことはいいの！今回は本当に大事な仕事！\n「<color=#FFB400>超希少種</color>」に関わることなんだよ！",
  ui_story_5031_50310101_131_dialog_content = "…盗み聞きするつもりはなかったのだけれど…",
  ui_story_5031_50310101_132_dialog_content = "フィアちゃん、声が大きすぎるわ…",
  ui_story_5031_50310101_133_dialog_content = "わざわざPlayerNameを待っていたということは、\nその「秘密の任務」に協力してほしいと言う事ね？",
  ui_story_5031_50310101_134_dialog_content = "うっ、ついうっかり…",
  ui_story_5031_50310101_135_dialog_content = "うーん、でも、カレンお姉ちゃんやバイスお姉ちゃんも\nPlayerNameの友達だし、信用していいよね…",
  ui_story_5031_50310101_136_dialog_content = "それならいっそ、全部話しちゃお。",
  ui_story_5031_50310101_137_dialog_content = "実は、何日か前に――",
  ui_story_5031_50310101_138_dialog_content = "えっ！？ハーバーシティに行っていいの？",
  ui_story_5031_50310101_139_dialog_content = "エヘヘ…景色がきれいで、\nおいしいものもたくさんあるって聞いてるよ。",
  ui_story_5031_50310101_140_dialog_content = "師匠がそんなに気遣ってくれるなんて…\nあたしの大変さをやっと分かって、休ませてくれるつもりなんだ！",
  ui_story_5031_50310101_141_dialog_content = "あそこはビーチがすごく有名だし…\nそういえばフィア、水着の用意はまだだった…",
  ui_story_5031_50310101_142_dialog_content = "はっはっは、考えが甘いな。",
  ui_story_5031_50310101_143_dialog_content = "そんなおいしい話なら、\n俺が真っ先に行ってるさ。",
  ui_story_5031_50310101_144_dialog_content = "任務と言っただろう？\n遊びに行かせるわけじゃない。",
  ui_story_5031_50310101_145_dialog_content = "ほら、旅費をやる。\nさっさと出発するんだ。",
  ui_story_5031_50310101_146_dialog_content = "えっ！たったこれだけ！？",
  ui_story_5031_50310101_147_dialog_content = "ちょ、ちょっと、師匠！？\nどこ行くの！？",
  ui_story_5031_50310101_148_dialog_content = "はぁ…あのダメ師匠に、\n優しさを期待したのが間違いだった…",
  ui_story_5031_50310101_149_dialog_content = "うーん、師匠への文句ばかりで、\n肝心な情報が何一つない…",
  ui_story_5031_50310101_150_dialog_content = "それはこれから話すところ！",
  ui_story_5031_50310101_151_dialog_content = "今回のターゲットは「<color=#FFB400>海雲クジラ</color>」って名前の珍獣なの。",
  ui_story_5031_50310101_152_dialog_content = "師匠はその子の特殊な光力を追い続けてて…\nその珍獣、この近くの海に来たみたいなんだって。",
  ui_story_5031_50310101_153_dialog_content = "でも最近、急に光力が消えちゃったらしいの。",
  ui_story_5031_50310101_154_dialog_content = "急にあとかたもなく消えたから、\nどこかへ行ったんじゃなくて、きっと何かあったんだろうって。",
  ui_story_5031_50310101_155_dialog_content = "状況はあまりよくなさそうね。",
  ui_story_5031_50310101_156_dialog_content = "そうなんだ。「超希少種」としての力は、\nドラゴライオンよりも強いって師匠が言ってた。",
  ui_story_5031_50310101_157_dialog_content = "伝説によると、暗力をかき消す強い光力を持っていて、\n暗鬼ですら恐怖を感じるんだって。",
  ui_story_5031_50310101_158_dialog_content = "しかも寿命がすごく長くて、\n自然には死なないらしいの。",
  ui_story_5031_50310101_159_dialog_content = "だから…師匠はその珍獣が悪い人に\n捕まったんじゃないかって心配してるの。",
  ui_story_5031_50310101_160_dialog_content = "海雲クジラの性格は優しいけど、力を誰かに悪用されたら、\n恐ろしいことが起こるだろうからって。",
  ui_story_5031_50310101_161_dialog_content = "もしあなたの言う通りだとしたら…\n私たちも黙って見ているわけにはいかないわね。",
  ui_story_5031_50310101_162_dialog_content = "何か手がかりはあるの？",
  ui_story_5031_50310101_163_dialog_content = "うーん、それがさっぱりなんだ。\n師匠、話が終わったら、すぐどっかに行っちゃって…",
  ui_story_5031_50310101_164_dialog_content = "それでハーバーシティをアテもなくウロウロしていて、\n僕を見つけたから、待ち伏せした？",
  ui_story_5031_50310101_165_dialog_content = "さすがPlayerName、鋭いね～！\nあと正直に言うと、師匠からもらったお金も無くなっちゃったの。",
  ui_story_5031_50310101_166_dialog_content = "PlayerNameがいなかったら、\nどうなってたか…",
  ui_story_5031_50310101_167_dialog_content = "そんなことだと思ったよ…",
  ui_story_5031_50310101_168_dialog_content = "まずは情報を集めましょう。\nちょうど私たちは領主を訪ねに行くところだったの。",
  ui_story_5031_50310101_169_dialog_content = "もしかしたら、何か教えてもらえるかもしれないわ。",
  ui_story_5031_50310101_170_dialog_content = "うん！じゃあカレンお姉ちゃんの言う通りにしよ！\nしゅっぱ～つ！",
  ui_story_5031_50310101_171_dialog_content = "ちょっと…先頭に立つのはいいけど、\n道は知ってるの？",
  ui_story_5031_50310101_172_dialog_content = "元気ねぇ。",
  ui_story_5031_50310201_1_dialog_content = "<color=#FFB400>エルビス</color>様…忠誠を誓う兵士たちの準備が整いました。",
  ui_story_5031_50310201_2_dialog_content = "計画通り、エメラルド号に運ばれる\n補給品と花火をカモフラージュとします。",
  ui_story_5031_50310201_3_dialog_content = "分かった。",
  ui_story_5031_50310201_4_dialog_content = "パト、ご苦労だった。\nこのことに関して、信頼できるのはお前だけかもしれん…",
  ui_story_5031_50310201_5_dialog_content = "ははっ！何なりとお申し付けください。\nエルビス様にお仕えできることを光栄に思います。",
  ui_story_5031_50310201_6_dialog_content = "やれやれ。チャンスが一瞬しかないからと言って、\nお前たちにこんな危険な役目を押し付けてしまうとは…",
  ui_story_5031_50310201_7_dialog_content = "も、申し上げます！\nエルビス様、パト隊長！",
  ui_story_5031_50310201_8_dialog_content = "バカもの！誰も入ってはならぬと言っただろう！",
  ui_story_5031_50310201_9_dialog_content = "は、はい。申し訳ありません。\nですが、来客のご身分を考えると、門前払いともいかず…",
  ui_story_5031_50310201_10_dialog_content = "来客のご身分？\nそのようにあわてては、我らモドリー家の兵の面汚しではないか。",
  ui_story_5031_50310201_11_dialog_content = "そ、その…カレン殿下が…",
  ui_story_5031_50310201_12_dialog_content = "なんだと？カレン殿下？白夜城のか？",
  ui_story_5031_50310201_13_dialog_content = "つまり、ハーバーシティは暗潮の危機の前に\n正式に白夜城に帰属して、保護を受けるようになったってこと？",
  ui_story_5031_50310201_14_dialog_content = "その前は？ずっと自分たちの力だけで守ってたの？",
  ui_story_5031_50310201_15_dialog_content = "文献の記録によると、かつてハーバーシティには大量の暗鬼が出没して、\nここで暮らす人たちが、土地を巡って暗鬼と戦い続けていたそうよ。",
  ui_story_5031_50310201_16_dialog_content = "長く続く戦争の中で、この地の統治者で強大な光力を持つ\n「<color=#FFB400>モドリー</color>」家が、他の一族をまとめ…",
  ui_story_5031_50310201_17_dialog_content = "数々の激戦の末、\nついに暗鬼をすべて追い払ったのだとか。",
  ui_story_5031_50310201_18_dialog_content = "その後…",
  ui_story_5031_50310201_19_dialog_content = "その後、この地は「<color=#FFB400>光の神</color>」の加護を受け、\n暗鬼が騒ぎを起こすこともほとんどなくなりました。",
  ui_story_5031_50310201_20_dialog_content = "人々は平和に暮らし、\n街は栄えていったのです。",
  ui_story_5031_50310201_21_dialog_content = "カレン殿下がハーバーシティの歴史を\nそこまでご存知とは、光栄でございますね。",
  ui_story_5031_50310201_22_dialog_content = "白夜城の保護にも感謝しております。「<color=#FFB400>神の加護</color>」だけで、\n暗潮の危機を生き延びることはできなかったでしょうから。",
  ui_story_5031_50310201_23_dialog_content = "遅ればせながら、私はエルビス・モドリー。\nモドリー家の末裔であり、ハーバーシティの現領主です。",
  ui_story_5031_50310201_24_dialog_content = "（おかしいな。この人の体…\nどうして光力がこんなに弱いんだろう？）",
  ui_story_5031_50310201_25_dialog_content = "ごきげんよう、エルビス閣下。\n急に押しかけて、迷惑ではなかったかしら。",
  ui_story_5031_50310201_26_dialog_content = "もちろん問題はございません。ただ、事前に知らせていただければ、\nお迎えする準備をいたしましたのに…",
  ui_story_5031_50310201_27_dialog_content = "その必要はないわ。大事にしないために、直接訪ねたの。\nあまりかしこまらないで。",
  ui_story_5031_50310201_28_dialog_content = "私たちはただの観光客よ。\nこの地を訪れたのも気分転換のため。",
  ui_story_5031_50310201_29_dialog_content = "かしこまりました。\nすると、そちらが噂に名高い、空の末裔とバイスさんですね？",
  ui_story_5031_50310201_30_dialog_content = "こんにちは、PlayerNameです。",
  ui_story_5031_50310201_31_dialog_content = "バイスです。PlayerNameだけでなく、\n私のことまでご存知だとは…",
  ui_story_5031_50310201_32_dialog_content = "あ、あの！",
  ui_story_5031_50310201_33_dialog_content = "おや、そちらの方は？",
  ui_story_5031_50310201_34_dialog_content = "あたしは珍獣マスターのフィア！\nPlayerName、カレンお姉ちゃん、バイスお姉ちゃんのお友だちです！",
  ui_story_5031_50310201_35_dialog_content = "これは失礼…はじめまして。\n珍獣マスターのフィアさんですね。",
  ui_story_5031_50310201_36_dialog_content = "宴の用意をしております。領主としてのせめてもの礼儀です。\nどうか一緒にお召し上がりください。",
  ui_story_5031_50310201_37_dialog_content = "ほう…バイスさんは「<color=#FFB400>エメラルド号</color>」の\n催しに興味があるのですか？",
  ui_story_5031_50310201_38_dialog_content = "正直に申しますと、ちょうど「エメラルド号」で旅する\n「<color=#FFB400>マジックハンド・ビルサーカス団</color>」を招待しているのです。",
  ui_story_5031_50310201_39_dialog_content = "この夏、盛大な催しを開いてもらい、\nハーバーシティの民に特別な思い出を作ってほしいと思いまして。",
  ui_story_5031_50310201_40_dialog_content = "船がまるごとサーカス団のものなんですか？\n確かにとてもロマンチックですね…",
  ui_story_5031_50310201_41_dialog_content = "そうです。興味がおありでしたら、\n参加してみてはいかがですか？",
  ui_story_5031_50310201_42_dialog_content = "今の団長とは小さい頃に付き合いがありまして。\nしばらく会っていませんでしたが、腕前は確かですよ。",
  ui_story_5031_50310201_43_dialog_content = "きっと素晴らしい祭りにしてくれることでしょう。",
  ui_story_5031_50310201_44_dialog_content = "あ…船！",
  ui_story_5031_50310201_45_dialog_content = "あの、すみません！領主様のお友だちにお願いして、\n船の中を見せてもらうことはできますか？",
  ui_story_5031_50310201_46_dialog_content = "ほう？",
  ui_story_5031_50310201_47_dialog_content = "<size=33>フィア！なんで急に\nそんな変なことを聞いたの？</size>",
  ui_story_5031_50310201_48_dialog_content = "キャロから聞いたことを思い出したの。\nハーバーシティの港に大きくて怪しい船がとまってるって。",
  ui_story_5031_50310201_49_dialog_content = "「海雲クジラ」が消えたなら、誰かに捕まって、\nそういう船に閉じこめられている可能性が高いでしょ？",
  ui_story_5031_50310201_50_dialog_content = "申し訳ありませんが、\nそれはできないでしょうね。",
  ui_story_5031_50310201_51_dialog_content = "えっ、なんで？",
  ui_story_5031_50310201_52_dialog_content = "詳しい理由は私にも分かりかねますが、\nサーカス団のおきてらしいのです。",
  ui_story_5031_50310201_53_dialog_content = "実は昨日、報酬として補給する物資について、\n団長の「<color=#FFB400>ジェノ</color>」と相談しようとした時…",
  ui_story_5031_50310201_54_dialog_content = "てっきり船内を案内してもらえるかと思っていたのですが、\n船倉の前の廊下で打ち合わせようと言われました。",
  ui_story_5031_50310201_55_dialog_content = "私も不思議に思って、せっかく大きな船なのだから\n見学したいと申し出たのですが…",
  ui_story_5031_50310201_56_dialog_content = "「サーカス団のおきてで、船倉に入れるのはサーカス団の者だけ」\nと、断られてしまいました。",
  ui_story_5031_50310201_57_dialog_content = "友人であり、今回のスポンサーでもある私ですら、\nそういう扱いです。皆さんが入るのは難しいかと…",
  ui_story_5031_50310201_58_dialog_content = "どうしても船の中がご覧になりたい理由でもあるのですか？\n改めてジェノに相談してみても構いませんが…",
  ui_story_5031_50310201_59_dialog_content = "実は、フィアは…",
  ui_story_5031_50310201_60_dialog_content = "えへへ！不思議に思っただけです！\n船の中ってどうなってるのかな～と思って！",
  ui_story_5031_50310201_61_dialog_content = "<size=33>これは秘密の任務なの！\n超希少種の情報をあちこちで話しちゃダメ！</size>",
  ui_story_5031_50310201_62_dialog_content = "お気持ちは分かります。\nあれほど大きな船はめったに見られませんからね。",
  ui_story_5031_50310201_63_dialog_content = "カーニバルには好奇心で\n足を運ぶ方も多いはずです。",
  ui_story_5031_50310201_64_dialog_content = "ひとまず、ジェノに相談してみましょう。",
  ui_story_5031_50310201_65_dialog_content = "本当ですか！？\nありがとうございます！",
  ui_story_5031_50310201_66_dialog_content = "お安い御用です。ですが、あまり期待しないでください。\nすでに一度断られているわけですからね。",
  ui_story_5031_50310201_67_dialog_content = "甲板の上だけでもカーニバルやグルメバトル、\nサーカスのショーなど、にぎやかになりますよ。",
  ui_story_5031_50310201_68_dialog_content = "きっとフィアさんの好奇心を\n満たしてくれると思います。",
  ui_story_5031_50310201_69_dialog_content = "ゲホッ…ゴホゴホ…！",
  ui_story_5031_50310201_70_dialog_content = "エルビス様！",
  ui_story_5031_50310201_71_dialog_content = "大丈夫だ、パト。",
  ui_story_5031_50310201_72_dialog_content = "カレン殿下や皆さんのご訪問ですっかり舞い上がって、\n薬を飲むことを忘れてしまっていたようです。",
  ui_story_5031_50310201_73_dialog_content = "あなたは…",
  ui_story_5031_50310201_74_dialog_content = "…ていねいなおもてなしをありがとう、エルビス。",
  ui_story_5031_50310201_75_dialog_content = "とんでもない。\nどうか、私の失礼で気を悪くされませんように。",
  ui_story_5031_50310201_76_dialog_content = "まさか。どうかお大事に。",
  ui_story_5031_50310201_77_dialog_content = "これからエメラルド号へ向かって、話を聞いてみるわ。\nお見送りの礼は不要よ。",
  ui_story_5031_50310201_78_dialog_content = "…分かりました。カレン殿下への贈り物を用意しますので、\n後ほどエメラルド号でお会いしましょう。",
  ui_story_5031_50310201_79_dialog_content = "煩わしいしきたりなどではなく、君臣の礼として…\nカレン殿下には、どうかお受け取りいただきたく。",
  ui_story_5031_50310201_80_dialog_content = "そこまで言われては断れないわね。",
  ui_story_5031_50310201_81_dialog_content = "行きましょう、みんな。",
  ui_story_5031_50310201_82_dialog_content = "…",
  ui_story_5031_50310201_83_dialog_content = "エルビス様。",
  ui_story_5031_50310201_84_dialog_content = "パト、手下たちに今すぐ動くよう命令を。",
  ui_story_5031_50310201_85_dialog_content = "それは…まさか、白夜城に感づかれたのでしょうか？",
  ui_story_5031_50310201_86_dialog_content = "いや、今はまだ分からない。\nだが、目を離すわけにもいかん。",
  ui_story_5031_50310201_87_dialog_content = "いずれにせよ、\n決行は今日しかない。",
  ui_story_5031_50310201_88_dialog_content = "エルビス様、せんえつながら…\nジェノ団長に直接助けを求められてはいかがでしょうか？",
  ui_story_5031_50310201_89_dialog_content = "エルビス様の幼なじみなのでしょう？",
  ui_story_5031_50310201_90_dialog_content = "そう簡単なことではないのだ。\n昔の気持ちだけでジェノを信じるわけにもいかん。",
  ui_story_5031_50310201_91_dialog_content = "昨日、私がエメラルド号の中を見学したいと言った時も、\nきっぱりと断られた。",
  ui_story_5031_50310201_92_dialog_content = "私が調べた限り、今のジェノは\n「<color=#FFB400>真理結社</color>」という組織に忠誠を誓っているらしい。",
  ui_story_5031_50310201_93_dialog_content = "不用意に我らの目的を明かせば…\n計画そのものが台無しになりかねん。",
  ui_story_5031_50310201_94_dialog_content = "今の私は、かつての友を\nまだ信じていていいのかどうかも分からない…",
  ui_story_5031_50310201_95_dialog_content = "お察しいたします、エルビス様。\nここは私めにお任せください。",
  ui_story_5031_50310201_96_dialog_content = "ああ、私も引き続きジェノを探ってみよう。\n果たして私の知っている「あいつ」なのかどうか…",
  ui_story_5031_50310201_97_dialog_content = "エルビスさんっていい人そうだったね。\n手厚くもてなしてくれたし、僕やバイスにもすごく親切だったし。",
  ui_story_5031_50310201_98_dialog_content = "そうね。普通の貴族よりもずっと友好的だし、\nいばってるって感じもなかったわ。",
  ui_story_5031_50310201_99_dialog_content = "ええ。モドリー家は他の貴族とは違う。\n自分の民をとても大切にしていて、民からも愛されている。",
  ui_story_5031_50310201_100_dialog_content = "統治者としては非常に優れた一族と言えるわ。\nただ、惜しむらくは…",
  ui_story_5031_50310201_101_dialog_content = "もしかして、光力がすごく弱かったことと関係ある？",
  ui_story_5031_50310201_102_dialog_content = "気づいていたようね。彼が急にせき込んでいたでしょう。\nあれはただのカゼといった、軽い病ではないの。",
  ui_story_5031_50310201_103_dialog_content = "彼の顔にあった痕もそう…\nあれは「<color=#FFB400>モドリー失調症</color>」という病気よ。",
  ui_story_5031_50310201_104_dialog_content = "顔のあれも病気のせいだったのね…",
  ui_story_5031_50310201_105_dialog_content = "重い病気なの？",
  ui_story_5031_50310201_106_dialog_content = "私も詳しくはないの。\n歴史を勉強していた時、周辺知識として出てきただけよ。",
  ui_story_5031_50310201_107_dialog_content = "興味本位で資料も調べはしたけれど、\nモドリー失調症や一族に関する記録はほとんどなかったわ。",
  ui_story_5031_50310201_108_dialog_content = "分かっているのは、患者の光力が急激に衰弱し、\n長く続くと言う事だけ…",
  ui_story_5031_50310201_109_dialog_content = "もともと強い光力があればまだしも、並みの光力の持ち主では、\n発症すれば日常生活にも支障をきたすでしょうね。",
  ui_story_5031_50310201_110_dialog_content = "重篤な場合は、命も危ない。",
  ui_story_5031_50310201_111_dialog_content = "そんなにひどい病気なの！？",
  ui_story_5031_50310201_112_dialog_content = "ええ。ただ、きわめて特殊な病気で、ハーバーシティーの周辺でしか見られないの。\n風土病と考えている学者もいるわ。",
  ui_story_5031_50310201_113_dialog_content = "ハーバーシティの民たちは、この病気こそ\n「<color=#FFB400>英雄の血脈</color>」を継いでいる証拠だと信じているそうよ。",
  ui_story_5031_50310201_114_dialog_content = "かつて暗鬼退治に加わった先祖たちが、\n比類なき勇気をもって暗鬼の呪いを背負い、この病気をわずらった。",
  ui_story_5031_50310201_115_dialog_content = "そして彼らの血脈を受け継ぐ者も、\nその病に冒される可能性があるのだ、とね。",
  ui_story_5031_50310201_116_dialog_content = "幸い、最近は発症者は年々少なくなっているようだけれど…",
  ui_story_5031_50310201_117_dialog_content = "うーん、なるほどなるほど…",
  ui_story_5031_50310201_118_dialog_content = "ずいぶん物事を分かってるみたいな態度だね…",
  ui_story_5031_50310201_119_dialog_content = "そ、そりゃもう分かってるからに決まってるでしょ。\nフィアが小さいからってバカにしないで。",
  ui_story_5031_50310201_120_dialog_content = "とにかく、あの人は\n自分の宿命を誰よりも分かってるんだよ。",
  ui_story_5031_50310201_121_dialog_content = "フィアが珍獣マスターになることが\n運命なのと同じようにね。",
  ui_story_5031_50310201_122_dialog_content = "何世代にもわたって受け継がれてきたエーコーとデントーって言うのは、\n複雑で重いモノなんだよ。",
  ui_story_5031_50310201_123_dialog_content = "よそものが外から見ただけで、\n分かるようなことじゃないよ。",
  ui_story_5031_50310201_124_dialog_content = "道理ね。",
  ui_story_5031_50310201_125_dialog_content = "フィア、それっぽく言ってるだけじゃないの？\n僕には何を言いたいのか、よく分からないけど…",
  ui_story_5031_50310201_126_dialog_content = "エヘヘ。細かいことは気にしないの。\nとにかく今はエメラルド号に、早く行こ！",
  ui_story_5031_50310201_127_dialog_content = "早く「超希少種」を救出して任務を終わらせれば、\nフィアもみんなと一緒に遊べるもんね！",
  ui_story_5031_50310201_128_dialog_content = "引っ張らないでよ！\nまだ船の中に入れるかも分からないんだし…",
  ui_story_5031_50310201_129_dialog_content = "フィアの魅力じゃ通してくれないかな？",
  ui_story_5031_50310201_130_dialog_content = "魅力って…フィアなら動物に変装してショーに紛れ込んだ方が\nまだ成功率が高そうだよ。",
  ui_story_5031_50310201_131_dialog_content = "むぐーっ！",
  ui_story_5031_50310201_132_dialog_content = "またそうやって、\n背が低いことをバカにする！",
  ui_story_5031_50310201_133_dialog_content = "こっちに来なさい！",
  ui_story_5031_50310201_134_dialog_content = "何するの、フィア！？\n引っ張らないでってば！",
  ui_story_5031_50310201_135_dialog_content = "海に突き落として、\nキャロにボールみたいに頭突きさせてやるから！",
  ui_story_5031_50310201_136_dialog_content = "キャロってアザラシか何かなの？\nそんな扱いしたらキャロが悲しむよ！",
  ui_story_5031_50310201_137_dialog_content = "知らない知らない！！",
  ui_story_5031_50310201_138_dialog_content = "仲良くケンカだなんて、ほほえましいわね。\n私まで少しなごんでくるわ。",
  ui_story_5031_50310201_139_dialog_content = "そうね。こんなにゆっくりできるのは、\nずいぶん久しぶりよ。",
  ui_story_5031_50310201_140_dialog_content = "…気を付けて！",
  ui_story_5031_50310201_141_dialog_content = "カレン、どうしたの！？",
  ui_story_5031_50310201_142_dialog_content = "こんな海辺に…\nどうして暗鬼がいるの？",
  ui_story_5031_50310201_143_dialog_content = "みんな気をつけて。暗鬼たち、様子がおかしい！\nとにかく、戦う準備を！",
  ui_story_5031_50310202_1_dialog_content = "グァ…",
  ui_story_5031_50310202_2_dialog_content = "この暗鬼、なぜこんなに弱っていたのかしら…",
  ui_story_5031_50310202_3_dialog_content = "君たち、ケガはないか…",
  ui_story_5031_50310202_4_dialog_content = "あ、あなたは…カレン殿下！？\n殿下が暗鬼に襲われるなどと、面目次第もございません！",
  ui_story_5031_50310202_5_dialog_content = "あわてなくて結構。私たちは無防備な市民とは違う。\n自分の身ぐらい守れるわ。",
  ui_story_5031_50310202_6_dialog_content = "ただ…常に警戒しておくべきね。\n危険は陰に潜んでいるものよ。",
  ui_story_5031_50310202_7_dialog_content = "ははっ！ただちに見回りを強化し、\n海岸沿いに暗鬼が出没した理由を突き止めてみせます。",
  ui_story_5031_50310202_8_dialog_content = "それでいいわ。\n己の使命を果たしなさい。",
  ui_story_5031_50310202_9_dialog_content = "はっ！",
  ui_story_5031_50310202_10_dialog_content = "カレンお姉ちゃん…カッコいい！\nしゃべり方が本当に女王様みたい！",
  ui_story_5031_50310202_11_dialog_content = "そりゃそうよ。カレンは白夜城城主の娘だもの。\n将来はきっと優れた統治者になるわ。",
  ui_story_5031_50310202_12_dialog_content = "ありがとう…\nでも、私はまだまだ未熟よ。",
  ui_story_5031_50310202_13_dialog_content = "それより、「エメラルド号」はこの先よ。\n早く行きましょう。",
  ui_story_5031_50310202_14_dialog_content = "グルメバトルの参加希望者はこっちで～す！",
  ui_story_5031_50310202_15_dialog_content = "これが全部船の上で？\n人がたくさんいて、にぎやかだね。",
  ui_story_5031_50310202_16_dialog_content = "PlayerName、まずは情報を集めましょう。",
  ui_story_5031_50310202_17_dialog_content = "そうだね。",
  ui_story_5031_50310202_18_dialog_content = "こんにちは。カーニバルについて聞きたいんだけど…",
  ui_story_5031_50310202_19_dialog_content = "「マジックハンド・ビルのサーカス団」へようこそ～。",
  ui_story_5031_50310202_20_dialog_content = "私たちのサーカスは初めて～？\n遠慮はいらないよ～、こちらにどうぞ～！",
  ui_story_5031_50310202_21_dialog_content = "でも船の上で怪しい事はしないでね～？\nさもないと――",
  ui_story_5031_50310202_22_dialog_content = "メル姉、ジェノ団長に皆でお客さんの出迎えをするようにって言われたでしょ？\nサボっちゃダメだよ。",
  ui_story_5031_50310202_23_dialog_content = "ほらほら、あっちに姉さんの好きそーな顔のコがいるよ。\nアイサツしないと！",
  ui_story_5031_50310202_24_dialog_content = "ちょっと、サ、サプリ、\n押さないで…",
  ui_story_5031_50310202_25_dialog_content = "エヘヘ。でもほら、あの人、本当にそっくりだよ。\nもっと近くで見てみなって。",
  ui_story_5031_50310202_26_dialog_content = "えっ？似てるって…何の話？",
  ui_story_5031_50310202_27_dialog_content = "メル姉が切り抜きしてる、\n影ノ街のタブロイド記事の人！",
  ui_story_5031_50310202_28_dialog_content = "何か話してるの？",
  ui_story_5031_50310202_29_dialog_content = "待って…本当にそっくり。\nあなた、まさか…空の末裔？",
  ui_story_5031_50310202_30_dialog_content = "ええと、そうだよ。空の末裔だけど…\nどうして僕のことを知ってるの？",
  ui_story_5031_50310202_31_dialog_content = "――！！",
  ui_story_5031_50310202_32_dialog_content = "サプ姉、メル姉が逃げちゃったよ？",
  ui_story_5031_50310202_33_dialog_content = "とりあえずコイツ、捕まえとく？",
  ui_story_5031_50310202_34_dialog_content = "えっ？？",
  ui_story_5031_50310202_35_dialog_content = "フフフ…おもしろくなってきたね。ファム、ムチャはダメ。\nこの場はレインボー姐さんに任せて、メル姉を追いかけましょ。",
  ui_story_5031_50310202_36_dialog_content = "ええっ！？\nキミたち、またサボり？",
  ui_story_5031_50310202_37_dialog_content = "はぁ…ほんと～にごめんね。\nあの3人は臨時のお手伝いなの。",
  ui_story_5031_50310202_38_dialog_content = "カーニバルを見に来たんでしょ？",
  ui_story_5031_50310202_39_dialog_content = "あたしはサーカス団の司会者兼、受付係兼、警備員で…\n本職は見習い機関士の、レインボー！",
  ui_story_5031_50310202_40_dialog_content = "ずいぶん肩書きが色々あるのね…",
  ui_story_5031_50310202_41_dialog_content = "エヘヘ！皆にもよくすごいって言われるよ。",
  ui_story_5031_50310202_42_dialog_content = "お姉ちゃん、こんにちは！フィア、ちょっと聞きたいんだけど、\n船の中に入るにはどうすれば――むぐっ！",
  ui_story_5031_50310202_43_dialog_content = "直接聞いたって、\n素直に教えてくれるはずないでしょ…",
  ui_story_5031_50310202_44_dialog_content = "じゃ、じゃあ、どうすればいいの？",
  ui_story_5031_50310202_45_dialog_content = "ええと…こんにちは。\nカーニバルって、どうやって参加するの？",
  ui_story_5031_50310202_46_dialog_content = "カーニバルならまだ準備中だよ。\nお客さんは船の上で開始の合図を待ってればいいだけだよ？",
  ui_story_5031_50310202_47_dialog_content = "先にあたしたちの\nグルメバトルエリアでも見て来るといいよ。",
  ui_story_5031_50310202_48_dialog_content = "もうすぐあそこで熱～いバトルが始まるんだ。\nおもしろい屋台もたくさんあるよ。",
  ui_story_5031_50310202_49_dialog_content = "あっちの方にあるからね～。",
  ui_story_5031_50310202_50_dialog_content = "ありがとう。\n先にいろいろ回ってみるよ。",
  ui_story_5031_50310202_51_dialog_content = "さっきのサーカス団員…\n何か妙だったわね。",
  ui_story_5031_50310202_52_dialog_content = "特にあの三姉妹、PlayerNameに\nかなり興味を持っているようね。",
  ui_story_5031_50310202_53_dialog_content = "そうなの…？\n変な人に目をつけられたくないんだけどなぁ…",
  ui_story_5031_50310202_54_dialog_content = "僕の周り、ただでさえトラブル続きだからね…\n今日ぐらいは皆と一緒にのんびりしたいよ。",
  ui_story_5031_50310202_55_dialog_content = "うーん。どうすれば船の中に入れるのかな…",
  ui_story_5031_50310202_56_dialog_content = "せっかく話の通じそうなお姉さんを\n説得できそうだったのに…",
  ui_story_5031_50310202_57_dialog_content = "正直に話したら、\nそのまま海に落とされちゃうかもしれないよ。",
  ui_story_5031_50310202_58_dialog_content = "エルビスさんが言ってたでしょ。\nサーカス団の団員しか中に入れないんだって。",
  ui_story_5031_50310202_59_dialog_content = "とにかく、まずはここでできるだけ探ってみよう。\n何か見つかるかもしれないよ。",
  ui_story_5031_50310202_60_dialog_content = "…あれ、向こうの屋台…\n知ってる顔が何人もいる気がする…",
  ui_story_5031_50310202_61_dialog_content = "炎天下の夏にこそ、\n暑さをかき消す唯一無二の一皿を召し上がれ。",
  ui_story_5031_50310202_62_dialog_content = "新フレーバーの「<color=#FFB400>ハーバーシティ限定ひんやり味</color>」もありますよ。",
  ui_story_5031_50310202_63_dialog_content = "1度にかき氷10杯をご注文いただいたお客様には、\n空の末裔によるデザインのプリントされた保冷バッグを差し上げます。",
  ui_story_5031_50310202_64_dialog_content = "はい、そちらのうるわしいお嬢さん。\nかき氷10杯と保冷バッグですね。",
  ui_story_5031_50310202_65_dialog_content = "あれって…私が考えたかき氷屋じゃないの！\nあなたのデザインまで使われてるわ！？",
  ui_story_5031_50310202_66_dialog_content = "バイス…去年、訳も分からずクレーケンの\n「<color=#FFB400>技術譲渡契約書</color>」に署名したの、覚えてる？",
  ui_story_5031_50310202_67_dialog_content = "たぶん、あの結果がこれなんじゃないかな。",
  ui_story_5031_50310202_68_dialog_content = "これは…甘すぎるわね。",
  ui_story_5031_50310202_69_dialog_content = "バイスの作ったかき氷の方が\n重層的な味わいがあったわ。",
  ui_story_5031_50310202_70_dialog_content = "あ、あたしも1杯！",
  ui_story_5031_50310202_71_dialog_content = "ちょっと！？\nなんでそんなに迷わず買っちゃうの！？",
  ui_story_5031_50310202_72_dialog_content = "バイスがアイデアを盗まれて\n悲しんでるって言うのに…",
  ui_story_5031_50310202_73_dialog_content = "わ、私は気にしないで…\n皆が美味しいかき氷を食べられるなら、私は…うぅ…",
  ui_story_5031_50310202_74_dialog_content = "やっぱりクレーケンに契約書を\n破棄させてくるわ！！",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5031_50310202_76_dialog_content = "うーん！冷たい！",
  ui_story_5031_50310202_77_dialog_content = "一度にたくさん食べたら、\n頭が痛くなるわよ。",
  ui_story_5031_50310202_78_dialog_content = "バイスはまだクレーケンと交渉中かしら。\n何ごともないといいけれど。",
  ui_story_5031_50310202_79_dialog_content = "PlayerName！",
  ui_story_5031_50310202_80_dialog_content = "あれ、この声は…",
  ui_story_5031_50310202_81_dialog_content = "PlayerName、まさか本当にキミがいるとはな！",
  ui_story_5031_50310202_82_dialog_content = "フェラール？どうしてここに？",
  ui_story_5031_50310202_83_dialog_content = "ん？「ワンダーポット争奪戦」に出るんじゃないのか？\nもうすぐ始まるぞ。",
  ui_story_5031_50310202_84_dialog_content = "そうそう…パン作りを手伝ってもらったこと、\nお礼をいっておかないとな。",
  ui_story_5031_50310202_85_dialog_content = "あれからいろいろ考えたんだ。それで、自分の腕を磨くためにも、\nこの大会に参加して、あの美味しさを大陸に広めようと思ってな。",
  ui_story_5031_50310202_86_dialog_content = "お礼なんていいよ。グルメバトルのことはさっき聞いたけど…\n「<color=#FFB400>ワンダーポット</color>」って何？",
  ui_story_5031_50310202_87_dialog_content = "…いや、待って！\nまさかR・W砂漠の、料理の鉄人――",
  ui_story_5031_50310202_88_dialog_content = "「暗鬼肉質評論家」のジョニーおじさん…\nそう、あの人が使ってた「ワンダーポット」だ！",
  ui_story_5031_50310202_89_dialog_content = "カレンお姉ちゃん、\nジョニーおじさんって誰？",
  ui_story_5031_50310202_90_dialog_content = "R・W砂漠で流行している料理本の作者らしいわね。\n私も詳しくは知らないわ。",
  ui_story_5031_50310202_91_dialog_content = "その人の鍋がそんなにすごいの…？",
  ui_story_5031_50310202_92_dialog_content = "ジョニーおじさんは普通の料理人じゃないんだよ！\nその鍋で伝説のレシピをいくつも作ってるんだ！",
  ui_story_5031_50310202_93_dialog_content = "ま、まさか…\nジョニーおじさんがワンダーポット争奪戦に来てるの？",
  ui_story_5031_50310202_94_dialog_content = "いや、ジョニーおじさんはどこかで旅をしてるはず。\nじゃあ、「ワンダーポット争奪戦」って…",
  ui_story_5031_50310202_95_dialog_content = "そういうことさ。\n1位の賞品があの「ワンダーポット」なんだ！",
  ui_story_5031_50310202_96_dialog_content = "本人が来てるかどうかは分からないが、\nあの人の鍋を狙って、各地からツワモノが集まってるんだ。",
  ui_story_5031_50310202_97_dialog_content = "僕も出る！出場させて！",
  ui_story_5031_50310202_98_dialog_content = "あの鍋をバイスにプレゼントすれば、\n巨像にいるみんなが幸せになれる！！",
  ui_story_5031_50310202_99_dialog_content = "うわっ！PlayerName、急にどうしたの！？\n大声出して、興奮しすぎだよ。",
  ui_story_5031_50310202_100_dialog_content = "失礼、フェラール…\nちょっとPlayerNameと話をさせて。",
  ui_story_5031_50310202_101_dialog_content = "カレン、フィア、引っ張らないでよ！",
  ui_story_5031_50310202_102_dialog_content = "フェラール！待ってて！\n戻ってくるから！！",
  ui_story_5031_50310202_103_dialog_content = "そうか、待ってるぞ！",
  ui_story_5031_50310202_104_dialog_content = "PlayerName、俺はずっとここで待ってるからな！",
  ui_story_5031_50310202_105_dialog_content = "PlayerName…少しは落ち着いたかしら？",
  ui_story_5031_50310202_106_dialog_content = "ごめん、つい興奮しちゃって…",
  ui_story_5031_50310202_107_dialog_content = "はぁ…欲望に目がくらんだってこと？\nPlayerNameお兄ちゃんもまだまだだね～。",
  ui_story_5031_50310202_108_dialog_content = "やっと見つけたわ！\nどうしてこんなところにいるの？",
  ui_story_5031_50310202_109_dialog_content = "バイス！クレーケンとの交渉、どうだった？",
  ui_story_5031_50310202_110_dialog_content = "ダ、ダメだったわ…\nでも、かき氷をタダでたくさんもらって来たの！",
  ui_story_5031_50310202_111_dialog_content = "みんなで思いっきり食べて、この悔しさを忘れましょ！\nパクパクパク…",
  ui_story_5031_50310202_112_dialog_content = "ムシャムシャ…\nバイス、本当に怒ってるみたいだね…",
  ui_story_5031_50310202_113_dialog_content = "うーん――\n頭がズキズキする！",
  ui_story_5031_50310202_114_dialog_content = "一口でたくさん食べすぎだよ…\nうっ、僕も頭が痛くなってきた。",
  ui_story_5031_50310202_115_dialog_content = "…あれ？向こうにある階段って、\n下の階の…船室への入口になってる？",
  ui_story_5031_50310202_116_dialog_content = "えっ？どこどこ？",
  ui_story_5031_50310202_117_dialog_content = "本当にそうみたい…\nどうする？",
  ui_story_5031_50310202_118_dialog_content = "勝手に入るのは感心しないわね？",
  ui_story_5031_50310202_119_dialog_content = "もし海雲クジラを捕まえた悪者なら、\nあたしたちを素直に中に入れて調べさせてくれるはずないよ。",
  ui_story_5031_50310202_120_dialog_content = "とにかく…ノックしてみよっと。",
  ui_story_5031_50310202_121_dialog_content = "トントントン！もしも～し、\nすみません、中に入りま～す。",
  ui_story_5031_50310202_122_dialog_content = "ノックの音って口で出すの？",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>ガチャ――</color>",
  ui_story_5031_50310202_124_dialog_content = "あっ！！",
  ui_story_5031_50310202_125_dialog_content = "どなたでしょう？",
  ui_story_5031_50310202_126_dialog_content = "あ、あたしたちは\n通りすがりの観光客だよ！",
  ui_story_5031_50310202_127_dialog_content = "皆さんはあらゆる希望を捨て、\nこの扉をくぐる覚悟ができているのですか？",
  ui_story_5031_50310202_128_dialog_content = "そうでなければ立ち去ってください。",
  ui_story_5031_50310202_129_dialog_content = "…えっ？",
  ui_story_5031_50310202_130_dialog_content = "下の階は一般開放されていません！",
  ui_story_5031_50310202_131_dialog_content = "お戻りください。",
  ui_story_5031_50310202_132_dialog_content = "あっ、ごめんなさい！\nすぐ戻ります。",
  ui_story_5031_50310202_133_dialog_content = "ううっ…やっぱり、\n簡単には忍び込めないね。",
  ui_story_5031_50310202_134_dialog_content = "どうすれば…",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>バタン――！</color>",
  ui_story_5031_50310202_136_dialog_content = "「ご乗船の皆さま、競技イベントの準備が整いました」",
  ui_story_5031_50310202_137_dialog_content = "「出場される方は、指定の場所で説明をお聞きの上、\nエントリーしてください」",
  ui_story_5031_50310202_138_dialog_content = "「出場者には、サーカス団の一員として体験活動に参加する権利や、\n高額の白夜コインを獲得するチャンスのほか…」",
  ui_story_5031_50310202_139_dialog_content = "「数々の試練を乗り越え、見事1位を獲得された方には、\n団長より直々に豪華な賞品が手渡されます」",
  ui_story_5031_50310202_140_dialog_content = "サーカス団員の体験中なら…\n船の中に入れるのかしら？",
  ui_story_5031_50310202_141_dialog_content = "悪くない考えね。",
  ui_story_5031_50310202_142_dialog_content = "行ってみよう。",
  ui_story_5031_50310202_143_dialog_content = "この人の多さはなんたることだ！？",
  ui_story_5031_50310202_144_dialog_content = "チッ、庶民どもめ、\nミツバチ同然に押し寄せてきやがって！",
  ui_story_5031_50310202_145_dialog_content = "我は貴族！裁判官マシューであるぞ！\n庶民ども、下がれ下がれぃ！！",
  ui_story_5031_50310202_146_dialog_content = "…",
  ui_story_5031_50310202_147_dialog_content = "ええい騒々しい、あっちへ行け！",
  ui_story_5031_50310202_148_dialog_content = "チッ…ローウェイ、\nお前の静かさもシャクにさわって来たわ。",
  ui_story_5031_50310202_149_dialog_content = "カレン、あそこの2人、\n白夜城の人みたいだよ。",
  ui_story_5031_50310202_150_dialog_content = "法廷の人のようね…\n関わらずにおきましょう。",
  ui_story_5031_50310202_151_dialog_content = "バイス～！カレンとPlayerNameも！\nあれ、そっちの子は誰？",
  ui_story_5031_50310202_152_dialog_content = "ガルー先輩！\nええと、この子は…",
  ui_story_5031_50310202_153_dialog_content = "あたしは珍獣マスターのフィア！\nよろしくお願いします！",
  ui_story_5031_50310202_154_dialog_content = "へぇ、いい子みたいね～。うんうん。\n空の末裔、子どもにヘンなこと教えちゃダメだよ？",
  ui_story_5031_50310202_155_dialog_content = "余計なお世話だよ！",
  ui_story_5031_50310202_156_dialog_content = "ガルー先輩、どうしてここに？",
  ui_story_5031_50310202_157_dialog_content = "あたしだけじゃないよ。\nバイスのかわいい後輩も来てるよ――",
  ui_story_5031_50310202_158_dialog_content = "あ…こ…こんにちは。あたしはシエル…\nバイス先輩と同じ学校にいたの。",
  ui_story_5031_50310202_159_dialog_content = "ええと…？",
  ui_story_5031_50310202_160_dialog_content = "久しぶり！PlayerNameと行動するようになってから、\nほとんど会ってなかったわね。",
  ui_story_5031_50310202_161_dialog_content = "シエルは少し人見知りなのよ。",
  ui_story_5031_50310202_162_dialog_content = "ちょっと自信なさそうだけど\n学校では「エンジニアリングの天才」って言われてたの！",
  ui_story_5031_50310202_163_dialog_content = "そうなんだ。まぁ、すごい人って皆、\nどこかしら変わってる気がするしね…",
  ui_story_5031_50310202_164_dialog_content = "それで、ガルーとシエルも遊びにきたの？",
  ui_story_5031_50310202_165_dialog_content = "ハズレ～。遊びにきたなら、\nもっとかわいい服でも着てるよ。",
  ui_story_5031_50310202_166_dialog_content = "空の末裔が分からないのはともかく、\nバイスもまだ気づいてないの？",
  ui_story_5031_50310202_167_dialog_content = "この船、こんなに大きいんだよ？\nきっと構造だってすごく複雑で、最先端なはずでしょ。",
  ui_story_5031_50310202_168_dialog_content = "だから船のことを知ってすぐにシエルを捕まえて、\n調査しに来たってわけ。",
  ui_story_5031_50310202_169_dialog_content = "でも、船の中には入れないみたいだし、\n外から調査しただけじゃ役に立つ情報は大して手に入らないでしょ？",
  ui_story_5031_50310202_170_dialog_content = "せっかくだし、大会に出ることにしたの！",
  ui_story_5031_50310202_171_dialog_content = "じゃあ、バイスもガルーたちの手伝いに行く？",
  ui_story_5031_50310202_172_dialog_content = "その必要はないよ～。巨像パーティをバラバラにしたくないし。\nルール的にはチームの人数もちゃんと考慮されてるらしいの。",
  ui_story_5031_50310202_173_dialog_content = "何より、シエルの実力なら\nバイスに引けを取らないよ！",
  ui_story_5031_50310202_174_dialog_content = "が、ガンバリマス…",
  ui_story_5031_50310202_175_dialog_content = "それじゃあ、私たちは先に行って準備してるね。\nまたね～。",
  ui_story_5031_50310202_176_dialog_content = "う～ん、強そうなライバルが\n増えちゃった…",
  ui_story_5031_50310202_177_dialog_content = "大会の説明はまだ始まらないの！？",
  ui_story_5031_50310202_178_dialog_content = "あっ、ステージに2人上がってきた！",
  ui_story_5031_50310202_179_dialog_content = "エルビスと…さきほど見た、黒ずくめの人ね。",
  ui_story_5031_50310202_180_dialog_content = "ゲホッ…エヘン、エヘン…",
  ui_story_5031_50310202_181_dialog_content = "親愛なるハーバーシティの民たち、\nそして遠方よりお越しの方々、ようこそ来てくれた。",
  ui_story_5031_50310202_182_dialog_content = "私はハーバーシティの領主、\nエルビス・モドリー。",
  ui_story_5031_50310202_183_dialog_content = "エルビス様！",
  ui_story_5031_50310202_184_dialog_content = "エルビス様バンザイ！\nエルビス様バンザイ！！",
  ui_story_5031_50310202_185_dialog_content = "皆、ありがとう。\nこの炎天下の中、海の伝説――",
  ui_story_5031_50310202_186_dialog_content = "かの有名なマジックハンド・ビルサーカス団を招待して、\nショーを開催してもらうことができ、とても光栄だ。",
  ui_story_5031_50310202_187_dialog_content = "マジックハンド・ビルサーカス団の団長、ジェノ・グレガーです。\n皆様、サーカスへようこそ。",
  ui_story_5031_50310202_188_dialog_content = "不正行為を防ぐため、\nルールは各チャレンジの前に改めて発表させていただきます。",
  ui_story_5031_50310202_189_dialog_content = "すべてのチャレンジを突破した方は、\n一日団員としてサーカスのショーに出演できるほか…",
  ui_story_5031_50310202_190_dialog_content = "僕が直々に用意した貴重な賞品を\nお渡しいたします。",
  ui_story_5031_50310202_191_dialog_content = "サーカス団はどこも不思議な品をたくさん集めているという、\nもっぱらのウワサがあるようですが…",
  ui_story_5031_50310202_192_dialog_content = "我らマジックハンド・ビルサーカス団も\nむろん例外ではありません。",
  ui_story_5031_50310202_193_dialog_content = "僕たちは航海しながら、サーカスの奥義を探求するべく修行しています。\n同時に、大海原（おおうなばら）から啓示を得るのです。",
  ui_story_5031_50310202_194_dialog_content = "そして、海は僕たちに珍しい宝物を数多く与えてくれます――\n今回の賞品も、その一つです。",
  ui_story_5031_50310202_195_dialog_content = "それが何かにつきましては、どうぞ、想像と期待を膨らませてください。\n決して皆様の期待を裏切らないとお約束いたします。",
  ui_story_5031_50310202_196_dialog_content = "おおお！\nすげぇ値打ちのありそうな感じだな！",
  ui_story_5031_50310202_197_dialog_content = "大もうけできそうだ！",
  ui_story_5031_50310202_197X1_dialog_content = "海から与えられた、珍しい宝物…\n分かった！",
  ui_story_5031_50310202_197X2_dialog_content = "きっと海雲――むぐっ！",
  ui_story_5031_50310202_197X3_dialog_content = "シーッ！声が大きいよ。正体を明かして、\nライバルの注目を引き寄せるつもり？",
  ui_story_5031_50310202_197X4_dialog_content = "むむむ…分かった。じゃあ、実力で試合に勝って、\n海雲クジラを助けよう！",
  ui_story_5031_50310202_198_dialog_content = "しかし、審判が1人だけでは、\n皆さんも納得できないことがあるかもしれません。",
  ui_story_5031_50310202_199_dialog_content = "そこで、ハーバーシティの民の敬愛を一心に受けておられる\n領主エルビス様にも、同じく審判をお願いしたいと思います。",
  ui_story_5031_50310202_200_dialog_content = "領主様！領主様！",
  ui_story_5031_50310202_201_dialog_content = "これは…ジェノ、打ち合わせになかったぞ？",
  ui_story_5031_50310202_202_dialog_content = "何かまずいことが？たまにはわずらわしい政務を忘れ、\n楽しむぐらいの権利はあってもよいでしょう。",
  ui_story_5031_50310202_203_dialog_content = "領主様！領主様！",
  ui_story_5031_50310202_204_dialog_content = "…うむ、分かった。",
  ui_story_5031_50310202_205_dialog_content = "皆、存分に楽しむがいい！",
  ui_story_5031_50310301_0_dialog_content = "ええと、このひもはここに通して…",
  ui_story_5031_50310301_0X1_dialog_content = "あれ？こ、ここにももう1本ある！",
  ui_story_5031_50310301_0X2_dialog_content = "これは、うう～ん…反対側から通せばいいのかしら？",
  ui_story_5031_50310301_0X3_dialog_content = "バイス、お疲れ様。",
  ui_story_5031_50310301_0X4_dialog_content = "大丈夫よ、カレン、もうちょっと待ってて。\nあと少しで出来るから。",
  ui_story_5031_50310301_0X5_dialog_content = "ええ、急がなくていいのよ。",
  ui_story_5031_50310301_0X6_dialog_content = "うん、ここに通して…これでよし！",
  ui_story_5031_50310301_0X7_dialog_content = "あら、ちょっと違うみたい…",
  ui_story_5031_50310301_0X8_dialog_content = "…バイス。",
  ui_story_5031_50310301_0X9_dialog_content = "え？どうしたの、痛かった？",
  ui_story_5031_50310301_0X10_dialog_content = "いいえ、ただ…聞きたいことがあるの。\n踏み込みすぎていないといいのだけれど。",
  ui_story_5031_50310301_0X11_dialog_content = "え？「踏み込んだ質問」？",
  ui_story_5031_50310301_0X12_dialog_content = "ええ…新しい力に目覚めるって…どんな感覚なのかしら？",
  ui_story_5031_50310301_0X13_dialog_content = "なんだ、特に踏み込んだ質問でもないわよ。",
  ui_story_5031_50310301_0X14_dialog_content = "ちょっと右腕をあげて。",
  ui_story_5031_50310301_0X15_dialog_content = "え？ええ。",
  ui_story_5031_50310301_0X16_dialog_content = "でも、その質問は答えるのが難しいわね。",
  ui_story_5031_50310301_0X17_dialog_content = "答えたくないってことじゃなくて、\n言葉で伝えるのが難しいの。",
  ui_story_5031_50310301_0X18_dialog_content = "分かるわ。",
  ui_story_5031_50310301_0X19_dialog_content = "私自身の感覚でいうなら、\n眠っていた力があるきっかけで爆発したって感じかしら。",
  ui_story_5031_50310301_0X20_dialog_content = "光力に対する感覚も、前とはまったく違ってる。\nでも、リスクもあるわ。",
  ui_story_5031_50310301_0X21_dialog_content = "「リスク」？",
  ui_story_5031_50310301_0X22_dialog_content = "あの時は、まるで底なしの闇に落ちたみたいで…\n永遠に目を覚まさないかもって、一度は思ったわ。",
  ui_story_5031_50310301_0X23_dialog_content = "少しでも気を抜くと自分を見失ってしまう気がして…\n今までの自分を一生懸命思い出して、考え続けたの。",
  ui_story_5031_50310301_0X24_dialog_content = "それから、不思議な光景をたくさん見たの。\nまるで自分がそこにいるみたいな感覚…",
  ui_story_5031_50310301_0X25_dialog_content = "現実そっくりの幻覚に、\n試されてるみたいだったわ。",
  ui_story_5031_50310301_0X26_dialog_content = "でも、私は意識の海の中で、\n一筋の光をつかむことができたから、最後までがんばることができたの。",
  ui_story_5031_50310301_0X27_dialog_content = "そうだったのね。\n眠っていた力が爆発するような感覚…",
  ui_story_5031_50310301_0X28_dialog_content = "ええ、私はそう思ってるわ。",
  ui_story_5031_50310301_0X29_dialog_content = "実際、光霊の力って、\nたいてい危険にさらされた時に目覚めるものよね。",
  ui_story_5031_50310301_0X30_dialog_content = "私も同じような状況だったと思うわ。",
  ui_story_5031_50310301_0X31_dialog_content = "ただ、私も新しい力を完全に使いこなせてはいないし…",
  ui_story_5031_50310301_0X32_dialog_content = "まだ日が浅いのよ。\n時間が経てば、きっと使いこなせるようになるわ。",
  ui_story_5031_50310301_0X33_dialog_content = "うん、そうよね！",
  ui_story_5031_50310301_0X34_dialog_content = "もしカレンも試してみたいなら、\n意識を…落としてみたら？",
  ui_story_5031_50310301_0X35_dialog_content = "「意識を落とす」？",
  ui_story_5031_50310301_0X36_dialog_content = "そう、力を出すときに、私はいつもそうやってるの。\n毎回成功するわけじゃないけどね。",
  ui_story_5031_50310301_0X37_dialog_content = "そうだったのね。よくわかったわ。",
  ui_story_5031_50310301_0X38_dialog_content = "今度私も試してみるわ。\nありがとう、バイス。",
  ui_story_5031_50310301_0X39_dialog_content = "どういたしまして！",
  ui_story_5031_50310301_0X40_dialog_content = "これでよしっと。\n最後の1本、ようやく結び終わったわ！",
  ui_story_5031_50310301_0X41_dialog_content = "はぁ…貴族の服って、\n着るだけでもこんなに大変なのね。",
  ui_story_5031_50310301_0X42_dialog_content = "それにこの服、特別な生地で作られてるみたいね。\n啓光では見たこともないわ。",
  ui_story_5031_50310301_0X43_dialog_content = "私も初めて見るわ。\nハーバーシティの特産かもしれないわね。",
  ui_story_5031_50310301_0X44_dialog_content = "ドレスのたぐいはハーバーシティの\n代表的産業の1つでもあるから。",
  ui_story_5031_50310301_0X45_dialog_content = "バイス、手間をかけたわね。",
  ui_story_5031_50310301_0X46_dialog_content = "大丈夫よ。それにしても、\nカレンに似合ってるわ！",
  ui_story_5031_50310301_0X47_dialog_content = "早くPlayerNameとフィアちゃんに見せてあげましょ？\nきっとビックリするわ！",
  ui_story_5031_50310301_1_dialog_content = "カレン、なんでまだ戻って来ないんだろう…",
  ui_story_5031_50310301_2_dialog_content = "女の子の着替えは時間がかかるものなんだよ。\nそれにあのドレス、着るの大変そうだったし。",
  ui_story_5031_50310301_2X1_dialog_content = "バイスお姉ちゃんが手伝ってくれてるとしても、\n時間かかるよ。",
  ui_story_5031_50310301_3_dialog_content = "…それもそうか。貴族の服って、\n誰かが手伝わないと着られないような感じがするしね…",
  ui_story_5031_50310301_4_dialog_content = "君も手伝いに行ってもらえない？",
  ui_story_5031_50310301_5_dialog_content = "何？あたしに命令する気？\n召使いだとでも思ってるの？",
  ui_story_5031_50310301_6_dialog_content = "うまくすれば、カレンとバイスが\nもっとがんばって「海雲クジラ」を探してくれるかもよ？",
  ui_story_5031_50310301_7_dialog_content = "わ、分かった。\n着替えなんて手伝ったことないけど…やってみるよ。",
  ui_story_5031_50310301_8_dialog_content = "PlayerName、フィアちゃんをからかっちゃダメよ。",
  ui_story_5031_50310301_9_dialog_content = "ごめんなさい。\nずいぶん待たせてしまったわね…",
  ui_story_5031_50310301_10_dialog_content = "うわぁ！カレンお姉ちゃん、\nすっごく――きれい！",
  ui_story_5031_50310301_11_dialog_content = "でしょ！着心地と動きやすさを兼ね備えてるみたいなの。\nカレンによく似合ってると思わない？",
  ui_story_5031_50310301_12_dialog_content = "ありがとう、みんな。ハーバーシティは、\nドレス職人や仕立て屋が多くいることでも有名なの。",
  ui_story_5031_50310301_13_dialog_content = "このドレスもさすがの着心地だわ。",
  ui_story_5031_50310301_14_dialog_content = "PlayerName、どう思う？",
  ui_story_5031_50310301_15_dialog_content = "あっ、ごめん。完全に見とれてたよ。\nつまり、その――",
  ui_story_5031_50310301_16_dialog_content = "美しく、優雅で、力強い！",
  ui_story_5031_50310301_17_dialog_content = "さすがはソルラド殿下のご息女。\n感動するほど優雅なお姿であらせられます。",
  ui_story_5031_50310301_18_dialog_content = "大げさよ…\nでも、ありがとう、エルビス。",
  ui_story_5031_50310301_19_dialog_content = "謙そんされる必要はありません。まるでソルラド家の\n気高き正義と不屈の精神を体現されているようです。",
  ui_story_5031_50310301_20_dialog_content = "そのドレスが殿下に幸運をもたらし、\n大会でも優勝できることを願っておりますよ。",
  ui_story_5031_50310301_21_dialog_content = "私はまだ、主催者としての仕事がありますので。\n後ほどお会いしましょう。",
  ui_story_5031_50310301_22_dialog_content = "あっ、ごめん。カレンの新しいドレス、\n何か言う前に…",
  ui_story_5031_50310301_23_dialog_content = "エルビスさんに全部言われちゃったよ。",
  ui_story_5031_50310301_24_dialog_content = "ええ、でも、口に出す必要はなかったわ。",
  ui_story_5031_50310301_25_dialog_content = "あなたの目が十分に物語っていたから。",
  ui_story_5031_50310301_26_dialog_content = "えっ？",
  ui_story_5031_50310301_27_dialog_content = "皆さ～ん！レインボーの説明タイムだよ！",
  ui_story_5031_50310301_28_dialog_content = "あたしはサーカス団の司会者兼、受付係兼、警備員！\nそして本職は見習い機関士！レインボーだよ！",
  ui_story_5031_50310301_29_dialog_content = "今回のカーニバルの司会者は\nあたしが務めさせていただきま～す！",
  ui_story_5031_50310301_30_dialog_content = "最初の試合は、\nまずレインボー特製のウォーターガンを受け取ってね。",
  ui_story_5031_50310301_31_dialog_content = "光力を水にして発射できる、\nとっても便利なウォーターガンだよ！",
  ui_story_5031_50310301_32_dialog_content = "ルールも超簡単！ウォーターガンで\nジェノ団長が指定したターゲットを攻撃すれば得点！",
  ui_story_5031_50310301_33_dialog_content = "ただし、試合中は他の選手やチームへの攻撃もアリ！",
  ui_story_5031_50310301_34_dialog_content = "最終スコアの上位5チームが次の試合に進めるよ。\n敗退したチームはそのまま海にドボン！",
  ui_story_5031_50310301_35_dialog_content = "ってことで、泳げないお客さんは参加しないか…\n少なくとも、浮き輪を用意してから参加してね！",
  ui_story_5031_50310301_36_dialog_content = "この試合では参加チームの人数に制限はナシ！\nチーム全員の平均点が最終スコアになるよ！",
  ui_story_5031_50310301_37_dialog_content = "おう姉ちゃん、そんなルールじゃ\n俺たちに有利すぎるぜ！",
  ui_story_5031_50310301_38_dialog_content = "ジョナとアズールのアネキが本気を出せば、\n1位はほぼ間違いなく俺たちのモンだ！",
  ui_story_5031_50310301_39_dialog_content = "水鉄砲ねぇ？子どもの遊びみたいだが、\n賞品のために参加してやるか。",
  ui_story_5031_50310301_40_dialog_content = "どうせヒマなんだし、\nちょっと遊んであげようかしら？",
  ui_story_5031_50310301_41_dialog_content = "ヘッヘッヘ…\nこりゃ楽勝間違いなしだ！",
  ui_story_5031_50310301_42_dialog_content = "喜ぶのはまだ早いぞ。\nお前ら2人はまだ新入りだろう？",
  ui_story_5031_50310301_43_dialog_content = "俺たちのオキテをしっかり頭に叩き込んどきな！\n外でR・Wの名前にドロを塗るんじゃないぞ。",
  ui_story_5031_50310301_44_dialog_content = "安心してくだせぇ、\n俺も兄弟も忘れちゃいませんって！",
  ui_story_5031_50310301_45_dialog_content = "ほら…アレとアレっすよね？\nしっかり覚えてますって！",
  ui_story_5031_50310301_46_dialog_content = "みんな～、ルールは分かったかな～？",
  ui_story_5031_50310301_47_dialog_content = "はーい！！",
  ui_story_5031_50310301_48_dialog_content = "待って！ウォーターガンに光力が必要なら、\n僕はただの的になっちゃうよ。",
  ui_story_5031_50310301_49_dialog_content = "うーん、空の末裔のことまで考えてなかったね。",
  ui_story_5031_50310301_50_dialog_content = "メル姉、空の末裔のチームを手伝ってあげたら？",
  ui_story_5031_50310301_51_dialog_content = "そ、そんなのダメよ…\n私たちは試合に参加できないの…",
  ui_story_5031_50310301_52_dialog_content = "はぁ…ホントに分かんない。あんなモヤシのどこがいいの？\nあたしはもっとムキムキの方が…",
  ui_story_5031_50310301_53_dialog_content = "団長～、空の末裔はどうする？",
  ui_story_5031_50310301_54_dialog_content = "ハンディキャップとして扱いましょう。\nそちらのお嬢さんと2人で1人分ということで。",
  ui_story_5031_50310301_55_dialog_content = "えっ！？どうしてあたしと\n空の末裔が2人で1人分になるの！？",
  ui_story_5031_50310301_56_dialog_content = "では、2人分でカウントしましょうか？",
  ui_story_5031_50310301_57_dialog_content = "うっ…フ、フィア、まだ小さいし力もないから\n半人前でも当然だよね！！",
  ui_story_5031_50310301_58_dialog_content = "異議がないようですので、\nそろそろターゲットを呼び出しましょう――",
  ui_story_5031_50310301_59_dialog_content = "さあ、皆さん！\nこの狂気に拍手と喝采を！",
  ui_story_5031_50310301_60_dialog_content = "地獄の野獣たちよ！\n雄叫びをあげるのだ！",
  ui_story_5031_50310301_61_dialog_content = "待って、団長が呼ぼうとしてるのって…",
  ui_story_5031_50310301_62_dialog_content = "は、早くレインボー姐さんの目をふさいで！\n暗鬼を見たらまた…！",
  ui_story_5031_50310301_63_dialog_content = "グアアッ！",
  ui_story_5031_50310301_64_dialog_content = "暗鬼だと！？",
  ui_story_5031_50310301_65_dialog_content = "暗鬼…！？",
  ui_story_5031_50310301_66_dialog_content = "ファム！早くレインボー姐を押さえつけて！\n暴走しちゃう！！",
  ui_story_5031_50310301_67_dialog_content = "団長のバカ！\nなんで暗鬼なんか呼び出したの！？",
  ui_story_5031_50310301_68_dialog_content = "フッ…今日の風に合っていたからです。",
  ui_story_5031_50310301_69_dialog_content = "PlayerName、フィア、私とバイスの後ろに。",
  ui_story_5031_50310301_70_dialog_content = "皆さん、ご心配なく。\nこの暗鬼たちは僕が「<color=#FFB400>始原</color>」の力を用いて作り出した幻影です。",
  ui_story_5031_50310301_71_dialog_content = "僕は自分が持つ能力を利用して暗鬼と戦い、\n彼らの「始原」を分析してきました。",
  ui_story_5031_50310301_72_dialog_content = "そして「<color=#FFB400>始原のカード</color>」の力によって、\n生き生きとした幻影を作り出すことに成功したのです。",
  ui_story_5031_50310301_73_dialog_content = "グアアア――",
  ui_story_5031_50310301_74_dialog_content = "グアアア――",
  ui_story_5031_50310301_75_dialog_content = "ご覧の通り、幻影はすべて僕が操っています。\n射撃のマトとして、これ以上のものはないでしょう？",
  ui_story_5031_50310301_76_dialog_content = "それでは、試合開始を宣言します！",
  ui_story_5031_50310401_1_dialog_content = "おいあんたら、サボるんじゃないぞ。散らばって暗鬼を探せ。\n1位は絶対に俺たちR・Wのものだ！",
  ui_story_5031_50310401_2_dialog_content = "ウッス、アネキ！\n…それで、光霊に出くわしたらどうしますか？",
  ui_story_5031_50310401_3_dialog_content = "どうするだと？\n俺たちはR・Wだぜ？",
  ui_story_5031_50310401_4_dialog_content = "R・Wの名を汚すようなことはするな…\n片っ端から撃ちまくって、海に落としてやれ！",
  ui_story_5031_50310401_5_dialog_content = "ヒャッハー！",
  ui_story_5031_50310401_6_dialog_content = "ムチャするわねぇ、ジョナ。",
  ui_story_5031_50310401_7_dialog_content = "どうした？撃ちたくないオトコでもいたか？",
  ui_story_5031_50310401_8_dialog_content = "そうねぇ…確かにかわいいコだけど、\n賞品の魅力に比べるとね…",
  ui_story_5031_50310401_9_dialog_content = "もう…なんでこんなところに銃のプロの\nジョナとアズールがいるの！？",
  ui_story_5031_50310401_10_dialog_content = "暗鬼を撃つだけで点がもらえるはずなのに、\nR・Wの人たち、ずっと他の人を狙ってる！！",
  ui_story_5031_50310401_11_dialog_content = "ジェノが遮へい物の幻影も作ってなかったら、\nとっくに海に落とされてるところだったよ。",
  ui_story_5031_50310401_12_dialog_content = "このまま後手に回っていては、包囲される…\n続いて！私が突破口を切り開く！",
  ui_story_5031_50310401_13_dialog_content = "待って！カレン！",
  ui_story_5031_50310401_14_dialog_content = "無法者どもめ！我が槍を――\n違ったわ。銃を味わいなさい！",
  ui_story_5031_50310401_15_dialog_content = "ぐわあぁぁ！！",
  ui_story_5031_50310401_16_dialog_content = "ア、アニキ！？",
  ui_story_5031_50310401_17_dialog_content = "これで2人！皆、急いで！",
  ui_story_5031_50310401_18_dialog_content = "強い…カレンの「アイスガンブロッサム」が命中して、そのまま海に落ちた。\nあっ！カレン！危ない！隠れて！",
  ui_story_5031_50310401_19_dialog_content = "PlayerName、今こそ突破のチャンスよ！",
  ui_story_5031_50310401_20_dialog_content = "カレン、1人で深入りしすぎよ！\nそれじゃ――",
  ui_story_5031_50310401_21_dialog_content = "捕まえたぜ、白夜城のプリンセス。",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>バンッ――</color>",
  ui_story_5031_50310401_23_dialog_content = "――！！",
  ui_story_5031_50310401_24_dialog_content = "カレン！",
  ui_story_5031_50310401_25_dialog_content = "た、助かったわ…PlayerName。",
  ui_story_5031_50310401_26_dialog_content = "カレンが無事ならいいよ。\nジョナっておもちゃの銃でもこんなに手強いんだ…",
  ui_story_5031_50310401_27_dialog_content = "うぅっ！R・Wめ～！ムカつく！\nあたしたちにつきまとわないでよ！",
  ui_story_5031_50310401_28_dialog_content = "ダメだ。何とかして状況を打開しないと…",
  ui_story_5031_50310401_29_dialog_content = "激しい試合になりましたね。",
  ui_story_5031_50310401_30_dialog_content = "そうだな。\nお前がこんな力を使うとは思いもしなかったが。",
  ui_story_5031_50310401_31_dialog_content = "真理結社から得た力ですよ…",
  ui_story_5031_50310401_32_dialog_content = "ああ、白夜城の貴族に名を連ねているのなら、\n悪いウワサもいろいろと聞いているのでは？",
  ui_story_5031_50310401_33_dialog_content = "「始原」というのは、ショーの演出のために\n作り出した言葉にすぎません。",
  ui_story_5031_50310401_34_dialog_content = "実のところ、私が持つエネルギー変換の力でしかないのです。\n長い間そう呼んでいるので、つい呼び名に慣れてしまいました。",
  ui_story_5031_50310401_35_dialog_content = "私に真理結社への偏見は特にない。\nその点は安心するがいい。",
  ui_story_5031_50310401_36_dialog_content = "だが、なぜ暗鬼なのだ？",
  ui_story_5031_50310401_37_dialog_content = "参加者は誰もがスリルと刺激を求め、\nカーニバルやサーカスに足を運ぶのです。",
  ui_story_5031_50310401_38_dialog_content = "ならば、暗鬼の登場は必然と言って良いのでは？",
  ui_story_5031_50310401_39_dialog_content = "商売に染まったな。\nずいぶん考えをめぐらせるようになった。",
  ui_story_5031_50310401_40_dialog_content = "いえいえ…これでも、サーカス団を率いている身ですから。",
  ui_story_5031_50310401_41_dialog_content = "失礼します、エルビス様。",
  ui_story_5031_50310401_42_dialog_content = "パトか。\nではジェノ、そろそろ失礼するよ。",
  ui_story_5031_50310401_43_dialog_content = "何か分かったか？",
  ui_story_5031_50310401_44_dialog_content = "はい。調べた結果、エルビス様の説明と\n一致する部屋がありました。",
  ui_story_5031_50310401_45_dialog_content = "そうか！ならば…",
  ui_story_5031_50310401_46_dialog_content = "ですが、その部屋に見たこともない錠前がかけられており…\n無理に破ろうとすれば警報が鳴るものだと思われます。",
  ui_story_5031_50310401_47_dialog_content = "分かった。ならばまず、扉を開けられる鍵を探せ。",
  ui_story_5031_50310401_48_dialog_content = "鍵はおそらくジェノの部屋にあるか、持ち歩いているかだろう。\n手分けして行動しよう。",
  ui_story_5031_50310401_49_dialog_content = "エルビス！",
  ui_story_5031_50310401_50_dialog_content = "お邪魔でしたか？また得点をしたチームがあります。\n観客たちが領主様による裁定を求めて、歓声をあげていますよ。",
  ui_story_5031_50310401_51_dialog_content = "領主様！領主様――！",
  ui_story_5031_50310401_52_dialog_content = "すまない、ジェノ。\nパトへのこと付けを済ませたら戻る。",
  ui_story_5031_50310401_53_dialog_content = "エルビス様、どういたしましょうか？",
  ui_story_5031_50310401_54_dialog_content = "船倉の捜索はお前の部下に任せる。",
  ui_story_5031_50310401_55_dialog_content = "この状況で私が長く席を外せば、\nジェノに疑われてしまう。",
  ui_story_5031_50310401_56_dialog_content = "それに、競技に出場している光霊たちも目的が知れない。\n私たちと同じ狙いの者もいるかもしれん。",
  ui_story_5031_50310401_57_dialog_content = "そちらも監視が必要だ。\n手を出すにしても、夜が更け、皆が船を降りた後にする。",
  ui_story_5031_50310401_58_dialog_content = "おっしゃる通りです。では、部下に命じて引き続き秘密裏に捜索させ、\nエルビス様のご命令をお待ちいたします。",
  ui_story_5031_50310401_59_dialog_content = "領主様！領主様！",
  ui_story_5031_50310401_60_dialog_content = "皆、待たせたな！\nR・Wチームに1点を追加とする！",
  ui_story_5031_50310401_61_dialog_content = "やっと戻って来ましたか。\n私も観客たちも、ずっと待っていたのですよ。",
  ui_story_5031_50310401_62_dialog_content = "すまなかったな、ジェノ。",
  ui_story_5031_50310402_1_dialog_content = "…鍵…ありかを知るにはどうすれば…",
  ui_story_5031_50310402_2_dialog_content = "どうかしましたか、エルビス？",
  ui_story_5031_50310402_3_dialog_content = "あの護衛と別れてから、顔色がすぐれないようですが。",
  ui_story_5031_50310402_4_dialog_content = "体の具合でも悪いのですか？",
  ui_story_5031_50310402_5_dialog_content = "いや、大丈夫だ。",
  ui_story_5031_50310402_6_dialog_content = "執務のことを少し思い出しただけだ。\n心配をかけてすまない。",
  ui_story_5031_50310402_7_dialog_content = "…急に審判を押しつけてしまいましたが、\n仕事に支障がありましたか…？",
  ui_story_5031_50310402_8_dialog_content = "申し訳ない。こうすればエルビスも\n皆と一緒に祭りを楽しめるものと思ったのですが…",
  ui_story_5031_50310402_9_dialog_content = "あれ？団長が謝るところなんて初めて見た！",
  ui_story_5031_50310402_10_dialog_content = "ホントだ、団長でも人を怒らせずに\nちゃんと話ができるんだね～。",
  ui_story_5031_50310402_11_dialog_content = "3人とも、ムダ話をせず、\nレインボーを手伝ってきてください。",
  ui_story_5031_50310402_12_dialog_content = "あっかんべ～！",
  ui_story_5031_50310402_13_dialog_content = "まったく…朝から晩までイタズラばかりですね。",
  ui_story_5031_50310402_14_dialog_content = "心配は無用だ。\n私はただ…",
  ui_story_5031_50310402_15_dialog_content = "やっかいな問題を考えていてな。\n結論が出ないだけだ。",
  ui_story_5031_50310402_16_dialog_content = "この機会に骨休めをするのも悪くない。\n物事や人を見る目が鍛えられれば、私にも役立つだろうしな。",
  ui_story_5031_50310402_17_dialog_content = "それならよかった。\n体調がすぐれなければ、いつでも言ってください。",
  ui_story_5031_50310402_18_dialog_content = "ああ、分かった。",
  ui_story_5031_50310402_19_dialog_content = "「出場者の皆さ～ん！試合をさらに盛り上げるため、\nまもなく暗鬼の数が2倍になりま～す！！」",
  ui_story_5031_50310402_20_dialog_content = "ついに来た！\nボーナスタイムってやつ！",
  ui_story_5031_50310402_21_dialog_content = "シエル、しっかり援護して！\nボーナスタイムはハイスコアのカギなんだよ！",
  ui_story_5031_50310402_22_dialog_content = "わかりました、ガルー長官！",
  ui_story_5031_50310402_23_dialog_content = "あっ、ガルー長官、走るの速すぎ――",
  ui_story_5031_50310402_24_dialog_content = "あ？誰だこいつは？",
  ui_story_5031_50310402_25_dialog_content = "仲間とはぐれた啓光のお嬢ちゃんかぁ？",
  ui_story_5031_50310402_26_dialog_content = "な、何するつもり！？",
  ui_story_5031_50310402_27_dialog_content = "そりゃもちろん賞品を根こそぎいただいて、\n売っ払ってゼータクざんまいに決まってんだろ。",
  ui_story_5031_50310402_28_dialog_content = "悪いな、お嬢ちゃん。ウォーターガンはいただくぜ。\nおとなしく海に落ちてな！",
  ui_story_5031_50310402_29_dialog_content = "待て待て、こいつのアーマー、なかなかの上物だぞ。\nバラして影ノ街で売れば、かなりの金になりそうだ。",
  ui_story_5031_50310402_30_dialog_content = "おお、そうだそうだ！俺たちR・Wは手ぶらじゃ帰らねぇ！\nお嬢ちゃん、大人しく…",
  ui_story_5031_50310402_31_dialog_content = "持ってる金目の物を全部出しな！",
  ui_story_5031_50310402_32_dialog_content = "さ、触らないで！",
  ui_story_5031_50310402_33_dialog_content = "やめなさい――！",
  ui_story_5031_50310402_34_dialog_content = "誰だ？さっきの司会者か？",
  ui_story_5031_50310402_35_dialog_content = "そう！2人とも、強盗と違反行為をやめなさい！\nさもないと、容赦しないよ！",
  ui_story_5031_50310402_36_dialog_content = "何だぁ！？偉そうに！！\n俺たちが司会者ごときにビビると思ってんのか！？",
  ui_story_5031_50310402_37_dialog_content = "弱い者いじめは、このレインボーが許さない！",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5031_50310402_39_dialog_content = "ア、アニキ！",
  ui_story_5031_50310402_40_dialog_content = "あなたも！",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5031_50310402_42_dialog_content = "ぐわあ――！",
  ui_story_5031_50310402_43_dialog_content = "す、すごい…ぶっ飛んでいっちゃった…",
  ui_story_5031_50310402_44_dialog_content = "大丈夫？まったく、ひどすぎるよ！\n試合のどさくさ紛れで強盗なんて！！",
  ui_story_5031_50310402_45_dialog_content = "あっ、あたし、ガルー長官を手伝いに行かなきゃ。\nどうもありがとう！",
  ui_story_5031_50310402_46_dialog_content = "ウォーターガン…なくなっちゃった。",
  ui_story_5031_50310402_47_dialog_content = "しょうがないなあ。\nこのウォーターガンを持って行って。",
  ui_story_5031_50310402_48_dialog_content = "「ウォーターガンをなくした場合、司会者から新しい物をもらえる」って\nちゃんとルールに書いてあるから、安心して。",
  ui_story_5031_50310402_49_dialog_content = "わ、分かった！ありがとう！",
  ui_story_5031_50310402_50_dialog_content = "あの…",
  ui_story_5031_50310402_51_dialog_content = "ん？",
  ui_story_5031_50310402_52_dialog_content = "あたし、シエル。\nありがとう、レインボーさん。",
  ui_story_5031_50310402_53_dialog_content = "シエルって言うの？\nお名前、覚えておくよ。",
  ui_story_5031_50310402_54_dialog_content = "フン、まったく…\nなぜカレン殿下が、庶民に紛れてゲームなど！",
  ui_story_5031_50310402_55_dialog_content = "これは貴族として実に…\nあるまじきことだ！",
  ui_story_5031_50310402_56_dialog_content = "…",
  ui_story_5031_50310402_57_dialog_content = "おい、お前も何とか言え！",
  ui_story_5031_50310402_58_dialog_content = "カレン様、監視し、守る。",
  ui_story_5031_50310402_59_dialog_content = "チッ、それでは何も言わんのと同じだ。",
  ui_story_5031_50310402_60_dialog_content = "急げ、こっちだ！\nこっちに暗鬼がたくさんいるぞ！",
  ui_story_5031_50310402_61_dialog_content = "あっ！",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5031_50310402_63_dialog_content = "す、すみません…うっかりぶつかって、\nあなた様のウォーターガンを落としてしまいました…",
  ui_story_5031_50310402_64_dialog_content = "す、すぐにお拾いいたします…",
  ui_story_5031_50310402_65_dialog_content = "構わん。気にするな。\n友人が向こうで待っているぞ。楽しく遊ぶといい。",
  ui_story_5031_50310402_66_dialog_content = "あ、ありがとうございます！\nお優しい貴族様で安心しました…",
  ui_story_5031_50310402_67_dialog_content = "…",
  ui_story_5031_50310402_68_dialog_content = "…チッ、気色が悪い…",
  ui_story_5031_50310402_69_dialog_content = "手を洗わせろ！\n水だ！水を持ってこい！",
  ui_story_5031_50310402_70_dialog_content = "…面倒。",
  ui_story_5031_50310402_71_dialog_content = "グアア――！",
  ui_story_5031_50310402_72_dialog_content = "PlayerName、暗鬼の数がかなり増えたわ。",
  ui_story_5031_50310402_73_dialog_content = "でも、R・Wの人たち、\n僕たちばっかり狙い続けてる…",
  ui_story_5031_50310402_74_dialog_content = "得点不足で敗退するのが怖くないのかな？",
  ui_story_5031_50310402_75_dialog_content = "私たちのことを優勝争いの\n最大のライバルだと思ってるんでしょうね。",
  ui_story_5031_50310402_76_dialog_content = "だから、この試合で私たちを落としたいのよ。",
  ui_story_5031_50310402_77_dialog_content = "それなら、方法を思いついた…イチかバチかだ。\n光力のない僕がおとりになるよ。",
  ui_story_5031_50310402_78_dialog_content = "できるだけ多くの暗鬼をおびき寄せるから、\nそのスキに皆は、ジョナとアズールの包囲網から脱出して。",
  ui_story_5031_50310402_79_dialog_content = "それはいくら何でも無理よ、PlayerName。\nもう一度突破できないか試しましょう。今度は油断しない！",
  ui_story_5031_50310402_80_dialog_content = "カレン、ジョナとアズールはすごい銃の使い手なんだ。\nどれだけ離れていても、正確に僕たちに命中させられる。",
  ui_story_5031_50310402_81_dialog_content = "そう簡単におくれは取らないわ。\n私を信じて。",
  ui_story_5031_50310402_82_dialog_content = "もちろん、カレンの力は信じてる。\nでも、今は僕のことを信じて。",
  ui_story_5031_50310402_83_dialog_content = "カレン、PlayerNameの作戦、\n試してみる価値はあると思うわ。",
  ui_story_5031_50310402_84_dialog_content = "この状況では、一番勝算があるかも…",
  ui_story_5031_50310402_85_dialog_content = "分かったわ。くれぐれも気をつけて。",
  ui_story_5031_50310402_86_dialog_content = "安心して。\nフィアもカレンやバイスと一緒に行動してね。",
  ui_story_5031_50310402_87_dialog_content = "ええっ？わ、分かった。",
  ui_story_5031_50310402_88_dialog_content = "ほらほら、暗鬼たち！\n獲物が向こうからやって来たぞ！！",
  ui_story_5031_50310402_89_dialog_content = "こんな狙いやすい獲物、もう二度と現れな…\nうわわわわ！！",
  ui_story_5031_50310402_90_dialog_content = "グアアッ！",
  ui_story_5031_50310402_91_dialog_content = "グアア――！",
  ui_story_5031_50310402_92_dialog_content = "あん？PlayerNameのヤツ、急に飛び出してきたな。\n何のつもりだ？",
  ui_story_5031_50310402_93_dialog_content = "さすがは空の末裔のボーヤ…自分をおとりに暗鬼を集めて、\nあたしたちの射線を切ろうってコトね。",
  ui_story_5031_50310402_94_dialog_content = "でも、その程度じゃダメよ…あたしを見くびった罰として、\nボーヤのお尻に1発お見舞いしてあげましょうか――",
  ui_story_5031_50310402_95_dialog_content = "小娘ども…",
  ui_story_5031_50310402_96_dialog_content = "ん？/あら？",
  ui_story_5031_50310402_97_dialog_content = "カレン殿下に手を出させるわけにはいかんな…",
  ui_story_5031_50310402_98_dialog_content = "お前たちのような、貴族に手を出そうとする身のほど知らずどもに…\nさきほど汚された手の怒り…叩き込んでくれる！",
  ui_story_5031_50310402_99_dialog_content = "バイス、フィア、私の後ろに！",
  ui_story_5031_50310402_100_dialog_content = "暗鬼ごとき、私だけで蹴散らして見せる！",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>バンッ、バンッ――！</color>",
  ui_story_5031_50310402_102_dialog_content = "グアアア――",
  ui_story_5031_50310402_103_dialog_content = "グゥアアアア――！！",
  ui_story_5031_50310402_104_dialog_content = "グアアッ！",
  ui_story_5031_50310402_105_dialog_content = "グアアッ！",
  ui_story_5031_50310402_106_dialog_content = "小物ばかりだけれど、いかんせん数が多すぎる…\n囲まれてしまったわね。",
  ui_story_5031_50310402_107_dialog_content = "カレン、戦いにこだわるのはやめて、\nまずはPlayerNameと合流しましょう。",
  ui_story_5031_50310402_108_dialog_content = "月繭が使えさえすれば、\nこの程度の暗鬼…！",
  ui_story_5031_50310402_108X1_dialog_content = "私にもバイスのような、新しい力があれば…！",
  ui_story_5031_50310402_108X2_dialog_content = "…落ち着くのよ、カレン…",
  ui_story_5031_50310402_108X3_dialog_content = "バイスが言っていたように、\n意識を「落とす」…",
  ui_story_5031_50310402_108X4_dialog_content = "呼吸を…感じるのよ。",
  ui_story_5031_50310402_108X5_dialog_content = "カレン。",
  ui_story_5031_50310402_108X6_dialog_content = "父上…",
  ui_story_5031_50310402_108X7_dialog_content = "暗鬼をすべて倒しきることなどできぬ。\nそれは余もお前も理解しているはずだ。",
  ui_story_5031_50310402_108X8_dialog_content = "軽々しく行動すれば、\nお前を信頼した兵士たちが命を落とす。",
  ui_story_5031_50310402_108X9_dialog_content = "半端な力では、\n大切な者たちを守ることなどできぬ。",
  ui_story_5031_50310402_108X10_dialog_content = "お前はまだまだ未熟だ…探しつづけなければならん。\nさらに強くなるために。",
  ui_story_5031_50310402_108X11_dialog_content = "お前には失望した…",
  ui_story_5031_50310402_108X12_dialog_content = "父上…そんなことは…！\n父上！",
  ui_story_5031_50310402_108X13_dialog_content = "カレン！",
  ui_story_5031_50310402_108X14_dialog_content = "グアアッ！",
  ui_story_5031_50310402_108X15_dialog_content = "どきなさい！",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5031_50310402_110_dialog_content = "げ、げんこつで叩いても、得点にならないよ？",
  ui_story_5031_50310402_111_dialog_content = "カレン、落ち着いて！\nPlayerNameを探しに行かないと！",
  ui_story_5031_50310402_112_dialog_content = "…ごめんなさい。その通りね。",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310402_114_dialog_content = "「試合終了！場内に残っている出場者は、\n審判席に戻って成績を確認してください！」",
  ui_story_5031_50310402_115_dialog_content = "よかったね、カレン。次の試合に進めるよ！",
  ui_story_5031_50310402_116_dialog_content = "ええ、PlayerNameが包囲から\n逃がしてくれたおかげね。",
  ui_story_5031_50310402_117_dialog_content = "でも、危険には違いないわ。\n実戦では絶対にあんな戦術を取らないで欲しいわね。",
  ui_story_5031_50310402_118_dialog_content = "あらあら…空の末裔のボーヤ、\n自分のおかげで皆が助かったと思ってるのかしら。",
  ui_story_5031_50310402_119_dialog_content = "えっ？アズール、どういう意味？",
  ui_story_5031_50310402_120_dialog_content = "急に出てきた白夜城のヤローが俺たちにケンカを吹っかけてきてな。\nそっちで手が塞がってたんだ。",
  ui_story_5031_50310402_121_dialog_content = "あいつがいなけりゃ、\nあんたのケツにアズールの弾が撃ち込まれてたはずだぜ。",
  ui_story_5031_50310402_122_dialog_content = "やっぱりオモチャで遊ぶより、\n白夜城のヤツとホンモノでやりあった方がスカッとするな。",
  ui_story_5031_50310402_123_dialog_content = "大声をあげながら突っ込んで来たわね。あれのどこが貴族らしいのかしら…\nま、そのおかげで試合の方はすっかり忘れちゃったけど。",
  ui_story_5031_50310402_124_dialog_content = "途中で横にいた無口な人に引きずられていったのが残念だけど、\nそうじゃなきゃ、まだ終わってなかったんじゃないかしら。",
  ui_story_5031_50310402_125_dialog_content = "ア、アネキ…",
  ui_story_5031_50310402_126_dialog_content = "おお？どのツラ下げて戻ってきた？",
  ui_story_5031_50310402_127_dialog_content = "女と子どもには手を出さないってオキテを忘れたか？",
  ui_story_5031_50310402_128_dialog_content = "す、すみません、アネキ。\nつい魔が差して…",
  ui_story_5031_50310402_129_dialog_content = "船から降りて腕立て伏せだ。\n俺が酒を飲み終わるまで続けてろ。",
  ui_story_5031_50310402_130_dialog_content = "は、はい！アネキ！",
  ui_story_5031_50310402_131_dialog_content = "チッ、興ざめさせやがって…",
  ui_story_5031_50310402_132_dialog_content = "R・Wにそんな一面があるなんて、意外ね。",
  ui_story_5031_50310402_133_dialog_content = "ほめ言葉として受け取っておくよ、プリンセス。\n俺はアズールと酒を飲んでくる。またな。",
  ui_story_5031_50310402_134_dialog_content = "あっちでタダ酒をいただいて来るわ！\n空の末裔のボーヤ、また後でお姉さんに会いに来てね、バイバ～イ！",
  ui_story_5031_50310402_135_dialog_content = "はぁ――何はともあれ、\n僕たちに目をつけてるライバルは減ったみたいだね。",
  ui_story_5031_50310402_136_dialog_content = "ガルー先輩たちも無事に次の試合に進んでるみたい。\n得点も高いわね。",
  ui_story_5031_50310402_137_dialog_content = "まさかジョナとアズールみたいなスゴ腕が初戦で敗退するほど、\n激戦になるなんて思わなかったよ。",
  ui_story_5031_50310402_138_dialog_content = "次の試合も…きっとすごく激しくて、\n悲惨で、厳しいものになるはず…",
  ui_story_5031_50310402_139_dialog_content = "ゴクリ…",
  ui_story_5031_50310402_140_dialog_content = "口で言わなくてもいいよ！？",
  ui_story_5031_50310402_141_dialog_content = "ふ、雰囲気に合わせようと思っただけだよ！",
  ui_story_5031_50310402_142_dialog_content = "領主様～、こんにちは！",
  ui_story_5031_50310402_143_dialog_content = "やあ、君はさっきの…",
  ui_story_5031_50310402_144_dialog_content = "はい、サプリです！",
  ui_story_5031_50310402_145_dialog_content = "ジェノ団長からこれを届けるようにって。",
  ui_story_5031_50310402_146_dialog_content = "これは？",
  ui_story_5031_50310402_147_dialog_content = "毛布です。領主様が海風で\nかぜを引くといけないからって、言ってました。",
  ui_story_5031_50310402_148_dialog_content = "…分かった。代わりに礼を言っておいてくれ。",
  ui_story_5031_50310402_149_dialog_content = "ありがとう、サプリ。",
  ui_story_5031_50310402_150_dialog_content = "エヘヘ。どういたしまして～。",
  ui_story_5031_50310402_151_dialog_content = "…",
  ui_story_5031_50310501_1_dialog_content = "おめでとうございます。\n第1試合を突破された勇者の皆様…",
  ui_story_5031_50310501_2_dialog_content = "この秘宝の扉の外までたどり着いたということは、\n皆様の勇気と力の証明にほかなりません。",
  ui_story_5031_50310501_3_dialog_content = "第2試合のルールもとても簡単です。",
  ui_story_5031_50310501_4_dialog_content = "小さい頃、このような遊びをしたことも\nいらっしゃるかと思います。",
  ui_story_5031_50310501_5_dialog_content = "出でよ、無尽のたそがれの中で舞い踊る、みにくき獣、\n秘法と秘宝の守護者よ――",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5031_50310501_7_dialog_content = "こちらが今回の、秘宝の番人です。",
  ui_story_5031_50310501_8_dialog_content = "オホン！それでは続いて、レインボーがルールを説明するよ～。",
  ui_story_5031_50310501_9_dialog_content = "この暗鬼が緑色になったら…",
  ui_story_5031_50310501_10_dialog_content = "ジャマをしてくる暗鬼たちを全速力で突破して、\n秘宝の番人の近くへダッシュしてね～。",
  ui_story_5031_50310501_11_dialog_content = "秘宝の番人のそばにあるラインまで到達できれば、\n次の試合に進めるよ！",
  ui_story_5031_50310501_12_dialog_content = "ただし！赤になった時は気を付けて！",
  ui_story_5031_50310501_13_dialog_content = "その時は光霊も暗鬼も、一切動いちゃダメ！\n違反しちゃうと近くの暗鬼に船から降ろされて、失格になっちゃうの！",
  ui_story_5031_50310501_14_dialog_content = "制限時間内にゴールへたどり着けなかった人も失格！",
  ui_story_5031_50310501_15_dialog_content = "あと、この勝負では、\n使用する光力術の制限はナシ！",
  ui_story_5031_50310501_16_dialog_content = "その通りです。さあ！\n秘宝を目指し、全力で挑んでください！",
  ui_story_5031_50310501_17_dialog_content = "PlayerName…",
  ui_story_5031_50310501_18_dialog_content = "うん、ようやく僕の力が役に立ちそうだよ。",
  ui_story_5031_50310501_19_dialog_content = "安心して。皆が最初にゴールへ\nたどり着けるようにするから！",
  ui_story_5031_50310502_1_dialog_content = "ハッハッハ！\nこの程度の暗鬼なら、俺でも楽勝だ！",
  ui_story_5031_50310502_2_dialog_content = "オラオラ！このザコどもが！",
  ui_story_5031_50310502_3_dialog_content = "おい！あのデカい暗鬼、\nもうすぐ色が変わるぞ！止まれ！",
  ui_story_5031_50310502_4_dialog_content = "まだいける！\nもう少し前に進んで、リードしておくんだ！",
  ui_story_5031_50310502_5_dialog_content = "バカどもが。もうすぐ敗退するというのに、\n身のほど知らずめ…",
  ui_story_5031_50310502_6_dialog_content = "さきほどの試合では助かった。\n私が賊ども2人をこらしめている間に点を稼いでいたとはな！",
  ui_story_5031_50310502_7_dialog_content = "たかが賊2人にあそこまで手こずるとは思わなかったが…\nまぁ、いい運動にはなった。",
  ui_story_5031_50310502_8_dialog_content = "お前に引きずられていなければ、\n倒せてはいただろうが…",
  ui_story_5031_50310502_9_dialog_content = "…",
  ui_story_5031_50310502_10_dialog_content = "フン、ほめても声を出さないのか。\n唇を貼り合わせでもしたか？",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310502_12_dialog_content = "色が変わった！",
  ui_story_5031_50310502_13_dialog_content = "グアアッ！",
  ui_story_5031_50310502_14_dialog_content = "く、来るな！",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>バシャン！！</color>",
  ui_story_5031_50310502_17_dialog_content = "やはり落とされたか。\n愚かな庶民どもめ…",
  ui_story_5031_50310502_18_dialog_content = "カレン殿下から離れすぎぬように、\nもう少し近づいてお守りするとしよう。",
  ui_story_5031_50310502_19_dialog_content = "カレン殿下が今のあわれな庶民のように、\n海に落とされては困るからな。",
  ui_story_5031_50310502_20_dialog_content = "毛布をありがとう、ジェノ。",
  ui_story_5031_50310502_21_dialog_content = "どういたしまして。海風が強かったですからね。\nあなたにかぜなど引かれては困ります。",
  ui_story_5031_50310502_22_dialog_content = "フ、今もこんな遊びが好きだとは意外だな。",
  ui_story_5031_50310502_23_dialog_content = "幼稚すぎるとでも？",
  ui_story_5031_50310502_24_dialog_content = "いや、少し驚いているだけさ。",
  ui_story_5031_50310502_25_dialog_content = "もう何年も経つのに、まだこんな遊びに興味を持っている…\nそれどころか、大会の一部にしてしまうのだからな。",
  ui_story_5031_50310502_26_dialog_content = "懐古趣味なものでして。",
  ui_story_5031_50310502_27_dialog_content = "僕は1つのことをいつまでも覚えている性質です。\n例えば…ずっと昔に約束をすっぽかされて、1日中待ちぼうけした、とか。",
  ui_story_5031_50310502_28_dialog_content = "…あの時は別れも言わずに行ってしまって、\n本当にすまなかった。",
  ui_story_5031_50310502_29_dialog_content = "ええ、もう許しますよ。",
  ui_story_5031_50310502_30_dialog_content = "…？",
  ui_story_5031_50310502_31_dialog_content = "その言葉を待っていただけなのです。",
  ui_story_5031_50310502_32_dialog_content = "少し考えれば分かることですから。",
  ui_story_5031_50310502_33_dialog_content = "レストランのオーナーに過ぎない家の息子が、\nハーバーシティの領主になるまで、どれほど大変な思いをしたか…",
  ui_story_5031_50310502_34_dialog_content = "それでも、あなたの大切なものの多くは変わっていないと感じられます。\n僕のカン違いでないといいのですが。",
  ui_story_5031_50310502_35_dialog_content = "大切なもの？",
  ui_story_5031_50310502_36_dialog_content = "たとえば、ハーバーシティで体操を推進している、などですね。\nバカバカしく聞こえますが、実にあなたらしい。",
  ui_story_5031_50310502_37_dialog_content = "ハハハ…それで皆が健康になるなら、\nバカバカしくても構わないさ。",
  ui_story_5031_50310502_38_dialog_content = "そういうお前はどうなんだ？白夜城に戻った後、ずいぶんと探した。\n誰も行方を知らなかったぞ。",
  ui_story_5031_50310502_39_dialog_content = "僕ですか？",
  ui_story_5031_50310502_40_dialog_content = "ハーバーシティに戻ってきてからも、ずいぶんと探した。\n誰も行方を知らなかった。",
  ui_story_5031_50310502_41_dialog_content = "それどころか、お前の一家はもう\nこの世にいないと言う者までいた…",
  ui_story_5031_50310502_42_dialog_content = "似たようなものです。",
  ui_story_5031_50310502_43_dialog_content = "暗潮の危機で生きるのに疲れたかわいそうな人々とともに、\n僕たち家族も、ひょんなことから「エメラルド号」に逃げ込みました。",
  ui_story_5031_50310502_44_dialog_content = "その後は、運命なのでしょう。\n僕は真理結社のビクトリア様に救って頂いたのです。",
  ui_story_5031_50310502_45_dialog_content = "「始原」の力も与えてくださいました。",
  ui_story_5031_50310502_46_dialog_content = "しかし、僕が「エメラルド号」に戻った時…\n両親がとうに世を去っていたことを知ったのです。",
  ui_story_5031_50310502_47_dialog_content = "当時の私は、両親の死が前団長と関係があると思い込んでいました。\n彼に戦いを挑み、両親の仇を討とうと思ったのです。",
  ui_story_5031_50310502_48_dialog_content = "僕が真実を知ったのはずっと後になってからです。\n幸い、前団長は僕を責めませんでした。",
  ui_story_5031_50310502_49_dialog_content = "その後、僕は「エメラルド号」とサーカス団の人たちと\n大海原を旅して回るようになりました。",
  ui_story_5031_50310502_50_dialog_content = "すまなかった…いい人たちだったのに…",
  ui_story_5031_50310502_51_dialog_content = "謝ることはありません。\nあなたのせいではないのですから。",
  ui_story_5031_50310502_52_dialog_content = "確かに僕は真理結社の力を利用し、\nマジシャンとしての人生を続けています。",
  ui_story_5031_50310502_53_dialog_content = "しかし、正直に言うと、\n真理結社やその教義にはまったく興味がないのです。",
  ui_story_5031_50310502_54_dialog_content = "結社の中にもたくさんの派閥があります。\n僕は最も外側の「不まじめ」なタイプに当たるのでしょうね。",
  ui_story_5031_50310502_55_dialog_content = "ですが、ビクトリア様には恩があります。\nあのお方との約束だけは絶対に守らなければなりません。",
  ui_story_5031_50310502_56_dialog_content = "また約束を破られるのはイヤですから…",
  ui_story_5031_50310502_57_dialog_content = "約束…ゲホッ！ゴホ、ゴホ！！",
  ui_story_5031_50310502_58_dialog_content = "それは…血ですか！？",
  ui_story_5031_50310502_59_dialog_content = "だ、大丈夫だ。最近、執務に追われて\n休めていない上に、かぜ気味でな…",
  ui_story_5031_50310502_60_dialog_content = "僕の目が節穴だとでも！？",
  ui_story_5031_50310502_61_dialog_content = "ハハハ…まさか。\n私は本当に、問題ない。",
  ui_story_5031_50310502_62_dialog_content = "信じないのなら、お得意の占いで寿命を占ってみたらどうだ？\nあと200年は生きられると思うぞ。",
  ui_story_5031_50310502_63_dialog_content = "何をバカなことを…\n一体どうしたのです！？正直に話してください…",
  ui_story_5031_50310502_64_dialog_content = "ハハ…ハーバーシティにいたのなら、\n「英雄の伝説」は知っているだろう？",
  ui_story_5031_50310502_65_dialog_content = "もちろんです。あんな子どもだましの伝説…",
  ui_story_5031_50310502_66_dialog_content = "その伝説は…真実だ。",
  ui_story_5031_50310502_67_dialog_content = "…",
  ui_story_5031_50310502_68_dialog_content = "簡単に言えば、血の契約を結ぶことで、\n暗鬼は封印されたのだ。",
  ui_story_5031_50310502_69_dialog_content = "契約の力によって暗鬼は深い眠りに落ち、\nハーバーシティは暗鬼が近寄れない楽園となった。",
  ui_story_5031_50310502_70_dialog_content = "しかし、彼らの子孫がその代償を支払い続けなくてはならない。",
  ui_story_5031_50310502_71_dialog_content = "それが「モドリー失調症」だ。",
  ui_story_5031_50310502_72_dialog_content = "モドリー失調症！？あなたもですか！？\nまさか、その顔も…",
  ui_story_5031_50310502_73_dialog_content = "ああ。だが、心配は無用だ。\n私はまだ…ゲホッ、ゲホッ…大丈夫だ。",
  ui_story_5031_50310502_74_dialog_content = "何かの契約だというのなら、\nその契約を解消する方法もあるのでは？",
  ui_story_5031_50310502_75_dialog_content = "実は、ここ数年ずっと探していたのだ…\n解決策をな。",
  ui_story_5031_50310502_76_dialog_content = "どんな方法です？",
  ui_story_5031_50310502_77_dialog_content = "すまん。まだ確信を得られていない。\n色々あってな、安易には話せん。",
  ui_story_5031_50310502_78_dialog_content = "…",
  ui_story_5031_50310502_79_dialog_content = "見ろ！前に飛び出してる女の子、すごく強いぞ！",
  ui_story_5031_50310502_80_dialog_content = "あの子、まったく光力術を使えない人と一緒にいるみたいだ。\nどうしてあんなに強いんだ？",
  ui_story_5031_50310502_81_dialog_content = "あの光力術を使えない人って…\nまさか空の末裔？",
  ui_story_5031_50310502_82_dialog_content = "なんだって、空の末裔！？\nどいつだ！？",
  ui_story_5031_50310502_83_dialog_content = "団長～、お取り込み中かもしれないけど、\nまた物資が届いたよ。確認して～。",
  ui_story_5031_50310502_84_dialog_content = "分かりました。すぐに行きます。",
  ui_story_5031_50310502_85_dialog_content = "ひとまず、審判の仕事は任せましたよ。\nすぐに戻ります。",
  ui_story_5031_50310502_86_dialog_content = "ああ。行ってこい、ジェノ。",
  ui_story_5031_50310602_1_dialog_content = "「2周目――スタート！」",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName！遅れずについてきて！",
  ui_story_5031_50310602_4_dialog_content = "バイスとフィアはPlayerNameを守って、\n暗鬼を近づけないようにして。",
  ui_story_5031_50310602_5_dialog_content = "了解！",
  ui_story_5031_50310602_6_dialog_content = "ごめん。一度に動ける時間がこんなに短いとは思わなかったよ。\nこれじゃ、指揮してもあまり役に立てないね。",
  ui_story_5031_50310602_7_dialog_content = "光力術を使って、秘宝の番人のそばへ\n一気に駆け寄ってる光霊もいるみたいだし…",
  ui_story_5031_50310602_8_dialog_content = "気にする必要はないわ。\n私たちは自分のペースで進めばいい。",
  ui_story_5031_50310602_9_dialog_content = "PlayerName、あなたが道を示して。",
  ui_story_5031_50310602_10_dialog_content = "分かったよ！",
  ui_story_5031_50310602_11_dialog_content = "やれやれ――",
  ui_story_5031_50310602_12_dialog_content = "距離を保つようにと言われていましたが、\nどうしても見ていられませんのでな。",
  ui_story_5031_50310602_13_dialog_content = "あなたは…思い出したわ。\n裁判官のマシュー。",
  ui_story_5031_50310602_14_dialog_content = "いかにも。\nこちらの「無口」は同僚のローウェイ。",
  ui_story_5031_50310602_15_dialog_content = "以前、ピアタマンの小僧が世話になったそうですな。\nしかし、これだけは言わせていただこう――",
  ui_story_5031_50310602_16_dialog_content = "カレン殿下、これは何たる失態ですかな？",
  ui_story_5031_50310602_17_dialog_content = "勇敢でお強いカレン殿下が、光力術を使えない者を守るため、\n思うように動けなくなるとは。",
  ui_story_5031_50310602_18_dialog_content = "殿下であれば、空の末裔などおらずとも、\nとうに次の試合に駒を進められているはずでございましょう。",
  ui_story_5031_50310602_19_dialog_content = "この空の末裔は、あの庶民どもと同じ！\n役立たずの足手まといだ。",
  ui_story_5031_50310602_20_dialog_content = "私の前で――！",
  ui_story_5031_50310602_21_dialog_content = "どうか、お気になさらず。",
  ui_story_5031_50310602_22_dialog_content = "え？",
  ui_story_5031_50310602_23_dialog_content = "こいつは心に問題があるのです。",
  ui_story_5031_50310602_24_dialog_content = "お、お前…何を言いだす！？",
  ui_story_5031_50310602_25_dialog_content = "続けて、続けて。フィア、聞きたいな～！",
  ui_story_5031_50310602_26_dialog_content = "温和なふりをして…",
  ui_story_5031_50310602_27_dialog_content = "その実、ひどい庶民嫌い。",
  ui_story_5031_50310602_28_dialog_content = "「庶民」と呼ぶものを軽べつし、ひどく嫌っている。",
  ui_story_5031_50310602_29_dialog_content = "自分の出自が…",
  ui_story_5031_50310602_30_dialog_content = "おい、それ以上言うな。黙れ！\nなぜ急にしゃべりだす！",
  ui_story_5031_50310602_31_dialog_content = "聞こえているのか！？\nやめないか！！",
  ui_story_5031_50310602_32_dialog_content = "うるさい。",
  ui_story_5031_50310602_33_dialog_content = "…チッ。",
  ui_story_5031_50310602_34_dialog_content = "でも、白夜城の貴族って、\n多かれ少なかれ平民を下に見てる人が多いよね。",
  ui_story_5031_50310602_35_dialog_content = "その比じゃない。",
  ui_story_5031_50310602_X35_dialog_content = "こいつは間接的に触れただけで、\n10回以上も手を洗う。",
  ui_story_5031_50310602_X36_dialog_content = "体にホコリでもつけられようものなら、\n悲鳴をあげる。",
  ui_story_5031_50310602_36_dialog_content = "へぇ～？じゃあ、ケージにでも入れて、\n外の世界から隔離しないとね～？",
  ui_story_5031_50310602_37_dialog_content = "そう。潔癖症だ。極度の。",
  ui_story_5031_50310602_38_dialog_content = "かわいそ～…",
  ui_story_5031_50310602_39_dialog_content = "お前のような庶民の小娘に同情されるほど\n落ちぶれてはいないぞ！",
  ui_story_5031_50310602_40_dialog_content = "あと、仕事もサボる。",
  ui_story_5031_50310602_41_dialog_content = "えっ、サボるの？\n立派な大人じゃないの～？",
  ui_story_5031_50310602_42_dialog_content = "学友のよしみで…",
  ui_story_5031_50310602_X42_dialog_content = "ピアタマンに…",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310602_44_dialog_content = "色が変わった！\nみんな、動かないで！",
  ui_story_5031_50310602_45_dialog_content = "し、しまった！",
  ui_story_5031_50310602_46_dialog_content = "引っ張ってくれ！突っ込みすぎた！",
  ui_story_5031_50310602_47_dialog_content = "け、汚らわしい庶民め！\nこっちに来るな――！",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5031_50310602_49_dialog_content = "す、すみません、貴族様…",
  ui_story_5031_50310602_50_dialog_content = "さ…さっさと失せろ！",
  ui_story_5031_50310602_51_dialog_content = "私の服が！き、着替える！",
  ui_story_5031_50310602_52_dialog_content = "ローウェイ、戻るぞ！\n身体を洗わねば！！",
  ui_story_5031_50310602_53_dialog_content = "好き嫌いが激しい。",
  ui_story_5031_50310602_54_dialog_content = "あと、自分でネコ舌だと言っている。",
  ui_story_5031_50310602_55_dialog_content = "いつも「アチチ！！」とか叫んでいる。",
  ui_story_5031_50310602_56_dialog_content = "それをわざわざ見せつけてくる。",
  ui_story_5031_50310602_57_dialog_content = "まったく見たくないのに。",
  ui_story_5031_50310602_58_dialog_content = "3名脱落――",
  ui_story_5031_50310602_59_dialog_content = "では、また――",
  ui_story_5031_50310602_60_dialog_content = "見た目とは大違いね。\n短くて力強い話し方が印象に残るわ。",
  ui_story_5031_50310602_X60_dialog_content = "うん、とってもおもしろそうな人だね。",
  ui_story_5031_50310602_61_dialog_content = "カレン、ごめん…",
  ui_story_5031_50310602_62_dialog_content = "何を謝ることがあるの？\nまさか、さっきの話をうのみにしたというの？",
  ui_story_5031_50310602_63_dialog_content = "カレンが必死に戦っているのに、僕は戦えなかった。\n足手まといになってるって、気はしてたんだ。",
  ui_story_5031_50310602_64_dialog_content = "そう思ったのは、私が必死だったから？",
  ui_story_5031_50310602_65_dialog_content = "うん。今日の君は…\nすごく真剣で、何もかも自分で背負い込もうとしてるみたいだ。",
  ui_story_5031_50310602_66_dialog_content = "そうだったかしら…？",
  ui_story_5031_50310602_67_dialog_content = "私たちはあなたを足手まといだと思ったことなどない。\nあなたは常に重要な役割を果たしているわ。",
  ui_story_5031_50310602_68_dialog_content = "もちろんよ。PlayerNameはいつだって、私たちの大事な仲間！",
  ui_story_5031_50310602_69_dialog_content = "はぁ…PlayerName、\nあんなヤツの言葉でヘコんでるの？",
  ui_story_5031_50310602_70_dialog_content = "みんな…",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310602_72_dialog_content = "緑色になったわ。\n行動に移りましょう。",
  ui_story_5031_50310602_73_dialog_content = "分かってる。みんな、一緒に突っ走ろう！",
  ui_story_5031_50310701_1_dialog_content = "もうすぐゴールよ、PlayerName。",
  ui_story_5031_50310701_2_dialog_content = "このままいけば、\n次でたどり着けるわ。",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310701_4_dialog_content = "全員、移動…",
  ui_story_5031_50310701_5_dialog_content = "いや、待って！おかしい！",
  ui_story_5031_50310701_6_dialog_content = "また戻るよ！",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>カランカラン――</color>",
  ui_story_5031_50310701_8_dialog_content = "どういうこと？\nなぜ急に間隔が短くなったの？",
  ui_story_5031_50310701_9_dialog_content = "うわっ！",
  ui_story_5031_50310701_10_dialog_content = "もう…どうして急に間隔が変わったんだろう？",
  ui_story_5031_50310701_11_dialog_content = "反応力を試しているのでしょうね。\nいきなり間隔が変わるのも、当然のことなのでしょう。",
  ui_story_5031_50310701_12_dialog_content = "これからはもっと慎重に動かないといけないわね…。",
  ui_story_5031_50310701_13_dialog_content = "また4名脱落！",
  ui_story_5031_50310701_14_dialog_content = "カレン、向こうの女の子、\n様子がおかしいみたい。",
  ui_story_5031_50310701_15_dialog_content = "表情が少し変だ。\n光力も弱まってる…",
  ui_story_5031_50310701_16_dialog_content = "うっ…",
  ui_story_5031_50310701_17_dialog_content = "まずい、倒れたわ！",
  ui_story_5031_50310701_18_dialog_content = "ルールだと、彼女も海に\n落とされちゃうかもしれないのよね？",
  ui_story_5031_50310701_19_dialog_content = "でも、目を固く閉じていて、\n苦しそうな様子だ…",
  ui_story_5031_50310701_20_dialog_content = "あのまま海に落とされたら危険だわ。",
  ui_story_5031_50310701_21_dialog_content = "PlayerName！\n何とかしなさいよ！",
  ui_story_5031_50310701_22_dialog_content = "グアアア――",
  ui_story_5031_50310701_23_dialog_content = "これ以上待てない！",
  ui_story_5031_50310701_24_dialog_content = "カレン！",
  ui_story_5031_50310702_1_dialog_content = "試合を一時中断します！！",
  ui_story_5031_50310702_2_dialog_content = "カレン殿下、何事です？",
  ui_story_5031_50310702_3_dialog_content = "この子の様子がおかしいの。",
  ui_story_5031_50310702_4_dialog_content = "私にお任せを。医学の心得がありますので。",
  ui_story_5031_50310702_5_dialog_content = "お嬢さん、私の声が聞こえるか？",
  ui_story_5031_50310702_6_dialog_content = "うぅ…",
  ui_story_5031_50310702_7_dialog_content = "これは…「モドリー失調症」だ…",
  ui_story_5031_50310702_8_dialog_content = "早く、この薬を飲むがいい。",
  ui_story_5031_50310702_9_dialog_content = "ジェノ、悪いがさっきの毛布を。",
  ui_story_5031_50310702_10_dialog_content = "分かりました。",
  ui_story_5031_50310702_11_dialog_content = "はぁ…はぁ…",
  ui_story_5031_50310702_12_dialog_content = "領主様…ありがとうございます…\nだいぶ良くなったみたいです。",
  ui_story_5031_50310702_13_dialog_content = "無理をしてはいけない。体温が低すぎる。\n毛布にくるまれば少しは楽になる。",
  ui_story_5031_50310702_14_dialog_content = "はい…知ってます、それに領主様が教えてくださった体操も…\nランカはお白湯をたくさん飲むようにしています…",
  ui_story_5031_50310702_15_dialog_content = "うむ、いい子だ。\n私も君のことをほこりに思う。",
  ui_story_5031_50310702_16_dialog_content = "エルビス、毛布です。",
  ui_story_5031_50310702_17_dialog_content = "ああ、ありがとう。",
  ui_story_5031_50310702_18_dialog_content = "パト！",
  ui_story_5031_50310702_19_dialog_content = "ここに。",
  ui_story_5031_50310702_20_dialog_content = "衛兵に彼女を家族のもとまで届けさせろ。\n病院で検査を受けるよう、家族に伝えるように。",
  ui_story_5031_50310702_21_dialog_content = "お任せを。ご安心ください。",
  ui_story_5031_50310702_22_dialog_content = "ジェノ、見たか？\nまだ、あんなに小さい子が…",
  ui_story_5031_50310702_23_dialog_content = "…",
  ui_story_5031_50310702_24_dialog_content = "これが、エルビスはハーバーシティの民に\n愛される領主ということね。",
  ui_story_5031_50310702_25_dialog_content = "民を愛しているなどと口だけの貴族たちが、\n本当に民を愛するあなたの姿を見たら、たいそう冷や汗をかくでしょう。",
  ui_story_5031_50310702_26_dialog_content = "ハーバーシティはこんなにも\n民を思いやる領主に恵まれているのね。",
  ui_story_5031_50310702_27_dialog_content = "フン、たかが庶民一人に…\nカレン殿下は大げさすぎる！",
  ui_story_5031_50310702_28_dialog_content = "まったく、ぶつかってきた奴のことを思い出すだけで…\nはらわたが煮えくり返りそうになるわ。",
  ui_story_5031_50310702_29_dialog_content = "危うく海に落とされるところだったが、\nなんとか自力ではい上がれたぞ…",
  ui_story_5031_50310702_30_dialog_content = "まったく、いつになったら\n身体を洗って着替えられるのだ…",
  ui_story_5031_50310702_31_dialog_content = "静かに。",
  ui_story_5031_50310702_32_dialog_content = "おほめに預かり光栄でございます、\nカレン殿下。",
  ui_story_5031_50310702_33_dialog_content = "ただ、あまり彼女の役には立てておりません…",
  ui_story_5031_50310702_34_dialog_content = "申し訳ございませんが、\n用事がありますので、失礼いたします。",
  ui_story_5031_50310702_35_dialog_content = "ええ。",
  ui_story_5031_50310702_36_dialog_content = "…",
  ui_story_5031_50310702_37_dialog_content = "エルビス様、私をお探しですか？",
  ui_story_5031_50310702_38_dialog_content = "パト、もう時間がない。",
  ui_story_5031_50310702_39_dialog_content = "先ほど気づいたことだが、\n「<color=#FFB400>信風石</color>」の力がまた弱まっているようだ。",
  ui_story_5031_50310702_40_dialog_content = "私もあの少女も、そのせいで発症したのだ。",
  ui_story_5031_50310702_41_dialog_content = "おそらく、封印がもう長く持たないと言う事だろう。",
  ui_story_5031_50310702_42_dialog_content = "エルビス様、本当に白夜城には助けを求められないのですか？\nカレン殿下は他の貴族たちとは違うようですが…",
  ui_story_5031_50310702_43_dialog_content = "あの方ならソルラド殿下と連絡を取り、\n我らを助けてくれるかもしれません。",
  ui_story_5031_50310702_44_dialog_content = "私とて、ソルラド殿下は\n利害を見極められる聡明なお方だと信じたい。",
  ui_story_5031_50310702_45_dialog_content = "だが、元老院の連中は信用できん。",
  ui_story_5031_50310702_46_dialog_content = "ハーバーシティのために大軍を出すどころか、\n私たちに代々暮らしてきた故郷を捨てるよう言い渡される可能性の方が高い。",
  ui_story_5031_50310702_47_dialog_content = "それに、私たちの先祖が大変な努力をして守り抜いてきた「信風石」の秘密は、\nまだほとんど誰にも知られていない。",
  ui_story_5031_50310702_48_dialog_content = "あれのことが公になれば、\nよからぬことを企む者が奪おうと狙い始めるだろう。",
  ui_story_5031_50310702_49_dialog_content = "信風石を失えば、\nハーバーシティは完全に終わりだ。",
  ui_story_5031_50310702_50_dialog_content = "先祖と子孫たちが命がけで守り、\nハーバーシティの民が築いてきた故郷は、煙のごとく消えてしまう。",
  ui_story_5031_50310702_51_dialog_content = "これもすべて、民の命とハーバーシティの未来のためだ。\n私たちは己の力しか頼れない。己しか信じられないのだ。",
  ui_story_5031_50310702_52_dialog_content = "エルビス様…かしこまりました。",
  ui_story_5031_50310702_53_dialog_content = "ハーバーシティとモドリー家のため、\n私はたとえ火の中にでも飛び込んでみせましょう。",
  ui_story_5031_50310702_54_dialog_content = "もはや後戻りはできない。",
  ui_story_5031_50310702_55_dialog_content = "私たちが失敗すれば、\n誰もハーバーシティの民を救ってはくれないだろう。",
  ui_story_5031_50310702_56_dialog_content = "私たちを救えるのは私たちだけだ、パト。",
  ui_story_5031_50310702_57_dialog_content = "――カレン殿下、あくまで身分は隠されたいと？",
  ui_story_5031_50310702_58_dialog_content = "ええ。静かに旅を楽しみたいの。\n頼んだわ。",
  ui_story_5031_50310702_59_dialog_content = "かしこまりました。",
  ui_story_5031_50310702_60_dialog_content = "諸君、聞いてくれ。",
  ui_story_5031_50310702_61_dialog_content = "先ほど、出場者であった女性が体調不良で倒れた。\n彼女はルールにしたがい、海に落とされるところだった。",
  ui_story_5031_50310702_62_dialog_content = "しかし、間一髪のところでこちらの献身的で勇敢な少女の一団が、\nルール違反を犯してまで、飛び出した！",
  ui_story_5031_50310702_63_dialog_content = "そのおかげで、落とされそうになっていた女性は救われた。",
  ui_story_5031_50310702_64_dialog_content = "確かに彼女たちはルールには違反した。\nだが、このハーバーシティにおいて、心優しき者が冷たく扱われてよいものか？",
  ui_story_5031_50310702_65_dialog_content = "我らハーバーシティの者は、他人への優しさを忘れるべきではない！\nゆえに、彼女たちを試合に戻すという裁定を許してもらいたい！",
  ui_story_5031_50310702_66_dialog_content = "賛成！異議なし！",
  ui_story_5031_50310702_67_dialog_content = "領主様バンザイ！",
  ui_story_5031_50310702_68_dialog_content = "皆、ありがとう！\n皆の領主でいられることを、私は光栄に思う！",
  ui_story_5031_50310702_69_dialog_content = "ありがとう、エルビス。",
  ui_story_5031_50310702_70_dialog_content = "当然のことをしたまでです。\nこれは会場にいる全員の心の声でしょうから。",
  ui_story_5031_50310702_71_dialog_content = "さあ、お仲間と一緒に、試合にお戻りください。",
  ui_story_5031_50310702_X71_dialog_content = "それでは、試合再開！",
  ui_story_5031_50310702_X72_dialog_content = "はぁ…はぁ…みんな、走るのが速すぎるよ…\nどうしてもうゴールしてるの…",
  ui_story_5031_50310702_X73_dialog_content = "PlayerName、急いで！\nまた色が変わるわ！",
  ui_story_5031_50310702_X74_dialog_content = "えっ？だ、ダメだ。\n僕、もう限界…",
  ui_story_5031_50310702_72_dialog_content = "PlayerName、私たちが受け止める！\nそのまま飛び込んで来なさい！",
  ui_story_5031_50310702_73_dialog_content = "分かった！",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>ドンッ――</color>",
  ui_story_5031_50310702_75_dialog_content = "危ないところだったわね。",
  ui_story_5031_50310702_76_dialog_content = "PlayerName、重いよ！",
  ui_story_5031_50310702_77_dialog_content = "やった！",
  ui_story_5031_50310702_78_dialog_content = "これで次の試合に進めるね。",
  ui_story_5031_50310702_79_dialog_content = "手ごわそうな人たちが\n他にもたくさん勝ち進んでるけどね。",
  ui_story_5031_50310702_80_dialog_content = "あそこで手を振って叫んでるのは…\nガルー先輩？",
  ui_story_5031_50310702_81_dialog_content = "シエル、急いで！",
  ui_story_5031_50310702_82_dialog_content = "早く、あの最強スキルを使って！",
  ui_story_5031_50310702_83_dialog_content = "このままじゃ、あたしたち2人とも脱落しちゃう！",
  ui_story_5031_50310702_84_dialog_content = "で、でも「<color=#FFB400>ステュクス</color>」はまだ…",
  ui_story_5031_50310702_85_dialog_content = "うぅ…りょ、了解！\n「脚部装甲状態変更――Ⅱ型」！",
  ui_story_5031_50310702_86_dialog_content = "「エネルギー解放比率50%上昇」…",
  ui_story_5031_50310702_87_dialog_content = "起動！",
  ui_story_5031_50310702_88_dialog_content = "シエルが突っ込んできたわ！",
  ui_story_5031_50310702_89_dialog_content = "あああ――どいてどいて！\n制御不能になっちゃった！",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>ドカン――</color>",
  ui_story_5031_50310702_91_dialog_content = "ああ…\n船の上の建物をつらぬいて、穴が…",
  ui_story_5031_50310702_92_dialog_content = "甲板もひどい有り様ね。",
  ui_story_5031_50310702_93_dialog_content = "ええ、すっごい…\nどこに行ったのかも分からないや。",
  ui_story_5031_50310702_94_dialog_content = "シエルちゃん、大丈夫？",
  ui_story_5031_50310702_95_dialog_content = "イタタタ、あ…あたしは大丈夫。",
  ui_story_5031_50310702_96_dialog_content = "まあ、あなたは大丈夫そうでよかったけど…\nあたしの大事なエメラルド号に、ハデに体当たりしてくれたね～。",
  ui_story_5031_50310702_97_dialog_content = "あっ、ご、ごめんなさい！",
  ui_story_5031_50310702_98_dialog_content = "わざとじゃないの！「ステュクス」のチューニングが甘くて…\nいや、全部あたしの努力不足のせいだ…",
  ui_story_5031_50310702_99_dialog_content = "まぁ、今さら何のミスかを追及しても仕方ないよ。\nそれより、これからどうするのかを考えよ？",
  ui_story_5031_50310702_100_dialog_content = "一番簡単なのは、お金を払って、\n船の壊れたところを修理してもらうことだけど…",
  ui_story_5031_50310702_101_dialog_content = "シエルちゃん、\nそんなお金は持ってなさそうだよね。",
  ui_story_5031_50310702_102_dialog_content = "うん、ごめんなさい…",
  ui_story_5031_50310702_103_dialog_content = "そんなに謝らないでって～。\n元気を出して！",
  ui_story_5031_50310702_104_dialog_content = "そうだ！この後のサーフィンバトルに挑戦してみない？",
  ui_story_5031_50310702_105_dialog_content = "領主のエルビスさんがスポンサーになってくれてるの。\nそれで、1位には特別に賞金も出るって！",
  ui_story_5031_50310702_106_dialog_content = "ホ、ホント！？",
  ui_story_5031_50310702_107_dialog_content = "ホントホント！ええと…\n確か1位の賞金は500万白夜コインぐらいだったっけ。",
  ui_story_5031_50310702_108_dialog_content = "修理費用と大体同じくらいになるんじゃないかな？",
  ui_story_5031_50310702_109_dialog_content = "で、出る！",
  ui_story_5031_50310702_110_dialog_content = "フフフ…まぁ、喜ぶのはまだ早いよ？",
  ui_story_5031_50310702_111_dialog_content = "あたしとメルトちゃんたちも参加するからね～！",
  ui_story_5031_50310702_112_dialog_content = "手加減したりしないよ？\nシエルちゃん。",
  ui_story_5031_50310702_113_dialog_content = "もし、あなたが負けたら…えーっと…\nその子、「ステュクス」だっけ？",
  ui_story_5031_50310702_114_dialog_content = "もらっちゃおうかな～。",
  ui_story_5031_50310702_115_dialog_content = "…ダ、ダメ！",
  ui_story_5031_50310702_116_dialog_content = "アハハ…あたしも研究のために見せてもらいたいだけだよ。\n別に奪ったり、何かするつもりはないよ。",
  ui_story_5031_50310702_117_dialog_content = "終わったら、ちゃんと返すから～。",
  ui_story_5031_50310702_118_dialog_content = "ごめんなさい。",
  ui_story_5031_50310702_119_dialog_content = "これだけは…ダメ…",
  ui_story_5031_50310801_1_dialog_content = "みんな～、夏の海風とサービスのフルーツで\n元気いっぱいになったかな？",
  ui_story_5031_50310801_2_dialog_content = "しっかり休めたら、\n次の試合に行くよ～！",
  ui_story_5031_50310801_3_dialog_content = "おー！！！！",
  ui_story_5031_50310801_4_dialog_content = "盛り上がってるね！\nみんなもウズウズしてるみたい！",
  ui_story_5031_50310801_5_dialog_content = "それでは次のバトルは～…\n今までの熱闘の汗を洗い流そう！",
  ui_story_5031_50310801_6_dialog_content = "炎のようにアツい太陽の下で、\n涼しく爽やかな海水浴を楽しもう！",
  ui_story_5031_50310801_7_dialog_content = "みんなお待ちかねの――\n<size=45>サーフィンバトル！</size>",
  ui_story_5031_50310801_8_dialog_content = "ワーッ！！",
  ui_story_5031_50310801_9_dialog_content = "ハーバーシティの伝統行事ということで、\nこの種目で1位になったチームには…",
  ui_story_5031_50310801_10_dialog_content = "領主、エルビス様から特別に\n<color=#FFB400>500万白夜コイン</color>の賞金が贈られます！",
  ui_story_5031_50310801_11_dialog_content = "ご、500万！？",
  ui_story_5031_50310801_12_dialog_content = "500万！？",
  ui_story_5031_50310801_13_dialog_content = "PlayerName、バイス、落ち着いて。",
  ui_story_5031_50310801_14_dialog_content = "私たちの本当の目的を忘れないで。",
  ui_story_5031_50310801_15_dialog_content = "分かってるよ…でも、フィアを手伝って珍獣を助けることと、\n賞金を手に入れることは矛盾しないでしょ？",
  ui_story_5031_50310801_16_dialog_content = "でも、ハーバーシティって、\n本当に余裕があるのね。",
  ui_story_5031_50310801_17_dialog_content = "確かにここ数年、\n目覚ましい発展を遂げているわ。",
  ui_story_5031_50310801_18_dialog_content = "それでも貴族の領主が住民の享楽（きょうらく）のために\n大金を投じるなんて、本当に珍しいことよ。",
  ui_story_5031_50310801_19_dialog_content = "ハーバーシティには聡明な領主がいる。\nしっかりと統治されているのも納得がいくわね。",
  ui_story_5031_50310801_20_dialog_content = "最近のカレンは本当にがんばってるわね。",
  ui_story_5031_50310801_21_dialog_content = "休みに来てる時でも、\n国家の発展がどうとか考えてるんだもの。",
  ui_story_5031_50310801_22_dialog_content = "ああ、ごめんなさい。\nつまらない話をしてしまったわ…",
  ui_story_5031_50310801_23_dialog_content = "ううん、そんなことないわ！\nそういうつもりで言ったんじゃないの。",
  ui_story_5031_50310801_24_dialog_content = "ただ、カレンが疲れすぎてないか心配なだけ。",
  ui_story_5031_50310801_25_dialog_content = "そうだよ、カレン。気分転換に来てるんだから、\n少しはリラックスしなくちゃ！",
  ui_story_5031_50310801_26_dialog_content = "その点はフィアを見習った方がいいよ。\nほら、あんなに嬉しそうにパイナップルにかじりついてる。",
  ui_story_5031_50310801_27_dialog_content = "あれは自分が何のためにここに来たのか、\n完全に忘れてる顔だよ。",
  ui_story_5031_50310801_28_dialog_content = "う～ん、甘～い！！",
  ui_story_5031_50310801_29_dialog_content = "お祭りってサイコー！\nタダでフルーツも食べられるなんて！！",
  ui_story_5031_50310801_30_dialog_content = "フフ…確かにその通りね。",
  ui_story_5031_50310801_31_dialog_content = "彼女には見習うべき部分がたくさんあるわ。",
  ui_story_5031_50310801_32_dialog_content = "<size=33>フィアだけじゃない…バイスやPlayerNameにも、ね…</size>",
  ui_story_5031_50310801_33_dialog_content = "暗鬼をすべて倒しきることなどできぬ。\nそれは余もお前も理解しているはずだ。",
  ui_story_5031_50310801_34_dialog_content = "君主たる者、やみくもに最前線へと飛び出し、\n1人だけですべてを食い止めようとしてはならぬ。",
  ui_story_5031_50310801_35_dialog_content = "それでは、お前自身が犠牲になるだけでは済まない。\nお前を信頼して付き従う者までが犠牲になるのだ。",
  ui_story_5031_50310801_36_dialog_content = "…",
  ui_story_5031_50310801_37_dialog_content = "真剣に考えるがいい。\nお前がPlayerNameと旅すること、余が許しているのは何故か。",
  ui_story_5031_50310801_38_dialog_content = "私は…",
  ui_story_5031_50310801_39_dialog_content = "お前には王としての資質がまだ足らぬ。",
  ui_story_5031_50310801_40_dialog_content = "…はい。",
  ui_story_5031_50310801_41_dialog_content = "――カレン？カレン！",
  ui_story_5031_50310801_42_dialog_content = "えっ？…ごめんなさい。\n何か言ったかしら？",
  ui_story_5031_50310801_43_dialog_content = "そろそろ着替えに行こうって言ったの。\nサーフィンバトルって、きっと濡れるでしょ。",
  ui_story_5031_50310801_44_dialog_content = "せっかくの新しい服、\n汚すわけにはいかないんじゃない？",
  ui_story_5031_50310801_45_dialog_content = "ああ、そうね…",
  ui_story_5031_50310801_46_dialog_content = "…いえ、着替えなど持って来ていたかしら？",
  ui_story_5031_50310801_47_dialog_content = "フフフ…それはもちろん――",
  ui_story_5031_50310801_48_dialog_content = "水着に着替えるのよ！",
  ui_story_5031_50310801_49_dialog_content = "わ～！カレンお姉ちゃんもバイスお姉ちゃんもきれい！",
  ui_story_5031_50310801_50_dialog_content = "エヘヘ…ありがとう、フィアちゃん。",
  ui_story_5031_50310801_51_dialog_content = "いつの間に私の水着まで持ってきていたの？",
  ui_story_5031_50310801_52_dialog_content = "海に来ると分かってて、\n水着を用意しないなんてありえないでしょ！",
  ui_story_5031_50310801_53_dialog_content = "まぁ、今まで水上のプログラムじゃなかったから、\n私も忘れてたけど…",
  ui_story_5031_50310801_54_dialog_content = "いいな～、フィアも水着欲しい！",
  ui_story_5031_50310801_55_dialog_content = "お祭りが終わったら、一緒にハーバーシティのお店を探して、\nオーダーメイドすればいいわ！",
  ui_story_5031_50310801_56_dialog_content = "ホント！？ありがとう、バイスお姉ちゃん！",
  ui_story_5031_50310801_57_dialog_content = "わぁ、フィア、服のオーダーメイドって初めて！\nうれしい！",
  ui_story_5031_50310801_58_dialog_content = "それから、この前見つけたかわいい食器セットも\n買えるかもしれないわ！",
  ui_story_5031_50310801_59_dialog_content = "やったー！",
  ui_story_5031_50310801_60_dialog_content = "それから…",
  ui_story_5031_50310801_61_dialog_content = "オホン、あの、ちょっと…？",
  ui_story_5031_50310801_62_dialog_content = "PlayerName、どうかしたの？",
  ui_story_5031_50310801_63_dialog_content = "すごく盛り上がっているところに\n水を差すようで悪いんだけど…",
  ui_story_5031_50310801_64_dialog_content = "僕、サーフィンなんてできないよ？",
  ui_story_5031_50310801_65_dialog_content = "<size=45>えぇっ！？</size>",
  ui_story_5031_50310801_66_dialog_content = "じゃあ、フィアのオーダーメイド水着は？",
  ui_story_5031_50310801_67_dialog_content = "そっちの心配！？\n…僕たちの本当の目的、珍獣だってこと忘れたの？",
  ui_story_5031_50310801_68_dialog_content = "うっ…うぅ、フィアの水着、\nそれから「海雲クジラ」…",
  ui_story_5031_50310801_69_dialog_content = "どっちも無理なの？\nうっ、うわああああん！",
  ui_story_5031_50310801_70_dialog_content = "あっ、ごめん…\nフィア、泣かないで…",
  ui_story_5031_50310801_71_dialog_content = "出来るだけなんとかするよ…\nた、たとえ1位になれなくても…",
  ui_story_5031_50310801_72_dialog_content = "水着ぐらいは僕がお金を出してあげるから！",
  ui_story_5031_50310801_73_dialog_content = "ぐすっ…ホント？",
  ui_story_5031_50310801_74_dialog_content = "ホントだよ。\nカレンとバイスが証人になってくれるでしょ？",
  ui_story_5031_50310801_75_dialog_content = "わ、分かった…",
  ui_story_5031_50310801_76_dialog_content = "ごめんね。状況を把握する前に、\n私が勝った後の妄想をし始めちゃったから…",
  ui_story_5031_50310801_77_dialog_content = "バイスのせいじゃないよ。僕が不器用なのがいけないんだ。\nサーフィンぐらいできないなんて…",
  ui_story_5031_50310801_78_dialog_content = "え？PlayerName、誤解してない？",
  ui_story_5031_50310801_79_dialog_content = "サーフィンって、\nみんなができて当然ってものでもないわよ？",
  ui_story_5031_50310801_80_dialog_content = "私はたまたま習ったことがあるだけ。",
  ui_story_5031_50310801_X80_dialog_content = "そうね。私も子どもの頃にここに来て、\n偶然、その年の大会を見て…",
  ui_story_5031_50310801_X81_dialog_content = "興味を持ったから、\n専門の教師を招いて教えてもらったの。",
  ui_story_5031_50310801_81_dialog_content = "そうなんだ？\nじゃあ、フィアはどこで習ったの？",
  ui_story_5031_50310801_82_dialog_content = "え？フィアは習ったことないよ。",
  ui_story_5031_50310801_83_dialog_content = "何だって！？",
  ui_story_5031_50310801_84_dialog_content = "じゃあ、さっきの大泣きは何だったの！？\n自分だってできないんじゃない！！",
  ui_story_5031_50310801_85_dialog_content = "もう、空の末裔、そんな大声出さないの。\nそんな調子じゃいつまで経っても彼女なんてできないよ～？",
  ui_story_5031_50310801_86_dialog_content = "か、彼女！？",
  ui_story_5031_50310801_87_dialog_content = "何を言ってるの！？\nあっ、逃げるな！！",
  ui_story_5031_50310801_88_dialog_content = "ほらほら！みんな海の方へ行ってるよ！\nあたしたちも早く行こ！",
  ui_story_5031_50310801_89_dialog_content = "逃げ足が速い…！",
  ui_story_5031_50310801_90_dialog_content = "…",
  ui_story_5031_50310801_91_dialog_content = "…",
  ui_story_5031_50310801_92_dialog_content = "（えっ、この雰囲気は何…！？）",
  ui_story_5031_50310801_93_dialog_content = "オホン…じゃ、じゃあ、僕たちも行こうか？",
  ui_story_5031_50310801_94_dialog_content = "ええ、そうね。",
  ui_story_5031_50310801_95_dialog_content = "そうしましょう。",
  ui_story_5031_50310801_96_dialog_content = "（2人とも、何であんなに急いでるんだろう？）",
  ui_story_5031_50310801_97_dialog_content = "そう。両手を平行にして、胸元に置いて。\n両足はそろえて。",
  ui_story_5031_50310801_98_dialog_content = "それから腕の力で体を持ち上げるの。",
  ui_story_5031_50310801_99_dialog_content = "こ、こう？",
  ui_story_5031_50310801_100_dialog_content = "そうよ。視線は前。それでいいわ。",
  ui_story_5031_50310801_101_dialog_content = "波が来たら、素早く体を起こすの。\n両足は肩幅に開いて、背筋を伸ばして。",
  ui_story_5031_50310801_102_dialog_content = "波が来たわ！",
  ui_story_5031_50310801_103_dialog_content = "サーフボードが押されているのを感じる？今よ！",
  ui_story_5031_50310801_104_dialog_content = "わ、分かった！",
  ui_story_5031_50310801_105_dialog_content = "体を起こして…うわっ！",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName！",
  ui_story_5031_50310801_108_dialog_content = "ゴホ、ゴホゴホッ！",
  ui_story_5031_50310801_109_dialog_content = "ぼ、僕は大丈夫。生きてるよ…",
  ui_story_5031_50310801_110_dialog_content = "う～ん、PlayerName、ヘボヘボ～。",
  ui_story_5031_50310801_111_dialog_content = "フィアだってもうサーフボードの上に\n立てるようになったのに。",
  ui_story_5031_50310801_112_dialog_content = "立ってないでしょ！！\nしゃがんでるじゃない！",
  ui_story_5031_50310801_113_dialog_content = "それでも乗れないよりマシだもん！",
  ui_story_5031_50310801_114_dialog_content = "それにカレンお姉ちゃんが、いい方法を教えてくれたの。\nあたしはサーフボードの上でしゃがむだけで十分だよ！",
  ui_story_5031_50310801_115_dialog_content = "お魚の群れとお話しして、サーフボードを押してもらうから！\nこれは誰にもマネできないでしょ～？",
  ui_story_5031_50310801_116_dialog_content = "君って人は…",
  ui_story_5031_50310801_117_dialog_content = "時間でーす！！！",
  ui_story_5031_50310801_118_dialog_content = "わぁ！たくさんの選手が海の中で\n練習してるのが見えるよ！やる気満々みたい！",
  ui_story_5031_50310801_119_dialog_content = "500万白夜コインの魅力に引き寄せられたかな～？",
  ui_story_5031_50310801_120_dialog_content = "ハハハハハ！",
  ui_story_5031_50310801_121_dialog_content = "アハハ、冗談はさておき…",
  ui_story_5031_50310801_122_dialog_content = "今からルールを説明するよ！",
  ui_story_5031_50310801_123_dialog_content = "ルールは今までと同じ！最大4人1組で、\n順番にコース内でサーフィンをしてもらうよ。",
  ui_story_5031_50310801_124_dialog_content = "人数の足りないチームは、\n自由に順番を組んでね。",
  ui_story_5031_50310801_125_dialog_content = "各チーム、上位2人の得点の平均点で計算するから、\n2人いれば出場できるよ！",
  ui_story_5031_50310801_126_dialog_content = "今までと同じで、暗鬼の幻を倒した場合も点がもらえるよ。\nただし！今回は海に落ちても脱落せず、競技が続くよ。",
  ui_story_5031_50310801_127_dialog_content = "暗鬼の撃破点以外に、\n個人点の50%はサーフィンの技術点から計算されるよ。",
  ui_story_5031_50310801_128_dialog_content = "だから、出場順はしっかり考えて決めてね！\nそれが勝利のカギになるかも？",
  ui_story_5031_50310801_129_dialog_content = "――あっ、うっかりあたしたちの作戦をバラしちゃった！\n競争が激しくなっちゃう！",
  ui_story_5031_50310801_130_dialog_content = "ワハハハハハハ！",
  ui_story_5031_50310801_131_dialog_content = "ま、皆に楽しんでもらえれば、\nそれでいっか！",
  ui_story_5031_50310801_132_dialog_content = "それじゃあ、さっそく第1ラウンド！",
  ui_story_5031_50310801_133_dialog_content = "各チーム、準備ができたら、\n1人目の勇者さんをスタート地点で待機させてね！",
  ui_story_5031_50310801_134_dialog_content = "最後に、これは秘密だけど――",
  ui_story_5031_50310801_135_dialog_content = "あたしたちのチームの一番手は、\nあたしだよ！",
  ui_story_5031_50310801_136_dialog_content = "うおおおお――！",
  ui_story_5031_50310801_137_dialog_content = "レインボーちゃん、がんばれー！",
  ui_story_5031_50310801_138_dialog_content = "レインボー、すっかり人気者になってるね。",
  ui_story_5031_50310801_139_dialog_content = "どうしよう…あんなに自信満々だ。\nそうとう得意なんだろうね。",
  ui_story_5031_50310801_140_dialog_content = "どうしようもないわ。\n2人分しか数えられないルールだけは都合がいいわね。",
  ui_story_5031_50310801_141_dialog_content = "それなら、順番が大事ね。",
  ui_story_5031_50310801_142_dialog_content = "レインボーさんが一番手なら、私たちは…",
  ui_story_5031_50310801_143_dialog_content = "ふふん！もちろん、\n最強のあたしが迎え撃つべきでしょ！",
  ui_story_5031_50310801_144_dialog_content = "…君が？最強？",
  ui_story_5031_50310801_145_dialog_content = "何が言いたいの！？",
  ui_story_5031_50310801_146_dialog_content = "忘れないで。さっきカレンお姉ちゃんに教わった方法、\nフィアにしかできないんだから！",
  ui_story_5031_50310801_147_dialog_content = "きっと一番になれるもん！",
  ui_story_5031_50310801_148_dialog_content = "PlayerName、\nあたしが勝って帰って来るのを待ってなさい！",
  ui_story_5031_50310801_149_dialog_content = "…本当に大丈夫かな？",
  ui_story_5031_50310801_150_dialog_content = "フィアの様子を見てたら、\n急に心配になってきた…",
  ui_story_5031_50310801_151_dialog_content = "オホン…司会者が出場のために飛び出していきましたので…\nこの種目は僕が司会を務めさせていただきます。",
  ui_story_5031_50310801_152_dialog_content = "ここからだと、\n海に浮かぶ皆さんがとても小さく見えますね。",
  ui_story_5031_50310801_153_dialog_content = "しかし、そのような小さな存在であっても、\n自然のリズムにしたがう術を理解し、このスポーツを編み出したのです。",
  ui_story_5031_50310801_154_dialog_content = "これは究極の美と知恵を合わせた芸術と言えるでしょう…",
  ui_story_5031_50310801_155_dialog_content = "それでは皆さん、がんばってください。\n海の旋律を操り、押し寄せる…",
  ui_story_5031_50310801_156_dialog_content = "…ごたくはいい！早く始めろ！！",
  ui_story_5031_50310801_157_dialog_content = "こっちは試合が観たいんだ！",
  ui_story_5031_50310801_158_dialog_content = "まったく。やはり愚鈍な凡才には理解できませんか…",
  ui_story_5031_50310801_159_dialog_content = "辛抱できないというのでしたら、\nただ今よりスタートです。",
  ui_story_5031_50310801_160_dialog_content = "…",
  ui_story_5031_50310801_161_dialog_content = "えっ？もう始まったのか！？",
  ui_story_5031_50310801_162_dialog_content = "あいつ、司会をしたことあるのか！？",
  ui_story_5031_50310801_163_dialog_content = "アハハ…さすがは団長…",
  ui_story_5031_50310801_164_dialog_content = "ってことで、お先に！",
  ui_story_5031_50310801_165_dialog_content = "あっ、シエル！\n始まってるよ！急いで出発して！",
  ui_story_5031_50310801_166_dialog_content = "えっ、始まってる！？合図とかは！？",
  ui_story_5031_50310801_167_dialog_content = "と、とにかく…「モードチェンジ――ジェットモード」！",
  ui_story_5031_50310801_168_dialog_content = "あの2人、スーツの動力で動いてない…？",
  ui_story_5031_50310801_169_dialog_content = "起こした波に飲まれて、\n横の出場者が海に落ちてるし…",
  ui_story_5031_50310801_170_dialog_content = "これ、競技になるの…？",
  ui_story_5031_50310801_171_dialog_content = "幸い、フィアの位置は少し離れているから、\nまだバランスを保っているわね。",
  ui_story_5031_50310801_172_dialog_content = "うおおお――！\nレインボーちゃんが飛び出したぞ！",
  ui_story_5031_50310801_173_dialog_content = "わぁ！あのターンジャンプ、カッコいい！",
  ui_story_5031_50310801_174_dialog_content = "あのパワードスーツの女の子もすごいぞ。\n反応が速い！",
  ui_story_5031_50310801_175_dialog_content = "でも、レインボーちゃんと比べると美しさが足りないかな…",
  ui_story_5031_50310801_176_dialog_content = "フッ…そんなに簡単には終わりませんよ。",
  ui_story_5031_50310801_177_dialog_content = "雄叫びをあげろ！\n深海の呪われし霊たちよ！",
  ui_story_5031_50310801_178_dialog_content = "グアア！",
  ui_story_5031_50310801_179_dialog_content = "出た！",
  ui_story_5031_50310801_180_dialog_content = "アハハ！レインボー姐がキレちゃう！",
  ui_story_5031_50310801_181_dialog_content = "レ、レインボー姐さん、\n気をつけて…",
  ui_story_5031_50310801_182_dialog_content = "う、海の中から暗鬼が飛び出してくるなんて！",
  ui_story_5031_50310801_183_dialog_content = "これはちょっと大変…あっ！",
  ui_story_5031_50310801_184_dialog_content = "レ、レインボーさん！？",
  ui_story_5031_50310801_185_dialog_content = "オラオラオラオラ！！",
  ui_story_5031_50310801_186_dialog_content = "もうガマンできない――ウジ虫どもが！",
  ui_story_5031_50310801_187_dialog_content = "<size=45>みんなくたばれ！</size>",
  ui_story_5031_50310801_188_dialog_content = "また顔色が悪いですね。\n先ほどの…ランカのことを考えているのですか？",
  ui_story_5031_50310802_X1_dialog_content = "また顔色が悪いですね。\n先ほどの…ランカのことを考えているのですか？",
  ui_story_5031_50310802_1_dialog_content = "あっ、ああ…そうだ。",
  ui_story_5031_50310802_2_dialog_content = "フルーツを持ってきましたよ。\n水分をとらないと。",
  ui_story_5031_50310802_3_dialog_content = "ありがとう、ジェノ。",
  ui_story_5031_50310802_4_dialog_content = "さきほど彼女に飲ませた薬…\nあれがあなたの言う、解決策ですか？",
  ui_story_5031_50310802_5_dialog_content = "いや…あれは私が古文書の記録をもとに作り出した薬だ。\n苦痛が一時的に収まるだけだ。",
  ui_story_5031_50310802_6_dialog_content = "あなたが？",
  ui_story_5031_50310802_7_dialog_content = "昔は料理人になりたがっていましたね。\nそれがどうして薬の調合になるのです？",
  ui_story_5031_50310802_8_dialog_content = "フフ…ハーバーシティには有名な料理人なら山ほどいるが、\n「モドリー失調症」を治せる者は誰もいないからな。",
  ui_story_5031_50310802_9_dialog_content = "だから自分の夢を捨てて、\n自分がその偉大な誰かになろうとしたのですか？",
  ui_story_5031_50310802_10_dialog_content = "偉大かどうかなど考えたこともない。\n私はただ、もうこの病で苦しむ人を見たくないと思っただけだ。",
  ui_story_5031_50310802_11_dialog_content = "それに、私は薬師でも何でもない。\nただ書物を読みふけって、調べ事をするのが好きなだけだ。",
  ui_story_5031_50310802_12_dialog_content = "「モドリー失調症」を完全に治せるようになったら、\n私も自分のやりたいことができるようになるさ。",
  ui_story_5031_50310802_13_dialog_content = "その時には何を？",
  ui_story_5031_50310802_14_dialog_content = "大陸の各地に、\n食事もできる上等な美術館を開くかもな。",
  ui_story_5031_50310802_15_dialog_content = "まだその約束を覚えていたのですか。",
  ui_story_5031_50310802_16_dialog_content = "何年も経っているので、\nもう忘れているかと思っていました。",
  ui_story_5031_50310802_17_dialog_content = "全部覚えているさ。\nお前が私の肖像画を描くと約束したこともな。",
  ui_story_5031_50310802_18_dialog_content = "ハーバーシティの美術館には、\nまだ領主である私の肖像画が掛かっていない。",
  ui_story_5031_50310802_19_dialog_content = "…",
  ui_story_5031_50310802_20_dialog_content = "それで、僕に何か手伝えることはありますか？",
  ui_story_5031_50310802_21_dialog_content = "何？",
  ui_story_5031_50310802_22_dialog_content = "「モドリー失調症」ですよ。\n僕に何か手伝えることはありますか？",
  ui_story_5031_50310802_23_dialog_content = "…",
  ui_story_5031_50310802_24_dialog_content = "実は…",
  ui_story_5031_50310802_25_dialog_content = "うおお！！レインボーちゃん、\nメチャクチャ強いぞ！",
  ui_story_5031_50310802_26_dialog_content = "美しさと力強さのコンビネーション！\nまさにパーフェクトだ！",
  ui_story_5031_50310802_27_dialog_content = "…今、何と？",
  ui_story_5031_50310802_28_dialog_content = "…何でもない。\nまずは試合を観ようじゃないか。",
  ui_story_5031_50310802_29_dialog_content = "審判の仕事をしっかりしないと、\n戦っている選手たちに申し訳が立たないからな。",
  ui_story_5031_50310802_30_dialog_content = "レ、レインボー、すごく強いなぁ。\nでも、何だか怖いんだけど…",
  ui_story_5031_50310802_31_dialog_content = "そ、そうね…",
  ui_story_5031_50310802_32_dialog_content = "モヤシくん、レインボー姐のことを\nそんな風に言っちゃダメだよ。",
  ui_story_5031_50310802_33_dialog_content = "そうそう～。\nメル姉の想い人でもダメだよ～。",
  ui_story_5031_50310802_34_dialog_content = "あっ、ごめん。\nそんなつもりじゃなかったんだ！",
  ui_story_5031_50310802_35_dialog_content = "ただ、あまりにすさまじい闘志だから\n脱帽したというか、驚かされたというか…",
  ui_story_5031_50310802_36_dialog_content = "サプ、変なこと言わないの…",
  ui_story_5031_50310802_37_dialog_content = "レインボー姐さんは\n暗鬼を憎んでいるから、ああなってしまうの。",
  ui_story_5031_50310802_38_dialog_content = "暗鬼を憎んでいる？",
  ui_story_5031_50310802_39_dialog_content = "そう…",
  ui_story_5031_50310802_40_dialog_content = "レインボー姐の故郷は、\n暗鬼に滅ぼされちゃったんだって。",
  ui_story_5031_50310802_41_dialog_content = "そうそう。\n友達や家族も、皆亡くしちゃって…",
  ui_story_5031_50310802_42_dialog_content = "だからレインボー姐、\n暗鬼を見るとあんな風になっちゃうんだ。",
  ui_story_5031_50310802_43_dialog_content = "でも、普段のレインボー姐はすごくいい人よ。\nあんな風になるのは、暗鬼を見た時だけ。",
  ui_story_5031_50310802_44_dialog_content = "うん！ファム、レインボー姐が一番好き！",
  ui_story_5031_50310802_45_dialog_content = "私も。いつも怖い顔してる団長に比べたら、\nレインボー姐の方がずっといい人だしね～。",
  ui_story_5031_50310802_46_dialog_content = "だ、団長だって悪い人じゃないわ…",
  ui_story_5031_50310802_47_dialog_content = "そう思ってるのはメル姉だけだよ！",
  ui_story_5031_50310802_48_dialog_content = "そんな事情があったんだ…",
  ui_story_5031_50310802_49_dialog_content = "あれだけ陽気で明るい雰囲気だから、\nそんな過去があったなんて、全然思わなかったわ…",
  ui_story_5031_50310802_50_dialog_content = "悲しみや怒りをかてに強く成長し、\nひまわりのように輝く女性になった…",
  ui_story_5031_50310802_51_dialog_content = "尊敬に値するわね。",
  ui_story_5031_50310802_52_dialog_content = "その通りだね。\nまぁ、僕が一番手じゃなくてよかったよ…",
  ui_story_5031_50310802_53_dialog_content = "…そう言えば、フィアは？",
  ui_story_5031_50310802_54_dialog_content = "あ、あんたたち！\nバラバラにサーフボードを押すんじゃないの！",
  ui_story_5031_50310802_55_dialog_content = "ちゃんと向きをそろえて…",
  ui_story_5031_50310802_56_dialog_content = "そっちじゃない！反対！\nそっちじゃないって…あっ！",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5031_50310802_58_dialog_content = "ハハハハ！あの女の子、\nその場でクルクル回ってるぞ？",
  ui_story_5031_50310802_59_dialog_content = "しかも海に落ちちゃったし…\nこれじゃ技術点は厳しそうだね。",
  ui_story_5031_50310802_60_dialog_content = "プハーッ！ゲホゲホ…",
  ui_story_5031_50310802_61_dialog_content = "魚たちのバカ！",
  ui_story_5031_50310802_62_dialog_content = "後でPlayerNameに笑われるんだろうな…\nうぅ…",
  ui_story_5031_50310802_63_dialog_content = "たぶん、フィアは\n僕に笑われるとでも思ってるんじゃないかな。",
  ui_story_5031_50310802_64_dialog_content = "でも…プッ…",
  ui_story_5031_50310802_65_dialog_content = "アハハ…今のは面白かった！",
  ui_story_5031_50310802_66_dialog_content = "PlayerName、大笑いしすぎよ…",
  ui_story_5031_50310802_67_dialog_content = "私のせいね…魚の群れが協調性に\n問題があるとまで、考えが至らなかったわ。",
  ui_story_5031_50310802_68_dialog_content = "動物と交流できるフィアの能力なら、魚の群れを指揮して\nサーフボードを動かせると思ったけれど…非現実的すぎたわね。",
  ui_story_5031_50310802_69_dialog_content = "いやいや、フィアが自分で\n大丈夫って言ったんだし…",
  ui_story_5031_50310802_70_dialog_content = "カレン、いつも責任を自分で背負い込んじゃダメだよ。\nただの遊びなんだから。深刻に考えることはないって。",
  ui_story_5031_50310802_71_dialog_content = "…そうね。",
  ui_story_5031_50310802_72_dialog_content = "試合状況を解説しましょう――\nまぁ、ご立派な目が付いているなら、おのずと分かるはずですが。",
  ui_story_5031_50310802_73_dialog_content = "現在リードを争うのは、\n当サーカス団の団員レインボー選手、そして啓光のシエル選手。",
  ui_story_5031_50310802_74_dialog_content = "2人は倒した暗鬼の数もほぼ互角。\n技術点においても他の選手を上回っています。",
  ui_story_5031_50310802_75_dialog_content = "しかし、会場の観客、審査委員の様子からすると、\nレインボー選手の技術が一枚上のようです。",
  ui_story_5031_50310802_76_dialog_content = "では、その他見どころの無い人たちもがんばってください。",
  ui_story_5031_50310802_77_dialog_content = "波に翻弄（ほんろう）され、\n浮き沈みを続けるといいでしょう。",
  ui_story_5031_50310802_78_dialog_content = "…",
  ui_story_5031_50310802_79_dialog_content = "うわぁぁん、見てなさいよ！！",
  ui_story_5031_50310802_80_dialog_content = "海の底に戻りな！",
  ui_story_5031_50310802_81_dialog_content = "グアア！",
  ui_story_5031_50310802_82_dialog_content = "はぁ…幻だって分かってるけど、\nガマンできなくなっちゃう…",
  ui_story_5031_50310802_83_dialog_content = "それに、キレイにした後は気分がいいね！",
  ui_story_5031_50310802_84_dialog_content = "つ、強い…",
  ui_story_5031_50310802_85_dialog_content = "え？あなたもなかなかやるじゃない！",
  ui_story_5031_50310802_86_dialog_content = "海と一緒に育ったあたしと張り合えるなんて、\n見直しちゃったよ！",
  ui_story_5031_50310802_87_dialog_content = "いや、あたしは暗鬼をやっつけて\n点を稼いだだけだから…",
  ui_story_5031_50310802_88_dialog_content = "サーフィンの方はそんなでも…",
  ui_story_5031_50310802_89_dialog_content = "ルールを利用してうまく立ち回ってるだけ…",
  ui_story_5031_50310802_90_dialog_content = "うーん、シエルちゃん、本当に変わってるね～。",
  ui_story_5031_50310802_91_dialog_content = "か、変わってる？",
  ui_story_5031_50310802_92_dialog_content = "だってほら…あたしはほめてるのに、\n自分はダメだって言い続けてるし、悲しそうな顔してる。",
  ui_story_5031_50310802_93_dialog_content = "暗鬼を攻撃して点を稼げるのは、もともとそういうルールでしょ？\nずるいことなんかないよ？",
  ui_story_5031_50310802_94_dialog_content = "…",
  ui_story_5031_50310802_95_dialog_content = "シエルちゃんはデキる人だよ。\nなんでもっと自分を信じてあげないの？",
  ui_story_5031_50310802_96_dialog_content = "そんなにモジモジしてたら、\nできることだって失敗しちゃうよ～。",
  ui_story_5031_50310802_97_dialog_content = "あたし…",
  ui_story_5031_50310802_98_dialog_content = "グア！",
  ui_story_5031_50310802_99_dialog_content = "暗鬼！逃がさない！！",
  ui_story_5031_50310802_100_dialog_content = "あたしが…できる？",
  ui_story_5031_50310802_101_dialog_content = "ヘヘ…エヘヘヘ…",
  ui_story_5031_50310802_102_dialog_content = "なら…レインボーさんの\n期待を裏切るわけには…絶対にいかない！",
  ui_story_5031_50310802_103_dialog_content = "「アームチェンジ――Ⅱ型」！",
  ui_story_5031_50310802_104_dialog_content = "「エネルギー解放比率60%上昇」！",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5031_50310802_106_dialog_content = "シ、シエル！？",
  ui_story_5031_50310802_107_dialog_content = "また出力を上げた！？",
  ui_story_5031_50310802_108_dialog_content = "でも、「ステュクス」は…",
  ui_story_5031_50310802_109_dialog_content = "おい！あのメカ娘、\n急に海面めがけて噴射し始めたぞ！",
  ui_story_5031_50310802_110_dialog_content = "うわっ！船まで揺れてるぞ。\n転覆しないだろうな…",
  ui_story_5031_50310802_111_dialog_content = "飛んだ！回転ジャンプでもやって、\n技術点を狙うつもりか？",
  ui_story_5031_50310802_112_dialog_content = "いや、違う。あれは…",
  ui_story_5031_50310802_113_dialog_content = "暗鬼だ！海の中の暗鬼を吸いだしてるぞ！",
  ui_story_5031_50310802_114_dialog_content = "わっ！これは…",
  ui_story_5031_50310802_115_dialog_content = "カッコいいね！！",
  ui_story_5031_50310802_116_dialog_content = "あたしには高難度の技はできない…\nなら、残りの50%の得点に頼るしかない！",
  ui_story_5031_50310802_117_dialog_content = "「ステュクス」、掃射！",
  ui_story_5031_50310802_118_dialog_content = "――パワードスーツの高出力を生かして、\n広範囲を攻撃したというわけですね。",
  ui_story_5031_50310802_119_dialog_content = "重量があるパワードスーツでは、\n軽やかな技が繰り出せませんが…",
  ui_story_5031_50310802_120_dialog_content = "彼女は己の強みを活かして、\n一瞬で大量の暗鬼を倒し、見事に逆転したということです。",
  ui_story_5031_50310802_121_dialog_content = "逆境の中でもあきらめずに突破口を見つけたとは、\nまさに尊敬に値する。",
  ui_story_5031_50310802_122_dialog_content = "では、領主様直々に、\n彼女の得点を計算していただきましょう。",
  ui_story_5031_50310802_123_dialog_content = "フッ、分かったよ…団長殿。",
  ui_story_5031_50310802_124_dialog_content = "こ、これで…",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>ガチャ、ガチャン！</color>",
  ui_story_5031_50310802_126_dialog_content = "あれ？",
  ui_story_5031_50310802_127_dialog_content = "まずい。やっぱり「ステュクス」が\nあんな出力に耐えられなかった…",
  ui_story_5031_50310802_128_dialog_content = "あああ！お、落ちちゃう！",
  ui_story_5031_50310802_129_dialog_content = "シエル！",
  ui_story_5031_50310802_130_dialog_content = "よいしょっと！",
  ui_story_5031_50310802_131_dialog_content = "あれ？あんたは…",
  ui_story_5031_50310802_132_dialog_content = "うっ…",
  ui_story_5031_50310802_133_dialog_content = "目を開けて。ちゃんと受け止めたから～。",
  ui_story_5031_50310802_134_dialog_content = "え？",
  ui_story_5031_50310802_135_dialog_content = "れ、レインボーさん？",
  ui_story_5031_50310802_136_dialog_content = "今のはムチャしすぎだね～。チューニングができてないのに、\nあんなに出力を上げるなんて。",
  ui_story_5031_50310802_137_dialog_content = "ご、ごめんなさい…",
  ui_story_5031_50310802_138_dialog_content = "「ステュクス」、さっきの爆発の後で、\nまだ完全に直せてなかったんだ…",
  ui_story_5031_50310802_139_dialog_content = "レインボーさんに迷惑かけちゃった…",
  ui_story_5031_50310802_140_dialog_content = "そうだったんだ。残念だったね～。",
  ui_story_5031_50310802_141_dialog_content = "完全に直ったら、きっとすごいんだろうね！\nワクワクするな～。",
  ui_story_5031_50310802_142_dialog_content = "…",
  ui_story_5031_50310802_143_dialog_content = "あの、レインボーさん…",
  ui_story_5031_50310802_144_dialog_content = "ん？どうしたの？",
  ui_story_5031_50310802_145_dialog_content = "どうして助けてくれたの…？\nあたしが海に落ちれば、かなり減点されたはずなのに…",
  ui_story_5031_50310802_146_dialog_content = "えっ？うーん、それはね…",
  ui_story_5031_50310802_147_dialog_content = "たぶん、500万白夜コインよりも――",
  ui_story_5031_50310802_148_dialog_content = "あなたに興味があるからかな～。",
  ui_story_5031_50310901_1_dialog_content = "第1ラウンド終了です。第2ラウンドに出場する選手は、\n指定のスタート地点に集合してください。",
  ui_story_5031_50310901_2_dialog_content = "待機中に前のラウンドの得点を集計します。",
  ui_story_5031_50310901_3_dialog_content = "フィアちゃん、悲しむことはないわ。\nまだチャンスはあるから！",
  ui_story_5031_50310901_4_dialog_content = "そうそう。責任を感じることはないよ。\n最初からいい成績を出せるとは思ってなかったし…",
  ui_story_5031_50310901_5_dialog_content = "うわあああん！",
  ui_story_5031_50310901_6_dialog_content = "PlayerNameのバカ！",
  ui_story_5031_50310901_7_dialog_content = "えっ？バカって…",
  ui_story_5031_50310901_8_dialog_content = "ぼ、僕はただなぐさめようとしただけで…",
  ui_story_5031_50310901_9_dialog_content = "はいはい。\nとりあえず、PlayerNameは黙ってて！",
  ui_story_5031_50310901_10_dialog_content = "…",
  ui_story_5031_50310901_11_dialog_content = "次のラウンドの準備をするわよ。",
  ui_story_5031_50310901_12_dialog_content = "レインボーたちから聞いたわ。\n次はメルトが出場するそうよ。",
  ui_story_5031_50310901_13_dialog_content = "あら…？フィア、どうかしたの？",
  ui_story_5031_50310901_14_dialog_content = "ううう、カレンお姉ちゃん、\nPlayerNameが…",
  ui_story_5031_50310901_15_dialog_content = "ちょっと！？僕は何もしてないよ！",
  ui_story_5031_50310901_16_dialog_content = "フィア、今はとりあえず、\n次のラウンドの準備をしましょ？",
  ui_story_5031_50310901_17_dialog_content = "フィアも賞き…じゃなくて、水着が欲しいし、\n「海雲クジラ」も助けないと。ね？",
  ui_story_5031_50310901_18_dialog_content = "ううっ…うん…",
  ui_story_5031_50310901_19_dialog_content = "じゃあ、フィアも涙を拭いて…\n次は誰が出るか、相談しましょ！",
  ui_story_5031_50310901_20_dialog_content = "じゃあ…次はPlayerNameお兄ちゃんに出てもらおうよ！",
  ui_story_5031_50310901_21_dialog_content = "え！？",
  ui_story_5031_50310901_22_dialog_content = "フン！さっきフィアが海に落ちた時、\n笑ってたでしょ！",
  ui_story_5031_50310901_23_dialog_content = "今度はフィアが笑う番だもんね！",
  ui_story_5031_50310901_24_dialog_content = "なんで僕が笑ってたことを知って…\nいや、それだと理にかなってないよ！",
  ui_story_5031_50310901_25_dialog_content = "とにかく大事なのは、試合に勝つことでしょ？",
  ui_story_5031_50310901_26_dialog_content = "どうせ必要なのは2人分の成績だけなんだし、\n僕が出る必要なんて、まったく…",
  ui_story_5031_50310901_27_dialog_content = "PlayerName、忘れたの？\nあなたとフィアは2人で1人分として扱われること。",
  ui_story_5031_50310901_28_dialog_content = "あなたたち2人の成績は合算よ。",
  ui_story_5031_50310901_29_dialog_content = "…た、確かにそう言われれば…",
  ui_story_5031_50310901_30_dialog_content = "私やバイスが出場する時にどんな強敵が現れるか、\nまだ分からないわ。",
  ui_story_5031_50310901_31_dialog_content = "念のため、あなたも出場した方がいい。",
  ui_story_5031_50310901_32_dialog_content = "ってことは…次のラウンドは\nPlayerNameに出てもらうのがいいってこと？",
  ui_story_5031_50310901_33_dialog_content = "そうね。あの三姉妹で\n性格が一番おとなしいのはメルトでしょうし…",
  ui_story_5031_50310901_34_dialog_content = "ガルー先輩も、\nサーフィンはあまり得意じゃなさそう…",
  ui_story_5031_50310901_35_dialog_content = "つまり…",
  ui_story_5031_50310901_36_dialog_content = "ということは…",
  ui_story_5031_50310901_37_dialog_content = "…分かったよ。僕が出ればいいんでしょ！！\nこっちを見つめないで！",
  ui_story_5031_50310901_38_dialog_content = "ふふふ、PlayerName、がんばってね～。",
  ui_story_5031_50310901_39_dialog_content = "あまり重荷に感じないで。\n私たちが教えたコツを思いだせばいいの。",
  ui_story_5031_50310901_40_dialog_content = "もしできなくても、問題ないわ。",
  ui_story_5031_50310901_41_dialog_content = "うん、わかったよ。",
  ui_story_5031_50310901_42_dialog_content = "フン！PlayerName、\nあたしの足を引っ張らないでよね！",
  ui_story_5031_50310901_43_dialog_content = "自分の得点だって高くないくせに！",
  ui_story_5031_50310901_44_dialog_content = "まだスタート地点に集合していない選手は、\n成績発表が終わる前にお集まりください。",
  ui_story_5031_50310901_45_dialog_content = "前ラウンドのトップは――レインボー選手。",
  ui_story_5031_50310901_46_dialog_content = "フン、さすがは我らサーカス団の屋台骨。\n特に驚くこともないですね。",
  ui_story_5031_50310901_47_dialog_content = "レインボーちゃーん！！",
  ui_story_5031_50310901_48_dialog_content = "しかし、次の選手には驚かれるかもしれません。",
  ui_story_5031_50310901_49_dialog_content = "レインボーと同点で1位になったのは――\nシエル選手です。",
  ui_story_5031_50310901_50_dialog_content = "おお！あのメカっ娘だよな？",
  ui_story_5031_50310901_51_dialog_content = "そんなにすごいのか！\nレインボーちゃんの点数に追いつくなんて！",
  ui_story_5031_50310901_52_dialog_content = "お～！シエルちゃん、すごい！",
  ui_story_5031_50310901_53_dialog_content = "ありがとうございます、先輩。",
  ui_story_5031_50310901_54_dialog_content = "ガルー先輩？どうしてここに？",
  ui_story_5031_50310901_55_dialog_content = "スタート地点に行かないんですか？",
  ui_story_5031_50310901_56_dialog_content = "フッフッフ…それはね…",
  ui_story_5031_50310901_57_dialog_content = "あなたたち、PlayerNameとメルト、\nそれからあたしを競わせようとしてるでしょ～？",
  ui_story_5031_50310901_58_dialog_content = "そうすれば、あなたたち2人の試合でライバルが1人減る。\n違う？",
  ui_story_5031_50310901_59_dialog_content = "…",
  ui_story_5031_50310901_60_dialog_content = "ええと、それは…",
  ui_story_5031_50310901_61_dialog_content = "でしょ？\n思い通りにさせるわけにいかないよ～！",
  ui_story_5031_50310901_62_dialog_content = "ふぅ、緊張することじゃない…",
  ui_story_5031_50310901_63_dialog_content = "このラウンド、明らかに人が少ない…\n落ち着いてやるだけでいいんだ。",
  ui_story_5031_50310901_64_dialog_content = "PlayerNameさん、あの…",
  ui_story_5031_50310901_65_dialog_content = "どうしたの？",
  ui_story_5031_50310901_66_dialog_content = "うっ…あの、リーシュコード、\n体に結ばれていませんよ…",
  ui_story_5031_50310901_67_dialog_content = "危ないです…",
  ui_story_5031_50310901_68_dialog_content = "あっ！忘れてた。",
  ui_story_5031_50310901_69_dialog_content = "ありがとう、メルト！\n助かったよ。",
  ui_story_5031_50310901_70_dialog_content = "…あっ！",
  ui_story_5031_50310901_71_dialog_content = "…海の中に潜って見えなくなっちゃった。",
  ui_story_5031_50310901_72_dialog_content = "何か悪いことでも言っちゃったかな…？",
  ui_story_5031_50310901_73_dialog_content = "そろそろ時間ですね。",
  ui_story_5031_50310901_74_dialog_content = "では、第2ラウンドを始めます。",
  ui_story_5031_50310901_75_dialog_content = "ハハハハ…また適当なスタートだな…",
  ui_story_5031_50310901_76_dialog_content = "これが団長のスタイルなのかな？",
  ui_story_5031_50310901_77_dialog_content = "おっ、このラウンドはメカがないのか。\n前のラウンドよりは地味になりそうだな。",
  ui_story_5031_50310901_78_dialog_content = "ん？見てみろ！あのサーカス団三姉妹の娘…",
  ui_story_5031_50310901_79_dialog_content = "動きがレインボーちゃんよりあざやかだ！",
  ui_story_5031_50310901_80_dialog_content = "当然ですね。メルトは手足のバランスと使い方では\n最も優れている団員の1人ですから。",
  ui_story_5031_50310901_81_dialog_content = "空中ブランコや吊り輪を完璧にこなせるのです。\nサーフィン程度、簡単でしょう。",
  ui_story_5031_50310901_82_dialog_content = "団員ひとりひとりのことを\nよく理解しているんだな。",
  ui_story_5031_50310901_83_dialog_content = "そうですね。団員はただショーに出るだけの\nパフォーマーではありません。",
  ui_story_5031_50310901_84_dialog_content = "サーカス団という大家族の一員なのです。",
  ui_story_5031_50310901_85_dialog_content = "…",
  ui_story_5031_50310901_86_dialog_content = "その言葉、昔のお前を思い出すな。",
  ui_story_5031_50310901_87_dialog_content = "そうですか？家族や「エルビス兄さん」に\n頼ってばかりいた役立たずを？",
  ui_story_5031_50310901_88_dialog_content = "いや。巣から落ちた小鳥のために泣く、\n心優しい子どもを、だ。",
  ui_story_5031_50310901_89_dialog_content = "小鳥を巣に戻すために木に登ろうとして、\n腕を折って半年はギブスをしていたな。",
  ui_story_5031_50310901_90_dialog_content = "お前はあの頃のままだ。皆のことを気にかけている。\nいや、気にかけないことができない。",
  ui_story_5031_50310901_91_dialog_content = "忘れたいことを思い出させないで欲しいですね。",
  ui_story_5031_50310901_92_dialog_content = "試合に集中しましょう。",
  ui_story_5031_50310901_93_dialog_content = "フフ…分かったよ。",
  ui_story_5031_50310902_1_dialog_content = "第2ラウンドのトップも、\nやはり我がサーカス団の団員――",
  ui_story_5031_50310902_2_dialog_content = "メルト選手です。",
  ui_story_5031_50310902_3_dialog_content = "うおおおお！",
  ui_story_5031_50310902_4_dialog_content = "彼女が毎晩、夜も昼も汗を流し続けてきた成果です。",
  ui_story_5031_50310902_5_dialog_content = "彼女の姿が皆さんのような、\n腐りきった怠惰な魂に刺激を与えたことを願っていますよ。",
  ui_story_5031_50310902_X5_dialog_content = "…",
  ui_story_5031_50310902_X6_dialog_content = "言葉を失いましたか？まあ、いいでしょう。\n誰もが人生で何かを追求しているわけではありませんからね。",
  ui_story_5031_50310902_X7_dialog_content = "それでは、第3ラウンドの出場者の皆さん、\nスタート地点で準備をしてください。",
  ui_story_5031_50310902_X8_dialog_content = "第3ラウンドの選手は準備をお願いします。",
  ui_story_5031_50310902_6_dialog_content = "第3ラウンドの出場者は、\nスタート地点に集合してください。",
  ui_story_5031_50310902_7_dialog_content = "えぇ～？ウソでしょ！？\nPlayerName、0点だったの！？",
  ui_story_5031_50310902_8_dialog_content = "ある意味、普通の人にはできないコトだよ！！",
  ui_story_5031_50310902_9_dialog_content = "バイスお姉ちゃんとカレンお姉ちゃんがいなかったら、\n「海雲クジラ」がどうなってたか…",
  ui_story_5031_50310902_10_dialog_content = "ううっ…それ以上言わないで…",
  ui_story_5031_50310902_11_dialog_content = "空の末裔に生まれてきて、\nごめんなさい…",
  ui_story_5031_50310902_12_dialog_content = "フィア、あまりPlayerNameを責めないであげて。",
  ui_story_5031_50310902_13_dialog_content = "初心者が1日でサーフィンをマスターするなんて、\nそもそもムリな話だったのよ。",
  ui_story_5031_50310902_14_dialog_content = "私たちで巻き返す。\n心配しなくていいわ。",
  ui_story_5031_50310902_15_dialog_content = "バイスお姉ちゃんとカレンお姉ちゃん、\n本当に頼りになるね！",
  ui_story_5031_50310902_16_dialog_content = "はぁ～…PlayerNameももっとがんばりなよ。",
  ui_story_5031_50310902_17_dialog_content = "もうバカにしないから、元気出してよ～。\nフィアがサーフィンをマスターしたら、一緒に教えてあげるから！",
  ui_story_5031_50310902_18_dialog_content = "アハハ…ありがとう…",
  ui_story_5031_50310902_19_dialog_content = "ふふん！お礼はもっと遠慮なく言っていいよ！",
  ui_story_5031_50310902_20_dialog_content = "あ、あの、PlayerNameさん…",
  ui_story_5031_50310902_21_dialog_content = "あっ、メルト。どうしたの？",
  ui_story_5031_50310902_22_dialog_content = "うぅ…",
  ui_story_5031_50310902_23_dialog_content = "サプリが話すよ。",
  ui_story_5031_50310902_24_dialog_content = "メル姉、PlayerNameに謝りたいんだって。\nさっき、危うくケガさせそうになったから！",
  ui_story_5031_50310902_25_dialog_content = "ああ、そのことは…大丈夫だよ！\n僕はケガなんかしてないから。",
  ui_story_5031_50310902_26_dialog_content = "驚いたせいで海水を飲んで、\n勝手にむせただけだよ。",
  ui_story_5031_50310902_27_dialog_content = "うう…はい…",
  ui_story_5031_50310902_28_dialog_content = "PlayerNameって優しいんだね～。\n団長とは大違いだよ。",
  ui_story_5031_50310902_29_dialog_content = "それならモヤシでも門前払いにはしないであげてもいいかな～。\nどうりでメル姉が空の末裔のこと…むぐっ！",
  ui_story_5031_50310902_30_dialog_content = "ファ、ファム！",
  ui_story_5031_50310902_31_dialog_content = "スタート地点に行く時間でしょ。\nは、早く行かないと！",
  ui_story_5031_50310902_32_dialog_content = "うぐぐ！",
  ui_story_5031_50310902_33_dialog_content = "あっ、サプリを置いて行かないで！",
  ui_story_5031_50310902_34_dialog_content = "ふ～ん？",
  ui_story_5031_50310902_35_dialog_content = "PlayerName、本当にモテるのね？",
  ui_story_5031_50310902_36_dialog_content = "…",
  ui_story_5031_50310902_37_dialog_content = "えっ？何の話？",
  ui_story_5031_50310902_38_dialog_content = "別に～？",
  ui_story_5031_50310902_39_dialog_content = "私も早く準備しないと。\nもうすぐ始まっちゃう！",
  ui_story_5031_50310902_40_dialog_content = "ええ、行きましょう。",
  ui_story_5031_50310902_41_dialog_content = "…何なんだろう、皆コソコソして…",
  ui_story_5031_50310902_42_dialog_content = "僕たちも海の方へ行こう。フィ…",
  ui_story_5031_50310902_43_dialog_content = "あれ？フィア？",
  ui_story_5031_50310902_44_dialog_content = "…まったく…みんなして、どういうこと…？",
  ui_story_5031_50310902_45_dialog_content = "第3ラウンド。ルールはすでに知っての通りです。\n始めましょう。",
  ui_story_5031_50310902_46_dialog_content = "速射感知！",
  ui_story_5031_50310902_47_dialog_content = "おぉ～、いきなり激しい攻撃だね。",
  ui_story_5031_50310902_48_dialog_content = "ファムも本気を出さないといけないみたい。\nこっそり特訓を積んできたんだから…バカにしないで！",
  ui_story_5031_50310902_49_dialog_content = "ゲホッ…ゴホゴホッ！",
  ui_story_5031_50310902_50_dialog_content = "エルビス、薬は！？",
  ui_story_5031_50310902_51_dialog_content = "私の…上着の内ポケットだ。",
  ui_story_5031_50310902_52_dialog_content = "忘れるな、マイクを…ゲホゲホ！",
  ui_story_5031_50310902_53_dialog_content = "ええ、切ってあります。",
  ui_story_5031_50310902_54_dialog_content = "本当に上着のポケットなのですか？\n何もありませんよ。",
  ui_story_5031_50310902_55_dialog_content = "うっ…ゴホ、ゴホッ！",
  ui_story_5031_50310902_56_dialog_content = "すまない。ハンカチは…あるか？",
  ui_story_5031_50310902_57_dialog_content = "ええ、待ってください。",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>チャリン、ドサッ――</color>",
  ui_story_5031_50310902_59_dialog_content = "まったく…ゴチャゴチャしすぎですね…",
  ui_story_5031_50310902_60_dialog_content = "こんな時に出てきて面倒を起こすなど…\nもう少しお行儀よくできないのですか？",
  ui_story_5031_50310902_61_dialog_content = "…",
  ui_story_5031_50310902_62_dialog_content = "どうぞ。",
  ui_story_5031_50310902_63_dialog_content = "すまん…ゴホッ、ゴホッ。",
  ui_story_5031_50310902_64_dialog_content = "うおぉ！このラウンドもすごいぞ。\n強い選手ばっかりだ！",
  ui_story_5031_50310902_65_dialog_content = "おお！また暗鬼をやっつけた！",
  ui_story_5031_50310902_66_dialog_content = "あの弓矢使いの女の子、すごいな！",
  ui_story_5031_50310902_67_dialog_content = "…",
  ui_story_5031_50310902_68_dialog_content = "すまないが、人の少ない場所へ\n連れて行ってもらえないか？休みたい。",
  ui_story_5031_50310902_69_dialog_content = "ええ。少し待っていてください…",
  ui_story_5031_50310902_70_dialog_content = "そこのピエロ、こちらへ！",
  ui_story_5031_50310902_71_dialog_content = "そう、あなたです。",
  ui_story_5031_50310902_72_dialog_content = "団長、どうしました？",
  ui_story_5031_50310902_73_dialog_content = "しばらく得点の集計を任せます。\n僕たちは打ち合わせがあるので。",
  ui_story_5031_50310902_74_dialog_content = "了解しました。",
  ui_story_5031_50310902_75_dialog_content = "そんな顔をするな。\n私は大丈夫だ…",
  ui_story_5031_50310902_76_dialog_content = "大丈夫？僕にしがみついて、\n血まで吐いていたのに？",
  ui_story_5031_50310902_77_dialog_content = "すまん…服を汚してしまったな。",
  ui_story_5031_50310902_78_dialog_content = "そんなことを心配しているのではありませんよ。",
  ui_story_5031_50310902_79_dialog_content = "問題ない。私の血の気が多すぎただけだ。\nむしろ健康すぎることの証拠だろう？",
  ui_story_5031_50310902_80_dialog_content = "…バカを言わないでください。",
  ui_story_5031_50310902_81_dialog_content = "解決策とやらは、\n本当に教えてもらえないのですか？",
  ui_story_5031_50310902_82_dialog_content = "僕を信じてもらえるのなら、\n必ず力になりますよ。",
  ui_story_5031_50310902_83_dialog_content = "…",
  ui_story_5031_50310902_84_dialog_content = "どうしてそんな顔をするのです？",
  ui_story_5031_50310902_85_dialog_content = "何でもない。お前の言葉を聞いて、\nまた少し、子どもの頃を思い出しただけだ。",
  ui_story_5031_50310902_86_dialog_content = "また忘れていたいことを\n思い出させるつもりですか？",
  ui_story_5031_50310902_87_dialog_content = "そうだな…お前は私より背が低いし、線も細かったが、\nいつも誰かを助けていたし、私も助けられた。",
  ui_story_5031_50310902_88_dialog_content = "今のお前の目は、あの頃と同じだ。\nまったく変わっていない。",
  ui_story_5031_50310902_89_dialog_content = "歳月は顔や体に痕を残すかもしれませんが、\n魂を変えることはできません。",
  ui_story_5031_50310902_90_dialog_content = "そうだな。変わらないものもたくさんある。",
  ui_story_5031_50310902_91_dialog_content = "たとえば、お前が相変わらず私より背が低いとかな。",
  ui_story_5031_50310902_92_dialog_content = "やれやれ…ですが、今のその体では、\nあなたが10人いても僕に勝てませんよ。",
  ui_story_5031_50310902_93_dialog_content = "そうだな。今のお前は\nもう私に守られていたジェノではない…",
  ui_story_5031_50310902_94_dialog_content = "それに今の私では、\nお前を守ることもできないだろう。",
  ui_story_5031_50310902_95_dialog_content = "…では、今度は僕があなたを守りましょう。",
  ui_story_5031_50310902_96_dialog_content = "フフ…軽々しく言っていいことではないぞ。",
  ui_story_5031_50310902_97_dialog_content = "僕は本気ですよ、エルビス。",
  ui_story_5031_50310902_98_dialog_content = "あなたの言っていた解決法が何なのか…\n教えてもらえれば、できる限りのことをすると約束しましょう。",
  ui_story_5031_50310902_99_dialog_content = "ならば、仮にそのことが、\nお前の背後にいる組織に関わっているとしたら？",
  ui_story_5031_50310902_100_dialog_content = "…？",
  ui_story_5031_50310902_101_dialog_content = "仮に――あくまでも仮にだ。お前の船を…\nお前の船の最深部にある物が必要だとしたら？",
  ui_story_5031_50310902_102_dialog_content = "それでも私に手を貸してくれるか？",
  ui_story_5031_50310902_103_dialog_content = "…どうして知っているのです？",
  ui_story_5031_50310902_104_dialog_content = "そんなことはどうでもいいんだ、ジェノ。",
  ui_story_5031_50310902_105_dialog_content = "大事なのは、私たちがもう子どもではないということだ。\nもう単純で、のんびりした楽しい頃には戻れないのだ。",
  ui_story_5031_50310902_106_dialog_content = "今はあらゆる決断、あらゆる約束、あらゆる言葉が、\nあまりにも大きな重みを持っている…",
  ui_story_5031_50310902_107_dialog_content = "だから…改めて聞く。\n私に手を貸してくれるのか…？",
  ui_story_5031_50310902_108_dialog_content = "…",
  ui_story_5031_50310902_109_dialog_content = "ぼ…僕は、誓いました。",
  ui_story_5031_50310902_110_dialog_content = "この船を守り、あれを守ると…",
  ui_story_5031_50310902_111_dialog_content = "…そうか。困らせてすまなかった。",
  ui_story_5031_50310902_112_dialog_content = "行こう。そろそろ司会に戻らなくてはな――\nあのピエロ君の手には負えなくなっているようだ。",
  ui_story_5031_50310902_113_dialog_content = "エルビス、僕は…",
  ui_story_5031_50310902_114_dialog_content = "ジェノ。",
  ui_story_5031_50310902_115_dialog_content = "…",
  ui_story_5031_50310902_116_dialog_content = "分かっている。\nそれ以上言うな。",
  ui_story_5031_50310902_117_dialog_content = "だが、とにかく知っておいて\nもらいたかったのだ…",
  ui_story_5031_50310902_118_dialog_content = "この十数年、\nずっとお前を忘れたことなどなかった。",
  ui_story_5031_50310902_119_dialog_content = "…！",
  ui_story_5031_50311001_1_dialog_content = "カレン殿下。",
  ui_story_5031_50311001_2_dialog_content = "まだ何か用？",
  ui_story_5031_50311001_3_dialog_content = "いつまでこんな茶番に\n参加し続けるおつもりですか？",
  ui_story_5031_50311001_4_dialog_content = "大勢の庶民と同じ海に入るなど…\n実に…気分が悪いではありませんか。",
  ui_story_5031_50311001_5_dialog_content = "そう？私は気にならないわ。",
  ui_story_5031_50311001_6_dialog_content = "気がのらないなら、砂浜か船の上で観戦していなさい。\nそのまま白夜城に帰っても構わないわ。",
  ui_story_5031_50311001_7_dialog_content = "フン、全く手を焼かせる…",
  ui_story_5031_50311001_8_dialog_content = "マシュー。",
  ui_story_5031_50311001_9_dialog_content = "…チッ。面倒な。どうして私が\nこんなわがままな姫君など守らなくてはならんのだ！",
  ui_story_5031_50311001_10_dialog_content = "…",
  ui_story_5031_50311001_11_dialog_content = "マシュー。私はわがままな姫君ではないし、\nあなたに守ってもらう必要もないわ。",
  ui_story_5031_50311001_12_dialog_content = "あなたが泳げないからと心配しているの？\n心配ないわ、私は泳げるから。",
  ui_story_5031_50311001_13_dialog_content = "プッ…",
  ui_story_5031_50311001_14_dialog_content = "な、なんですと！？",
  ui_story_5031_50311001_15_dialog_content = "誰が泳げないなどと言いましたか！？たかが泳ぐ程度！\n庶民すらできることが、私にできないはずなど…！",
  ui_story_5031_50311001_16_dialog_content = "あとローウェイ！何をクスクス笑っている！？\n全部聞こえているぞ！",
  ui_story_5031_50311001_17_dialog_content = "マシュー、確かに泳げない。",
  ui_story_5031_50311001_18_dialog_content = "…あああ！お前ってヤツは！",
  ui_story_5031_50311001_19_dialog_content = "もういい、たくさんだ！意地の悪い殿下！\nいずれ庶民に紛れていたことを後悔しますぞ！",
  ui_story_5031_50311001_20_dialog_content = "帰るぞ！シャワーを浴びる！",
  ui_story_5031_50311001_21_dialog_content = "…",
  ui_story_5031_50311001_22_dialog_content = "…あの人たち、何しに来たの？",
  ui_story_5031_50311001_23_dialog_content = "あの人、自分が泳げないものだから、\n私がこの試合に出るのを止めたかったようね。",
  ui_story_5031_50311001_24_dialog_content = "あのイルンティ裁判長が一体何を考えて\nあんなやからを私のところに送って来たのかしら…？",
  ui_story_5031_50311001_25_dialog_content = "バイスお姉ちゃん！おかえり！",
  ui_story_5031_50311001_26_dialog_content = "バイス、おかえり。",
  ui_story_5031_50311001_27_dialog_content = "さっきのバイスお姉ちゃん、すごかった！\nきっと高得点だよ！",
  ui_story_5031_50311001_28_dialog_content = "これで「海雲クジラ」はあたしたちのもの！\n師匠のお説教を聞かずにすみそう！",
  ui_story_5031_50311001_29_dialog_content = "フィアちゃん、あまり期待しすぎないで…",
  ui_story_5031_50311001_30_dialog_content = "ライバルも手ごわい相手ばっかりなのよ…",
  ui_story_5031_50311001_31_dialog_content = "ガルー先輩、あんなにサーフィンができるなんて知らなかった…\n完全に油断してたわ！",
  ui_story_5031_50311001_32_dialog_content = "大丈夫だよ。まだ次のラウンドがあるから。\nあっちの成績はこれ以上伸びないし。",
  ui_story_5031_50311001_33_dialog_content = "ええ。じゃあ、次はカレンの出番ね！",
  ui_story_5031_50311001_34_dialog_content = "ところで、さっきの人たち…マシューとローウェイだったかしら？\n何しに来たの？試合に出るの？",
  ui_story_5031_50311001_35_dialog_content = "気にしなくていいわ。",
  ui_story_5031_50311001_36_dialog_content = "…そう言えば、しばらく前から\n司会の声が聞こえてこないわね。",
  ui_story_5031_50311001_37_dialog_content = "あっ、そういえば…\n領主様たち、何してるのかしら？",
  ui_story_5031_50311001_38_dialog_content = "とにかく、カレンは準備して！",
  ui_story_5031_50311001_39_dialog_content = "がんばってね、カレン！",
  ui_story_5031_50311001_40_dialog_content = "カレンお姉ちゃん、がんばって！",
  ui_story_5031_50311001_41_dialog_content = "ええ、任せて。",
  ui_story_5031_50311001_42_dialog_content = "…",
  ui_story_5031_50311001_43_dialog_content = "ジェノ団長？",
  ui_story_5031_50311001_44_dialog_content = "何です？",
  ui_story_5031_50311001_45_dialog_content = "<size=33>ひえっ、怖っ…！\nなんで急に不機嫌になったんだ…？</size>",
  ui_story_5031_50311001_46_dialog_content = "あ、あの、団長…前のラウンドの成績が出ました。\n発表しますか？",
  ui_story_5031_50311001_47_dialog_content = "…",
  ui_story_5031_50311001_48_dialog_content = "ええと、団長…\nそれとも次のラウンドの開始を宣言しますか？",
  ui_story_5031_50311001_49_dialog_content = "選手たちはもう位置についているようですし…",
  ui_story_5031_50311001_50_dialog_content = "…スタート。",
  ui_story_5031_50311001_51_dialog_content = "…",
  ui_story_5031_50311001_52_dialog_content = "なんかこのスタイルにも慣れてきたな…",
  ui_story_5031_50311001_53_dialog_content = "アイスブロッサム！",
  ui_story_5031_50311001_54_dialog_content = "わぁ、早い！",
  ui_story_5031_50311001_55_dialog_content = "目の前の波を凍らせるなんて！",
  ui_story_5031_50311001_56_dialog_content = "完璧な動きで、\nあっという間に距離を離して…",
  ui_story_5031_50311001_57_dialog_content = "すごいすごい！\nサプリも見てて興奮してきた！",
  ui_story_5031_50311001_58_dialog_content = "はっ！",
  ui_story_5031_50311001_59_dialog_content = "グア！！",
  ui_story_5031_50311001_60_dialog_content = "えっ？こんなに多くの暗鬼を一度に？",
  ui_story_5031_50311001_61_dialog_content = "うおぉぉ！",
  ui_story_5031_50311001_62_dialog_content = "あれ、ランカを助けた子じゃないか？",
  ui_story_5031_50311001_63_dialog_content = "いくら何でも強すぎるだろう…\nサーフィンの技も見事だし、暗鬼の群れをほぼ秒殺してる！",
  ui_story_5031_50311001_64_dialog_content = "それだけじゃないよ。海面をうまく凍らせて、\n自分だけのコーナーを作ってる！",
  ui_story_5031_50311001_65_dialog_content = "わぁ～…あのお姉さん、\nカレンって名前だっけ？",
  ui_story_5031_50311001_66_dialog_content = "そうそう、思いだした。\n確かお姫様なんだよね！",
  ui_story_5031_50311001_67_dialog_content = "すごい、すごい！",
  ui_story_5031_50311001_68_dialog_content = "熱くなってきた！\nサプリもがんばらないと！",
  ui_story_5031_50311001_69_dialog_content = "ふぅ…",
  ui_story_5031_50311001_70_dialog_content = "これで62匹！",
  ui_story_5031_50311001_71_dialog_content = "ガルーは70、シエルは…93。",
  ui_story_5031_50311001_72_dialog_content = "…こういうことに関しては\nやはり機械の方が有利のようね。",
  ui_story_5031_50311001_73_dialog_content = "バイスが69匹だから…",
  ui_story_5031_50311001_74_dialog_content = "32匹の差ね。\n技術点は分からないけれど…",
  ui_story_5031_50311001_75_dialog_content = "サーカス団の方は…",
  ui_story_5031_50311001_76_dialog_content = "ハロ～！お姫さま、のんびり休憩中？",
  ui_story_5031_50311001_77_dialog_content = "サプリ？",
  ui_story_5031_50311001_78_dialog_content = "お姫さま、サプリの名前、覚えててくれたんだ！\nうれしい！",
  ui_story_5031_50311001_79_dialog_content = "カレンでいいわ。",
  ui_story_5031_50311001_80_dialog_content = "うん、カレン姐様～！",
  ui_story_5031_50311001_81_dialog_content = "サプリ、カレン姐様のこと、\n大好きだけど、悪い知らせがあるの。",
  ui_story_5031_50311001_82_dialog_content = "何かしら？",
  ui_story_5031_50311001_83_dialog_content = "私たちの作戦はね～…レインボー姐とメル姉が\n先陣を切って、ポイントを取るの。",
  ui_story_5031_50311001_84_dialog_content = "ファムとサプリの役目は…",
  ui_story_5031_50311001_85_dialog_content = "残りの選手の邪魔をすること！",
  ui_story_5031_50311001_86_dialog_content = "うっ！",
  ui_story_5031_50311001_87_dialog_content = "それでバイスがファムに\nしつこく妨害されていたということね！",
  ui_story_5031_50311001_88_dialog_content = "そういうこと！カレン姐様、\nサプリのこと、嫌いにならないで！どうしようもないの。",
  ui_story_5031_50311001_89_dialog_content = "なんと、無礼者め！\nおそれ多くもカレン殿下に手を出すとは！！",
  ui_story_5031_50311001_90_dialog_content = "ローウェイ、カレン殿下を助けろ！\nあの庶民のガキを海に落としてやれ！！",
  ui_story_5031_50311001_91_dialog_content = "…",
  ui_story_5031_50311001_92_dialog_content = "素早い身のこなし…\nさすがはサーカス団ね。",
  ui_story_5031_50311001_93_dialog_content = "こんな小さなサーフボードの上では、\n向こうに分がある…",
  ui_story_5031_50311001_94_dialog_content = "わぁ、さすがはカレン姐様！",
  ui_story_5031_50311001_95_dialog_content = "サプリの攻撃を防ぎながら\nバランスがとれるなんて！",
  ui_story_5031_50311001_96_dialog_content = "とってもエレガントだわ！\nやっぱりサプリ、カレン姐様のこと、大好き！",
  ui_story_5031_50311001_97_dialog_content = "…本気でケガをさせるわけにもいかない…",
  ui_story_5031_50311001_98_dialog_content = "とにかく、まずは距離を取るしか…",
  ui_story_5031_50311001_99_dialog_content = "あれ？カレン姐様、どこに行くの？",
  ui_story_5031_50311001_100_dialog_content = "もうサプリと遊んでくれないの？\nまだ遊び足りないよ！",
  ui_story_5031_50311001_101_dialog_content = "…そこっ！",
  ui_story_5031_50311001_102_dialog_content = "アイス――ブロッサム！",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>パキン――</color>",
  ui_story_5031_50311001_104_dialog_content = "あっ！",
  ui_story_5031_50311001_105_dialog_content = "ごめんなさい。\nしばらくそこで大人しくしていて。",
  ui_story_5031_50311001_106_dialog_content = "うっ…あれ？",
  ui_story_5031_50311001_107_dialog_content = "び、びっくりした…\n死ぬかと思ったよ。",
  ui_story_5031_50311001_108_dialog_content = "氷で動けなくしただけだったんだね！",
  ui_story_5031_50311001_109_dialog_content = "うん、手足が完璧に動かないのに、\nサプリは傷ついてないし、顔だけは出しておいてくれた…",
  ui_story_5031_50311001_110_dialog_content = "すごい制御力！\nカレン姐様のこと、ますます好きになりそう！",
  ui_story_5031_50311001_111_dialog_content = "…変わり者ね…",
  ui_story_5031_50311001_112_dialog_content = "でも、これで脅威は消えた。\nあとは点数を稼ぐことだけに集中すれば…",
  ui_story_5031_50311001_113_dialog_content = "かなり時間をムダにしてしまったわ。\n皆の期待に応えるためにも、急がないと。",
  ui_story_5031_50311002_1_dialog_content = "みんな、集合～！",
  ui_story_5031_50311002_2_dialog_content = "サーフィンバトル、どうだったかな？",
  ui_story_5031_50311002_3_dialog_content = "サイコー！",
  ui_story_5031_50311002_4_dialog_content = "エヘヘ、レインボーも思いっきり楽しめたよ！",
  ui_story_5031_50311002_5_dialog_content = "出場選手のみんなもお疲れ様！\n誰にとっても、忘れられない思い出になったね！",
  ui_story_5031_50311002_6_dialog_content = "それでは、成績発表の時間で～す！",
  ui_story_5031_50311002_7_dialog_content = "ゴクリ――",
  ui_story_5031_50311002_8_dialog_content = "フィア、またそれ？",
  ui_story_5031_50311002_9_dialog_content = "フィ、フィア、緊張なんかしてないし！",
  ui_story_5031_50311002_10_dialog_content = "心配しないで。カレンがあんなに活躍してくれたんだもの。\nきっと大丈夫よ！",
  ui_story_5031_50311002_11_dialog_content = "いえ、私はガルーとシエルの\n暗鬼の撃破数に追いついただけ…",
  ui_story_5031_50311002_12_dialog_content = "技術点も含めたら、\n結果を見ないと分からないわ。",
  ui_story_5031_50311002_13_dialog_content = "それにレインボーたちとも、\nかなりの開きがあるはず。",
  ui_story_5031_50311002_14_dialog_content = "さあ、これ以上は引き延ばさないよ～？",
  ui_story_5031_50311002_15_dialog_content = "それでは発表します！\nサーフィンバトル、第1位は――",
  ui_story_5031_50311002_16_dialog_content = "ジャ、ジャーン！\nなんとあたしたち、「エメラルドチーム」！",
  ui_story_5031_50311002_17_dialog_content = "得点のうちわけは後で掲示板に貼りだすから、\n異議がある人は確認してね！",
  ui_story_5031_50311002_18_dialog_content = "会場にいたお客さんの審査で評価されてるから、\nひいきは一切ないよ！",
  ui_story_5031_50311002_19_dialog_content = "うおおぉ！",
  ui_story_5031_50311002_20_dialog_content = "レインボーちゃん、さすがだ！",
  ui_story_5031_50311002_21_dialog_content = "みんな、あたしたち「エメラルドチーム」を\n応援してくれてありがとう！",
  ui_story_5031_50311002_22_dialog_content = "そして領主様、500万白夜コイン\nありがと～！！",
  ui_story_5031_50311002_23_dialog_content = "ワハハハハ！",
  ui_story_5031_50311002_24_dialog_content = "あぁ、残念だわ…",
  ui_story_5031_50311002_25_dialog_content = "白夜コイン…500万白夜コイン…",
  ui_story_5031_50311002_26_dialog_content = "ううっ、フィアの水着が！",
  ui_story_5031_50311002_27_dialog_content = "大丈夫、レインボーたちはカーニバル自体に出場してるわけじゃない。\n「海雲クジラ」については、まだ希望があるよ。",
  ui_story_5031_50311002_28_dialog_content = "水着は…まぁ、賞金がなくても\n僕らで買ってあげられるから…",
  ui_story_5031_50311002_29_dialog_content = "ホント！？PlayerName、\n水着を買ってくれるの！？",
  ui_story_5031_50311002_30_dialog_content = "そうだね…君がいい子にして、\nもう人を怒らせたり、トラブルを起こさなければね。",
  ui_story_5031_50311002_31_dialog_content = "ええ～？あたしの表面にとらわれすぎだよ～。\nフィアはこれでもレディなんだよ？",
  ui_story_5031_50311002_32_dialog_content = "できないなら、それはそれで別にいいよ？",
  ui_story_5031_50311002_33_dialog_content = "ちょっと！一度言った以上は\nちゃんと守ってよね！",
  ui_story_5031_50311002_34_dialog_content = "…",
  ui_story_5031_50311002_35_dialog_content = "続いて2位のチームを発表するよ！",
  ui_story_5031_50311002_36_dialog_content = "シーッ！2位の発表だ！",
  ui_story_5031_50311002_37_dialog_content = "第2位は――",
  ui_story_5031_50311002_38_dialog_content = "啓光連邦からのお客さん！\nガルーとシエルチーム！",
  ui_story_5031_50311002_39_dialog_content = "おおっ！",
  ui_story_5031_50311002_40_dialog_content = "えっ！？",
  ui_story_5031_50311002_41_dialog_content = "<size=45>えぇ！？</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>えーっ！！！</size>",
  ui_story_5031_50311002_43_dialog_content = "ま、まさかガルー先輩とシエルが？",
  ui_story_5031_50311002_44_dialog_content = "そ、それじゃあ、賞品を手に入れるのは…",
  ui_story_5031_50311002_45_dialog_content = "あたしたちじゃないってこと？",
  ui_story_5031_50311002_46_dialog_content = "そ、それじゃあ「海雲クジラ」が\n誰かに連れていかれちゃう！",
  ui_story_5031_50311002_47_dialog_content = "師匠にズタボロに怒られちゃう！",
  ui_story_5031_50311002_48_dialog_content = "…",
  ui_story_5031_50311002_49_dialog_content = "あっ、カレン？\nどこに行くの？",
  ui_story_5031_50311002_50_dialog_content = "カレン！",
  ui_story_5031_50311002_51_dialog_content = "カレン、待って。\nどこに行くの？",
  ui_story_5031_50311002_52_dialog_content = "カレン…？",
  ui_story_5031_50311002_53_dialog_content = "PlayerName、バイス、ごめんなさい。\n少し一人にさせて。",
  ui_story_5031_50311002_54_dialog_content = "そ、それは構わないけど…",
  ui_story_5031_50311002_55_dialog_content = "でも、カレンのことが心配なんだ。\nもしよければ…",
  ui_story_5031_50311002_56_dialog_content = "せめて何があったのか、\n話してくれないかな？",
  ui_story_5031_50311002_56X1_dialog_content = "そうよ。私たち、\n何か悪いことでも言っちゃったかしら？",
  ui_story_5031_50311002_56X2_dialog_content = "いえ、違うの。\nあなたたちとは関係ないわ。",
  ui_story_5031_50311002_57_dialog_content = "…ただ、自分が情けないと思っただけよ。",
  ui_story_5031_50311002_58_dialog_content = "全力を尽くしたのに、友人を勝たせてあげられなかった。\n望むものを手に入れさせてあげられなかった。",
  ui_story_5031_50311002_59_dialog_content = "でも、それはカレンのせいじゃないでしょ？",
  ui_story_5031_50311002_60_dialog_content = "それを言うなら、\n一番謝らなきゃいけないのは僕だよ…",
  ui_story_5031_50311002_61_dialog_content = "皆があんなにがんばってくれたのに、\n結局サーフィンは習得できなくて、台無しにしちゃったんだから。",
  ui_story_5031_50311002_62_dialog_content = "それとは違うわ…",
  ui_story_5031_50311002_63_dialog_content = "違わない、同じことだよ！",
  ui_story_5031_50311002_64_dialog_content = "カレンが僕たちのためにがんばってくれたのは嬉しいけど、\n僕のミスは僕のミスだ。自分を責めないで。",
  ui_story_5031_50311002_65_dialog_content = "そもそも、こういうチーム戦で、\n誰かを責めたりするべきじゃないよ。",
  ui_story_5031_50311002_66_dialog_content = "僕の方こそカレンに謝らないといけないし、\n感謝もしてるんだ。",
  ui_story_5031_50311002_67_dialog_content = "カレンがいなかったら、\n僕たちはそもそもここまで来られなかっただろうしね。",
  ui_story_5031_50311002_68_dialog_content = "…",
  ui_story_5031_50311002_69_dialog_content = "それと同じで、バイスがいなかったら、\n僕たちはここまでやれたと思う？",
  ui_story_5031_50311002_70_dialog_content = "…できなかったでしょうね。",
  ui_story_5031_50311002_71_dialog_content = "そうでしょ？\n僕たちにとって、カレンも同じだよ。",
  ui_story_5031_50311002_72_dialog_content = "そもそも1位を目指してたのは…その、ナントカクジラのためなんだ。\nまた別の方法を考えればいいよ。",
  ui_story_5031_50311002_73_dialog_content = "1位を逃したからって、\n世界が滅びるわけでもないんだし。",
  ui_story_5031_50311002_74_dialog_content = "そうよ、カレン。いざとなったら、団長さんに聞いてもいいし…\nガルー先輩やレインボーでもいいわ。",
  ui_story_5031_50311002_75_dialog_content = "ちゃんと海雲クジラのことを説明すれば、\nきっと協力してくれるはずよ。",
  ui_story_5031_50311002_75X1_dialog_content = "バイスの言うとおりだよ。\n大した問題でもないし、解決策はいくらでもあるはずだ。",
  ui_story_5031_50311002_76_dialog_content = "だからカレン、\nもう悲しまないで？",
  ui_story_5031_50311002_77_dialog_content = "次の方法を考えよう。",
  ui_story_5031_50311002_78_dialog_content = "…",
  ui_story_5031_50311002_79_dialog_content = "分かったわ。",
  ui_story_5031_50311002_80_dialog_content = "あなたたちの言う通りね。\nありがとう。",
  ui_story_5031_50311002_81_dialog_content = "確かに私は、あなたたちをもっと見習うべきなのかも。\nそれが父上の狙いだとしたら…",
  ui_story_5031_50311002_82_dialog_content = "ソルラドさん？\nどうしてお父さんが出てくるの？",
  ui_story_5031_50311002_83_dialog_content = "この旅行の前に、白夜城で父上と…\n少し、話をしたの。",
  ui_story_5031_50311002_83X1_dialog_content = "「話した」？",
  ui_story_5031_50311002_83X2_dialog_content = "あなたたちと一緒に旅をしている意味を\n考えるようにと言われたわ。",
  ui_story_5031_50311002_83X3_dialog_content = "それが分かってきた気がするの。\nあなたたちには、私が学ぶべきところがたくさんある。",
  ui_story_5031_50311002_83X4_dialog_content = "それで一日中、自分の世界に閉じこもって\n考え事しているような感じだったのね。",
  ui_story_5031_50311002_83X5_dialog_content = "けれど、いくら考えても、\nまだいろいろなことがぼんやりしたまま。",
  ui_story_5031_50311002_83X6_dialog_content = "バイスと話した、新しい力のこともそう。\n今日、実はずっと試していたのよ。",
  ui_story_5031_50311002_83X7_dialog_content = "え？あの話？",
  ui_story_5031_50311002_83X8_dialog_content = "そうよ。あなたの言った通り、\n意識を「落として」みた。",
  ui_story_5031_50311002_83X9_dialog_content = "けれど、思い出すのは父上と話した時のことばかり。\nまったく集中できなかったの。",
  ui_story_5031_50311002_83X10_dialog_content = "結局、何も起こらなかったわ。",
  ui_story_5031_50311002_83X11_dialog_content = "そうだったの…でも、珍しいことじゃないわ。",
  ui_story_5031_50311002_83X12_dialog_content = "感情や雑念にとらわれずに、\n精神を限界まで集中させるなんて、そもそも難しいことだし。",
  ui_story_5031_50311002_83X13_dialog_content = "私の時は…心の中に一筋の光が見えて、\nそれ以外の雑念が全部吹き飛んだの。",
  ui_story_5031_50311002_83X14_dialog_content = "「一筋の光」…この間もそう言っていたわね。\n具体的には何なのかしら？",
  ui_story_5031_50311002_83X15_dialog_content = "あの時は…思い出したの。\nあなたと、それからPlayerNameと、一緒に経験したいろんなこと。",
  ui_story_5031_50311002_83X16_dialog_content = "そうしたら、知らず知らずのうちに、\n心が落ち着いていたの。",
  ui_story_5031_50311002_83X17_dialog_content = "でも、私もうまく言えないわ…\n具体的に説明するのは難しいわね。",
  ui_story_5031_50311002_83X18_dialog_content = "そうだったのね。\nそれなら、私は…",
  ui_story_5031_50311002_84_dialog_content = "PlayerName！カレンお姉ちゃん！\nバイスお姉ちゃん！",
  ui_story_5031_50311002_85_dialog_content = "どうしてフィアを置いてきぼりにして、こんなところにいるの？\nすっごく探したんだから！",
  ui_story_5031_50311002_85X1_dialog_content = "あ、ごめん、急いでたから、\nうっかり一人にしちゃったわ！",
  ui_story_5031_50311002_86_dialog_content = "フィア、そんなにあわててどうしたの？",
  ui_story_5031_50311002_87_dialog_content = "だから、皆を探しに来たの！",
  ui_story_5031_50311002_88_dialog_content = "聞いて！団長が言ってたの――",
  ui_story_5031_50311002_89_dialog_content = "サーフィンバトルの順位は\n次の種目の出場順を決めるのに使うだけで、まだ次があるの！",
  ui_story_5031_50311002_90_dialog_content = "一日団員として、サーカスに出られるんだって！",
  ui_story_5031_50311002_91_dialog_content = "だから、まだチャンスがあるってこと！",
  ui_story_5031_50311101_1_dialog_content = "で、今の状況だけど――",
  ui_story_5031_50311101_2_dialog_content = "ぐすっ…<size=45>うわあぁん！！！</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>あたしたちの…大事な目的が…</size>",
  ui_story_5031_50311101_4_dialog_content = "海雲クジラが…このままじゃ見つけられないよ。\n<size=45>うわあああん！</size>",
  ui_story_5031_50311101_5_dialog_content = "（…はぁ…もうすぐ一番大事な\n決戦の舞台なのに…）",
  ui_story_5031_50311101_6_dialog_content = "（珍獣たちとフィアの仲がこじれて、\nどうしても言うことを聞こうとしない…）",
  ui_story_5031_50311101_7_dialog_content = "（このままじゃ勝てない…\nとにかく、最後までがんばるように、フィアを説得しないと。）",
  ui_story_5031_50311101_8_option_content = "フィア、まだ落ち込むには早いよ！",
  ui_story_5031_50311101_9_dialog_content = "ぐすっ…じゃあ、何かいい方法があるの？",
  ui_story_5031_50311101_10_dialog_content = "正直、僕も何も思いつかないよ。\nでも、練習の時間は、あと1時間しかないんだ。",
  ui_story_5031_50311101_11_dialog_content = "それが過ぎたら、\n船上の観客たちがショーを観にくる。",
  ui_story_5031_50311101_12_dialog_content = "そしたらおしまいじゃない！？\nうわあぁん！！",
  ui_story_5031_50311101_13_dialog_content = "待って、とにかく泣かないで！",
  ui_story_5031_50311101_14_dialog_content = "ほら、僕たち2人でアストラ大陸中を回って、\n珍獣保護のためにずいぶん苦労したことを思いだして！",
  ui_story_5031_50311101_15_dialog_content = "僕たちですごいことを成し遂げたんだ！\nこの程度のことで、簡単に負けるわけにはいかないでしょ？",
  ui_story_5031_50311101_16_dialog_content = "フィアがあと少しがんばって、ビッカーと仲良くできれば、\nきっとショーは成功するよ！",
  ui_story_5031_50311101_17_dialog_content = "ハイ？",
  ui_story_5031_50311101_18_dialog_content = "フィア…もう、やる気が出ない…",
  ui_story_5031_50311101_19_dialog_content = "そもそも優勝賞品が本当に海雲クジラかどうかも知らないのに、\nこんなところまで来ちゃったし…",
  ui_story_5031_50311101_20_dialog_content = "（今さらそこに気づいたの…？）",
  ui_story_5031_50311101_21_dialog_content = "その顔は何！？\n心の中で悪口言ってる！？",
  ui_story_5031_50311101_22_dialog_content = "いやいや、まさか！",
  ui_story_5031_50311101_23_dialog_content = "じゃあ、こうしよう。僕たち2人でトイレに行くふりでもして、\n海雲クジラがいるかどうか、こっそり確かめに行かない？",
  ui_story_5031_50311101_24_dialog_content = "賞品が本当に海雲クジラだったら、\nフィアもビッカーとリハーサルを続ける気になるでしょ？",
  ui_story_5031_50311101_25_dialog_content = "そ、そんなことして大丈夫なの？",
  ui_story_5031_50311101_26_dialog_content = "あのジェノって人、怖そうだよ。\n怒らせたら大変なんじゃ…",
  ui_story_5031_50311101_27_dialog_content = "こっそり見るだけだったら、\nきっと大丈夫だよ。",
  ui_story_5031_50311101_28_dialog_content = "僕も感知能力を使って手伝うから、\n誰にも見つからないよ。",
  ui_story_5031_50311101_29_dialog_content = "う…うん！そうだね！",
  ui_story_5031_50311101_30_dialog_content = "じゃあ、お願い！あたしの珍獣、\n「超超希少種」空の末裔PlayerName！",
  ui_story_5031_50311101_31_dialog_content = "僕は珍獣じゃないって何度も言ってるでしょ！！",
  ui_story_5031_50311101_32_dialog_content = "はぁ…まあいいや。\n時間もないし、急いで行って、戻ってこよう。",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>船の深部</color>",
  ui_story_5031_50311101_34_dialog_content = "あの怖い団長が入れてくれなかった場所、ここだね。",
  ui_story_5031_50311101_35_dialog_content = "広いなぁ。どの廊下も同じに見えるし、\n分かれ道がたくさんある…",
  ui_story_5031_50311101_36_dialog_content = "海雲クジラ、一体どこに隠れてるの？",
  ui_story_5031_50311101_37_dialog_content = "待って、フィア…",
  ui_story_5031_50311101_38_dialog_content = "ここに隠れよう。前から誰か来る。",
  ui_story_5031_50311101_39_dialog_content = "ふぁ～…これで3周目だぜ？",
  ui_story_5031_50311101_40_dialog_content = "団長、本当に何考えてるんだろうな。\nアリすら入るスキのない場所を巡回だなんて…",
  ui_story_5031_50311101_41_dialog_content = "なんで見回りの警備なんてしてるの？\nやっぱり、団長には人に言えない秘密が…",
  ui_story_5031_50311101_42_dialog_content = "PlayerNameが手伝ってくれてなかったら、\nとっくに見つかって、つまみ出されてたよ。",
  ui_story_5031_50311101_43_dialog_content = "これもPlayerNameのお手柄だよ！\n海雲クジラを見つけたら、ごほうびをあげる。",
  ui_story_5031_50311101_44_dialog_content = "動物クッキーとかどう？\nキャロは大好きなんだけど、PlayerNameも好き？",
  ui_story_5031_50311101_45_dialog_content = "今はそんなことを考えるより、\n優勝賞品が何かを突き止める方が先だよ。",
  ui_story_5031_50311101_46_dialog_content = "うん…",
  ui_story_5031_50311101_47_dialog_content = "…止まって。前に2人いるのを感知した…\nでも、立ち止まって、動いてないみたいだ。",
  ui_story_5031_50311101_48_dialog_content = "じゃあ、こっそり通り過ぎれば\nきっと見つからないよ。",
  ui_story_5031_50311101_49_dialog_content = "待って！",
  ui_story_5031_50311101_50_dialog_content = "今度は何？",
  ui_story_5031_50311101_51_dialog_content = "この2人の感じ…知ってる人みたいだ。",
  ui_story_5031_50311101_52_dialog_content = "…エルビスとパト！？",
  ui_story_5031_50311101_53_dialog_content = "領主様と衛兵のおじさん？\nどうしてこんなところに？",
  ui_story_5031_50311101_54_dialog_content = "僕が知るわけないでしょ！\nとにかく、今は放っておこう。目標が優先だ。",
  ui_story_5031_50311101_55_dialog_content = "音を出さないで…\n絶対に気づかれないようにして。",
  ui_story_5031_50311101_56_dialog_content = "申し訳ございません。寝室や疑わしい場所を探したのですが…\n鍵らしきものは見つかりませんでした。",
  ui_story_5031_50311101_57_dialog_content = "構わん。もう場所は分かった。",
  ui_story_5031_50311101_58_dialog_content = "鍵はずっと身につけているようだ。\n何をする時も、肌身離さずな。",
  ui_story_5031_50311101_59_dialog_content = "それはやっかいな…",
  ui_story_5031_50311101_60_dialog_content = "問題ない。計画通りに事を進めろ。\n今夜は何としても成功させねばならない。",
  ui_story_5031_50311101_61_dialog_content = "計画？PlayerName、あの2人、\n計画が何とかって…むぐぐ――！",
  ui_story_5031_50311101_62_option_content = "シーッ！",
  ui_story_5031_50311101_63_dialog_content = "…聞こえたか？",
  ui_story_5031_50311101_64_dialog_content = "何者だ？出てこい！",
  ui_story_5031_50311101_65_dialog_content = "（まずい、逃げないと！）",
  ui_story_5031_50311101_66_dialog_content = "ふぅ…はぁ…一気に甲板まで来たけど…",
  ui_story_5031_50311101_67_dialog_content = "ぷはぁ――！PlayerName、何するの！？\n窒息しちゃうところだったでしょ！",
  ui_story_5031_50311101_68_dialog_content = "ごめん、ごめん。あわててたから…",
  ui_story_5031_50311101_69_dialog_content = "こっちの方です！",
  ui_story_5031_50311101_70_dialog_content = "ゴホッ、ゴホッ…追え！",
  ui_story_5031_50311101_71_dialog_content = "まずい。まだ追いかけてきてる。\n急いで隠れる場所を探さなきゃ…",
  ui_story_5031_50311101_72_dialog_content = "あれ――PlayerName、チビッコちゃん！",
  ui_story_5031_50311101_73_dialog_content = "フィアはチビじゃないよ！",
  ui_story_5031_50311101_74_dialog_content = "リハーサルは終わったの？",
  ui_story_5031_50311101_75_dialog_content = "えっ？ま、まだだよ。\nごめん、用があるから先に…",
  ui_story_5031_50311101_76_dialog_content = "フフン、あたしは必殺技を用意してあるよ！",
  ui_story_5031_50311101_77_dialog_content = "王座があれば、優勝は間違いなくあたし！",
  ui_story_5031_50311101_78_dialog_content = "今から見せてあげてもいいよ～？",
  ui_story_5031_50311101_79_dialog_content = "（まずい…ガルーにからまれた。\n近くに隠れられる場所は…）",
  ui_story_5031_50311101_80_dialog_content = "PlayerName、まだ追いかけてきてるよ！",
  ui_story_5031_50311101_81_dialog_content = "早く無敵の感知能力で何とかして！",
  ui_story_5031_50311101_82_dialog_content = "そういう能力じゃないよ！",
  ui_story_5031_50311101_83_dialog_content = "無敵の…",
  ui_story_5031_50311101_84_dialog_content = "王座…",
  ui_story_5031_50311101_85_dialog_content = "<size=45>ブルーオーシャンッ！！！</size>",
  ui_story_5031_50311101_86_dialog_content = "まぶしい！！",
  ui_story_5031_50311101_87_dialog_content = "何の光だ！？",
  ui_story_5031_50311101_88_dialog_content = "どう？すごいでしょ！",
  ui_story_5031_50311101_89_dialog_content = "あたしが最近王座に追加したライトアップ機能！",
  ui_story_5031_50311101_90_dialog_content = "これさえあれば、真っ暗な夜の海を\n思いっきり飛ばせるの！",
  ui_story_5031_50311101_91_dialog_content = "えっ、す、すごい…かな？",
  ui_story_5031_50311101_92_dialog_content = "す、すごい！",
  ui_story_5031_50311101_93_dialog_content = "人がいっぱい集まって来たよ！",
  ui_story_5031_50311101_94_dialog_content = "今のすごい！もう一度やってみせて！",
  ui_story_5031_50311101_95_dialog_content = "もう一回？へへへ、いいよ！",
  ui_story_5031_50311101_96_dialog_content = "チッ…人が多すぎます。\n取り逃がしたようです…",
  ui_story_5031_50311101_97_dialog_content = "構わん。盗み聞きされただけなら、\n計画に何も影響はない。",
  ui_story_5031_50311101_98_dialog_content = "行くぞ。すべては計画通りに。",
  ui_story_5031_50311101_99_dialog_content = "はっ。",
  ui_story_5031_50311101_100_dialog_content = "行ったみたい…気づかれなかったね。",
  ui_story_5031_50311101_101_dialog_content = "よかった…ガルー、本当に助かったよ！",
  ui_story_5031_50311101_102_dialog_content = "え？何のこと？\nあたし、何かした？",
  ui_story_5031_50311101_103_dialog_content = "全部終わったら、改めてお礼するよ…",
  ui_story_5031_50311101_104_dialog_content = "だけど、今はやらなきゃいけないことがあるから！\nまたね！！",
  ui_story_5031_50311101_105_dialog_content = "ええ～？なんでそんなに急いでるの？",
  ui_story_5031_50311101_106_dialog_content = "ま、緊張はほぐれたみたいだね。",
  ui_story_5031_50311101_107_dialog_content = "フフフ…あたしのショーの素晴らしさってもんよ！",
  ui_story_5031_50311101_108_dialog_content = "こんなにがんばったけど、結局、賞品が何なのか分からなかったし…\n時間もだいぶムダにしちゃった…",
  ui_story_5031_50311101_109_dialog_content = "仕方ないよ。船の中はすごく広いし、\n見張りもあんなにいるんじゃ…",
  ui_story_5031_50311101_110_dialog_content = "短い間に僕たち2人だけで、\n中を全部調べるなんて不可能だよ。",
  ui_story_5031_50311101_111_dialog_content = "おとなしく技を磨いて、\n競技で1位になるしかなさそうだね！",
  ui_story_5031_50311101_112_dialog_content = "でも…もう時間が…",
  ui_story_5031_50311101_113_dialog_content = "海雲クジラ…うぅ…\nかわいそうな海雲クジラ、もしかしたらもう…",
  ui_story_5031_50311101_114_dialog_content = "もう、なんでまた泣くの？",
  ui_story_5031_50311101_115_dialog_content = "PlayerName、フィア？まだ練習してるの？",
  ui_story_5031_50311101_116_dialog_content = "フィアに何か言って、\n泣かせたのではないでしょうね？",
  ui_story_5031_50311101_117_option_content = "そんなことないよ！",
  ui_story_5031_50311101_118_option_content = "僕のせいじゃないよ！",
  ui_story_5031_50311101_119_dialog_content = "ビッカーがリハーサルに協力してくれないんだ。\nそれでフィアが困ってるんだよ。",
  ui_story_5031_50311101_120_dialog_content = "ハイハ～イ。",
  ui_story_5031_50311101_121_dialog_content = "うう…まったく、\nほめてるんじゃないの！",
  ui_story_5031_50311101_122_dialog_content = "ハイ？",
  ui_story_5031_50311101_123_dialog_content = "不思議ね。この前のビッカーとフィアは、\nあんなに仲良しだったのに。",
  ui_story_5031_50311101_124_dialog_content = "どうして言うことを聞かなくなったの？",
  ui_story_5031_50311101_125_dialog_content = "まさか、コミュニケーションがうまくいかなかった？",
  ui_story_5031_50311101_126_dialog_content = "フィアはちゃんとビッカーと話してるのに、\n言うことを聞いてくれないの！",
  ui_story_5031_50311101_127_dialog_content = "何て言ったの？",
  ui_story_5031_50311101_128_dialog_content = "優勝したいから、協力してって…",
  ui_story_5031_50311101_129_dialog_content = "それで、ビッカーは何か言った？",
  ui_story_5031_50311101_130_dialog_content = "何も…",
  ui_story_5031_50311101_131_dialog_content = "それはつまり、\n同意していないということでしょう？",
  ui_story_5031_50311101_132_dialog_content = "でも、臨時のパートナーになるってはっきり認めてくれたんだよ。\nなんでいう事を聞いてくれないの…？",
  ui_story_5031_50311101_133_dialog_content = "うわあああ～ん！！！",
  ui_story_5031_50311101_134_dialog_content = "はぁ…泣いても仕方ないわ。\nこの問題、解決できるかは、あなた次第よ。",
  ui_story_5031_50311101_135_dialog_content = "あたし次第…？",
  ui_story_5031_50311101_136_dialog_content = "ビッカーはあなたのパートナーになった。\nでも、えらそうに命令をして、聞いてくれるとは限らないのよ。",
  ui_story_5031_50311101_137_dialog_content = "結局のところ、あなたとビッカーで\n十分に意思疎通できていないのが問題なのでしょうね。",
  ui_story_5031_50311101_138_dialog_content = "うぅ…じゃあ、フィアはどうすればいいの？",
  ui_story_5031_50311101_139_dialog_content = "まずはきちんと、謝ってみたら？",
  ui_story_5031_50311101_140_dialog_content = "謝るだけではないわ。大事なことは謝った後、\n真剣に助力をお願いして、同意を得ることよ。",
  ui_story_5031_50311101_141_dialog_content = "ビッカー、手伝ってくれるかな…？",
  ui_story_5031_50311101_142_dialog_content = "この子、野生のよりも凶暴そう…",
  ui_story_5031_50311101_143_dialog_content = "それはあなたの誠意次第ね。",
  ui_story_5031_50311101_144_dialog_content = "フィアならきっと大丈夫よ。",
  ui_story_5031_50311101_145_dialog_content = "そうだよ、あきらめないで。\nがんばって！",
  ui_story_5031_50311101_146_dialog_content = "わ、分かった。\nやってみる！",
  ui_story_5031_50311101_147_dialog_content = "ビッカー、ご…",
  ui_story_5031_50311101_148_dialog_content = "ごめんなさい…",
  ui_story_5031_50311101_149_dialog_content = "ハイハイ？",
  ui_story_5031_50311101_150_dialog_content = "（ビッカーが前足を耳元に近づけてる…\nまさか、声が小さいって言いたいの？）",
  ui_story_5031_50311101_151_dialog_content = "ご…",
  ui_story_5031_50311101_152_dialog_content = "<size=45>ごめんなさい！！！</size>",
  ui_story_5031_50311101_153_dialog_content = "あたしが悪かったの！\nムリヤリ手伝わせちゃいけなかったよね。",
  ui_story_5031_50311101_154_dialog_content = "あたしが悪かった。次は…\nううん、もう次はないよ！",
  ui_story_5031_50311101_155_dialog_content = "これからは、ちゃんとあんたの言ってることを聞くから。\nうぅ…",
  ui_story_5031_50311101_156_dialog_content = "ハイ？",
  ui_story_5031_50311101_157_dialog_content = "これから…えっ、これから…\n美味しいものを買ってこいって？",
  ui_story_5031_50311101_158_dialog_content = "ハ～イ、ハイハイ？",
  ui_story_5031_50311101_159_dialog_content = "えっ！？ペンおじさんの農園っていう\n有名ブランドのブドウが食べたい？",
  ui_story_5031_50311101_160_dialog_content = "他のビッカーから聞いたって！？",
  ui_story_5031_50311101_161_dialog_content = "でも、あれは高いの…",
  ui_story_5031_50311101_162_dialog_content = "ハイハイ？",
  ui_story_5031_50311101_163_dialog_content = "ううん、も、文句じゃないの！",
  ui_story_5031_50311101_164_dialog_content = "あたしを許してくれるなら、買ってあげるから！\nうぅ…",
  ui_story_5031_50311101_165_dialog_content = "（フィアが困ってる…）",
  ui_story_5031_50311101_166_dialog_content = "（この機会に、他人との付き合い方を学んでもらおう）",
  ui_story_5031_50311101_167_dialog_content = "ハ～イ。",
  ui_story_5031_50311101_168_dialog_content = "（ビッカーはうれしそうだ。\n謝罪は受け入れてもらえたのかな？）",
  ui_story_5031_50311101_169_dialog_content = "許してくれるの？\nよ、よかった！",
  ui_story_5031_50311101_170_dialog_content = "じゃあ、この後のショーは…",
  ui_story_5031_50311101_171_dialog_content = "ハイハ～イ。",
  ui_story_5031_50311101_172_dialog_content = "えっ？",
  ui_story_5031_50311101_173_dialog_content = "何て言ったの？",
  ui_story_5031_50311101_174_dialog_content = "「フィアの態度次第」だって。",
  ui_story_5031_50311101_175_dialog_content = "そんな持ってまわった言い方を…！？",
  ui_story_5031_50311101_176_dialog_content = "本当に大丈夫？\nもう一度お願いしてみたら？",
  ui_story_5031_50311101_177_dialog_content = "決戦にかかわる一大事なんだし…",
  ui_story_5031_50311101_178_dialog_content = "うぅ、あたし…",
  ui_story_5031_50311101_179_dialog_content = "まもなく最後の種目が始まります。\n出場者の皆さん、時間です。",
  ui_story_5031_50311101_180_dialog_content = "え、もう！？",
  ui_story_5031_50311101_181_dialog_content = "もう1時間が…仕方ない…",
  ui_story_5031_50311101_182_dialog_content = "覚悟を決めて、行こう！",
  ui_story_5031_50311101_183_dialog_content = "任せて！",
  ui_story_5031_50311101_184_dialog_content = "私たちでできる限り点を稼ぐわ。",
  ui_story_5031_50311101_185_dialog_content = "フィアとビッカーもがんばるよ！",
  ui_story_5031_50311101_186_dialog_content = "ハイハイ！",
  ui_story_5031_50311201_1_dialog_content = "夜の訪れとともに、\n今、3つ目の勝負が始まるよ！",
  ui_story_5031_50311201_2_dialog_content = "うおー！！",
  ui_story_5031_50311201_3_dialog_content = "ここまでの試合で成績の良かったチーム2組が\nステージで1対1の大決戦！",
  ui_story_5031_50311201_4_dialog_content = "片方は――\n現在成績トップ、啓光チーム！",
  ui_story_5031_50311201_5_dialog_content = "そして、新人猛獣使い、\nフィアちゃん率いるフィアチーム！",
  ui_story_5031_50311201_6_dialog_content = "うおおおお！！！",
  ui_story_5031_50311201_7_dialog_content = "かなり盛り上がってるね！\nすっごくいい感じ！",
  ui_story_5031_50311201_8_dialog_content = "それでは、勝負の前に…\nジェノ団長と三姉妹による前座ショーをお楽しみください！",
  ui_story_5031_50311201_9_dialog_content = "ジェノ団長の登場でーす！",
  ui_story_5031_50311201_10_dialog_content = "「予言の力」…\n古今、無数の光霊たちが追い求めてきた能力です。",
  ui_story_5031_50311201_11_dialog_content = "超常的存在と意思を交わし、\nあるいは過去、あるいは未来から届いた言葉を読み取って…",
  ui_story_5031_50311201_12_dialog_content = "歴史の真相やこれから起こることを知る。",
  ui_story_5031_50311201_13_dialog_content = "今夜、その古き力をここでお見せし、\n皆様の疑問にお答えしましょう…",
  ui_story_5031_50311201_14_dialog_content = "僕が使用するのは、この「始原のカード」です。",
  ui_story_5031_50311201_15_dialog_content = "おお…出たぞ！ウワサの「予言の儀式」だ！",
  ui_story_5031_50311201_16_dialog_content = "暗鬼を呼び出したり、予言ができたり…\n「始原」の力って、一体どういう力なんだろう…",
  ui_story_5031_50311201_17_dialog_content = "それでは、幸運な1名のお客様にステージに上がっていただき、\nショーのお手伝いをしていただきましょう。",
  ui_story_5031_50311201_18_dialog_content = "幸運の糸が結ばれるのは、どのお客様でしょうか…？",
  ui_story_5031_50311201_19_dialog_content = "俺だ！！！",
  ui_story_5031_50311201_20_dialog_content = "僕にやらせて！",
  ui_story_5031_50311201_21_dialog_content = "ああ、僕には分かります…",
  ui_story_5031_50311201_22_dialog_content = "「始原のカード」が私の運命をあなたへと導く――",
  ui_story_5031_50311201_23_dialog_content = "1列目、一番右にお座りの女性の方。",
  ui_story_5031_50311201_24_dialog_content = "わ、私ですか？",
  ui_story_5031_50311201_25_dialog_content = "そうです、どうかステージへ。",
  ui_story_5031_50311201_26_dialog_content = "どのようなことでもお尋ねくださって結構ですよ。\n僕が「始原のカード」で超常的存在に問い、答えをお教えします。",
  ui_story_5031_50311201_27_dialog_content = "どんなことでも…？",
  ui_story_5031_50311201_28_dialog_content = "そうです。",
  ui_story_5031_50311201_29_dialog_content = "だったら…私がどこから来たか、分かりますか？",
  ui_story_5031_50311201_30_dialog_content = "「始原のカード」よ、我が目となりて真実を現したまえ…\nこの女性の故郷はいずこなりや？",
  ui_story_5031_50311201_31_dialog_content = "（カードがジェノの手の中を飛び回ってる。\n1枚取り出した…！）",
  ui_story_5031_50311201_32_dialog_content = "「始原のカード」の答えは…\nペドロ要塞からいらっしゃったようですね。",
  ui_story_5031_50311201_33_dialog_content = "どうして分かったんですか！？",
  ui_story_5031_50311201_34_dialog_content = "「始原のカード」から聞いたことです。\n他にもいろいろと教えてくれていますよ――",
  ui_story_5031_50311201_35_dialog_content = "あなたは子爵家のお生まれで、\n幸せな家庭を築いていらっしゃる。",
  ui_story_5031_50311201_36_dialog_content = "お2人はとても仲がよろしいようですが…\n一緒に座っていらっしゃらないようですね？",
  ui_story_5031_50311201_37_dialog_content = "すごい…そんなことまで分かるなんて…",
  ui_story_5031_50311201_38_dialog_content = "チケットが人気で、隣同士の席を取れなかったんです。\nだから、離れて座るしかなくて…",
  ui_story_5031_50311201_39_dialog_content = "しかも、あなたに前列のいい席を譲ってくれた…",
  ui_story_5031_50311201_40_dialog_content = "そ、そうです…",
  ui_story_5031_50311201_41_dialog_content = "「始原のカード」が、お2人の未来が順調であるよう祈っています。\nさあ、席にお戻りください。",
  ui_story_5031_50311201_42_dialog_content = "おお！！！すごい！！！",
  ui_story_5031_50311201_43_dialog_content = "もう1人！もう1人やってくれ！",
  ui_story_5031_50311201_44_dialog_content = "時間とはとうときもの。「始原のカード」といえども、\n時の法則には従わなければなりません。",
  ui_story_5031_50311201_45_dialog_content = "皆様、どうぞ次のショーをご覧ください。\nまた皆様と運命のつながる日がくることを、楽しみにしております…",
  ui_story_5031_50311201_46_dialog_content = "ジェノ団長の見事なショーでした！",
  ui_story_5031_50311201_47_dialog_content = "続いて、メルト、サプリ、ファム3姉妹の\n手に汗握る、空中ブランコショー！",
  ui_story_5031_50311201_48_dialog_content = "そ、それじゃあ…出番よ！",
  ui_story_5031_50311201_49_dialog_content = "アゴが外れるほど、驚かせてあげる！",
  ui_story_5031_50311201_50_dialog_content = "うん――",
  ui_story_5031_50311201_51_dialog_content = "行くわ！",
  ui_story_5031_50311201_52_dialog_content = "（メルトがハシゴを昇って…ほかの2人は手を伸ばした！）",
  ui_story_5031_50311201_53_dialog_content = "それっ！",
  ui_story_5031_50311201_54_dialog_content = "ファム、しっかり受け止めてよ！",
  ui_story_5031_50311201_55_dialog_content = "サプ姉ちゃん、重い…",
  ui_story_5031_50311201_56_dialog_content = "（ヒヤっとした！ファムがサプリをつかめてよかった…）",
  ui_story_5031_50311201_57_dialog_content = "つ、つぎは私が！",
  ui_story_5031_50311201_58_dialog_content = "（えっ！？まさか――）",
  ui_story_5031_50311201_59_dialog_content = "はいっ！",
  ui_story_5031_50311201_60_dialog_content = "つかんだよ！",
  ui_story_5031_50311201_61_dialog_content = "もっと…重い！",
  ui_story_5031_50311201_62_dialog_content = "やったわ！",
  ui_story_5031_50311201_63_option_content = "すごい！！！",
  ui_story_5031_50311201_64_dialog_content = "うおおお！！！すごいな！！！",
  ui_story_5031_50311201_65_dialog_content = "あ、ありがとう！",
  ui_story_5031_50311201_66_dialog_content = "私たちの華麗な姿、目に焼き付けた～？",
  ui_story_5031_50311201_67_dialog_content = "焼き付けたよ！！！",
  ui_story_5031_50311201_68_dialog_content = "簡単なショーだったけど…",
  ui_story_5031_50311201_69_dialog_content = "みんなの歓声、受け取ったわ！",
  ui_story_5031_50311201_70_dialog_content = "じゃ、続きを楽しんでね！",
  ui_story_5031_50311201_71_dialog_content = "三姉妹の素晴らしいショーに拍手～！",
  ui_story_5031_50311201_72_dialog_content = "それじゃあ、いよいよ…決戦の時！",
  ui_story_5031_50311201_73_dialog_content = "現在トップの啓光チームの2人組は、\nそれぞれ必殺技を披露するって聞いたけど…？",
  ui_story_5031_50311201_74_dialog_content = "ガルー先輩の意見を参考にして、\nパワードスーツを改造したのは、この時のため…",
  ui_story_5031_50311201_75_dialog_content = "ぜったいに成功させる、お願い！",
  ui_story_5031_50311201_76_dialog_content = "シエル、何かすごいものを用意してるみたいだ！",
  ui_story_5031_50311201_77_dialog_content = "…",
  ui_story_5031_50311201_78_dialog_content = "あれ？フィア、大丈夫？\nどうして震えてるの？",
  ui_story_5031_50311201_79_dialog_content = "き…",
  ui_story_5031_50311201_80_dialog_content = "緊張してる？",
  ui_story_5031_50311201_81_dialog_content = "そ、そんなことないもん！",
  ui_story_5031_50311201_82_dialog_content = "フィアは珍獣マスターなんだよ！\n緊張なんて――うぐっ！",
  ui_story_5031_50311201_83_dialog_content = "舌を噛むほど、緊張してるんだね…",
  ui_story_5031_50311201_84_dialog_content = "し、してない！",
  ui_story_5031_50311201_85_dialog_content = "フィア、まずは何も考えず、深呼吸をしてみて。",
  ui_story_5031_50311201_86_dialog_content = "ふぅ――",
  ui_story_5031_50311201_87_dialog_content = "すぅ――",
  ui_story_5031_50311201_88_dialog_content = "どう？少しは良くなった？",
  ui_story_5031_50311201_89_dialog_content = "うう…やっぱりダメ…\n心臓が今にも飛び出しそうだよ…",
  ui_story_5031_50311201_90_dialog_content = "あの2人、何かすごそうだし…\nあたしなんて、ビッカーとちゃんと約束もできてないし…",
  ui_story_5031_50311201_91_dialog_content = "どう考えても、勝てるわけないよ！",
  ui_story_5031_50311201_92_dialog_content = "とにかく、まずは落ち着こう！\nここまで来たら、後悔したって何もならないでしょ。",
  ui_story_5031_50311201_93_dialog_content = "元気を出して。\n出来るだけがんばればいいだけだから。",
  ui_story_5031_50311201_94_dialog_content = "でも、万が一ビッカーが\n言うこと聞いてくれなかったら、どうするの？",
  ui_story_5031_50311201_95_dialog_content = "そうだなぁ…",
  ui_story_5031_50311201_96_option_content = "こんな話、聞いたことない？",
  ui_story_5031_50311201_97_dialog_content = "なにを？",
  ui_story_5031_50311201_98_dialog_content = "「ほめれば伸びる」。",
  ui_story_5031_50311201_99_dialog_content = "えっ？！",
  ui_story_5031_50311201_100_dialog_content = "とにかく、その言葉通りだよ。\nビッカーのご機嫌を取って、協力してくれるようお願いするんだ。",
  ui_story_5031_50311201_101_dialog_content = "優勝できれば、賞品が海雲クジラであろうとなかろうと、\nどうにでもなる！",
  ui_story_5031_50311201_102_dialog_content = "じゃ、じゃあ、なんとかがんばってみる！",
  ui_story_5031_50311201_103_dialog_content = "うん、応援してるよ！\n僕もバイスもカレンもがんばるから！",
  ui_story_5031_50311201_104_dialog_content = "最終得点は、全員分の合計点を人数で割った平均だから…",
  ui_story_5031_50311201_105_dialog_content = "1人1人がんばれば、その分優勝確率が上がるんだ！",
  ui_story_5031_50311201_106_dialog_content = "わ、わかった…",
  ui_story_5031_50311201_107_dialog_content = "さあさあ、見て見て！\nガルー選手とシエル選手の見事なパフォーマンス！",
  ui_story_5031_50311201_108_dialog_content = "パワードスーツと「王座」がまぶしい光の中、\n混ざりあうように踊る…",
  ui_story_5031_50311201_109_dialog_content = "鋼鉄で出来たパワードスーツの、重みを感じさせない華やかな動き！\nまるで戦いながら踊ってるみたい！技術力もそうとうなもの！",
  ui_story_5031_50311201_110_dialog_content = "重量感と華麗さ、完璧な融合です！",
  ui_story_5031_50311201_111_dialog_content = "それでは、続いてフィアチームの登場！",
  ui_story_5031_50311201_112_dialog_content = "いったいどんなショーを見せてくれるのか！？",
  ui_story_5031_50311201_113_dialog_content = "ふぅ…行こう、ビッカー！",
  ui_story_5031_50311201_114_dialog_content = "ハイ！",
  ui_story_5031_50311201_115_dialog_content = "（フィアもビッカーも、がんばれ！）",
  ui_story_5031_50311201_116_dialog_content = "（お願い！うまくいって…）",
  ui_story_5031_50311201_117_dialog_content = "はい、じゃあ始めるよ。\nビッカー、ここに来て。",
  ui_story_5031_50311201_118_dialog_content = "ハイ！",
  ui_story_5031_50311201_119_dialog_content = "あたしの言った通り、ジャンプと同時に宙返りするの。",
  ui_story_5031_50311201_120_dialog_content = "ハイハイ？",
  ui_story_5031_50311201_121_dialog_content = "（ビッカー、フィアを見ながら、\n怪しげな笑いを浮かべてる…！？）",
  ui_story_5031_50311201_122_dialog_content = "お、お願い…言うこと聞いて！",
  ui_story_5031_50311201_123_dialog_content = "ハイ？",
  ui_story_5031_50311201_124_dialog_content = "（ビッカー、とぼけてる！？）",
  ui_story_5031_50311201_125_dialog_content = "おい、どうなってんだ！？",
  ui_story_5031_50311201_126_dialog_content = "時間をムダにするために、\nチケットを買ったんじゃないぞ！",
  ui_story_5031_50311201_127_dialog_content = "ううぅ…",
  ui_story_5031_50311201_128_dialog_content = "お、お願い！",
  ui_story_5031_50311201_129_dialog_content = "ハイ～？",
  ui_story_5031_50311201_129X1_dialog_content = "ビッカー、どこの誰よりもすごいでしょ！\nこんなこと、簡単にできちゃうでしょ！",
  ui_story_5031_50311201_130_dialog_content = "終わったらペンおじさんのブドウ、\n買ってあげるから！",
  ui_story_5031_50311201_131_dialog_content = "ハイハイ！",
  ui_story_5031_50311201_132_dialog_content = "うまくいった！？",
  ui_story_5031_50311201_133_dialog_content = "ハ～イ。",
  ui_story_5031_50311201_134_dialog_content = "おお！もう1回見せてくれ！",
  ui_story_5031_50311201_135_dialog_content = "次は、ボールを投げるよ！\nしっかり受け止めてね！",
  ui_story_5031_50311201_136_dialog_content = "ハイ！ハイ！",
  ui_story_5031_50311201_137_dialog_content = "ハ～イ。",
  ui_story_5031_50311201_138_dialog_content = "すごい！",
  ui_story_5031_50311201_139_dialog_content = "（よかった！ブドウにつられて、\nあたしに協力してくれてる…！）",
  ui_story_5031_50311201_140_dialog_content = "ハイ？",
  ui_story_5031_50311201_141_dialog_content = "え、待って！それは食べ物じゃないよ！",
  ui_story_5031_50311201_142_dialog_content = "ワハハハ！",
  ui_story_5031_50311201_143_dialog_content = "（あぶなかったぁ…お客さんは\nショーの一部だって思ってくれたみたい）",
  ui_story_5031_50311201_144_dialog_content = "ビッカー、最後に必殺技を見せてあげて！！",
  ui_story_5031_50311201_145_dialog_content = "必殺技？そんなの、あったっけ？",
  ui_story_5031_50311201_146_dialog_content = "まさか、ハンターを倒した時みたいに、\n大きな石を飲ませるとか…",
  ui_story_5031_50311201_147_dialog_content = "危ないよ！",
  ui_story_5031_50311201_148_dialog_content = "そんなことするわけないでしょ！",
  ui_story_5031_50311201_149_dialog_content = "今日用意したのは、コレ！",
  ui_story_5031_50311201_150_dialog_content = "見て見て――！",
  ui_story_5031_50311201_151_dialog_content = "シャボン玉！？",
  ui_story_5031_50311201_152_dialog_content = "きれいだな！",
  ui_story_5031_50311201_153_dialog_content = "でも、ショーと何の関係があるんだ？",
  ui_story_5031_50311201_154_dialog_content = "さぁ、ビッカー！出番だよ！",
  ui_story_5031_50311201_155_dialog_content = "ハイハイ！",
  ui_story_5031_50311201_156_dialog_content = "ハーイ！",
  ui_story_5031_50311201_157_dialog_content = "（確かにシャボン玉は、\nビッカーの大好きな丸い形だ！）",
  ui_story_5031_50311201_158_dialog_content = "おお！あの動物、こんな能力があったのか！？",
  ui_story_5031_50311201_159_dialog_content = "ハイ！",
  ui_story_5031_50311201_160_dialog_content = "ハイ…ハイ…",
  ui_story_5031_50311201_161_dialog_content = "げぷっ…",
  ui_story_5031_50311201_162_dialog_content = "（空気をたくさん食べ過ぎて、\nビッカーの身体がパンパンだ！）",
  ui_story_5031_50311201_163_dialog_content = "かわいい！アハハ！",
  ui_story_5031_50311201_164_dialog_content = "それでは、フィアのショーはここまで！",
  ui_story_5031_50311201_165_dialog_content = "引き続き、あたしたちのショーをお楽しみください！",
  ui_story_5031_50311201_166_dialog_content = "わー！！",
  ui_story_5031_50311201_167_dialog_content = "フィアのショーが終わってから、\n僕、バイス、カレンが順番にステージへ上がった…",
  ui_story_5031_50311201_168_dialog_content = "僕は感知能力で読心術のショーをして…",
  ui_story_5031_50311201_169_dialog_content = "バイスは弓の腕を生かして、射的を見せた…",
  ui_story_5031_50311201_170_dialog_content = "…ただ、次は的のリンゴを\n僕の頭の上に置かないで欲しい！！",
  ui_story_5031_50311201_171_dialog_content = "一番すごかったのは、やっぱりカレンだった。\nカレンのバレエは会場の皆が思わず見とれた…",
  ui_story_5031_50311201_172_dialog_content = "しかも、驚いたことに…ジェノに協力を頼んで、\n暗鬼をステージに出し、ショーの道具にした！",
  ui_story_5031_50311202_1_dialog_content = "アイスブロッサム！",
  ui_story_5031_50311202_2_dialog_content = "バレエと戦闘を組み合わせるなんて、\nきっとカレンにしかできないことだろう。",
  ui_story_5031_50311202_3_dialog_content = "本当に…すごかった！",
  ui_story_5031_50311202_4_dialog_content = "カレン選手のパフォーマンスに拍手～！\nスリリングかつ優雅なショーでした！",
  ui_story_5031_50311202_5_dialog_content = "続いては、みなさんお待ちかね――",
  ui_story_5031_50311202_6_dialog_content = "ついに…結果発表！",
  ui_story_5031_50311202_7_dialog_content = "ハイ！",
  ui_story_5031_50311202_8_dialog_content = "き、緊張で…息が…",
  ui_story_5031_50311202_9_dialog_content = "しっかりして、フィア！",
  ui_story_5031_50311202_10_dialog_content = "海雲クジラを助けるんでしょ！",
  ui_story_5031_50311202_11_dialog_content = "海雲クジラ…そうだ、海雲クジラ！\nフィアの賞品！",
  ui_story_5031_50311202_12_dialog_content = "それでは、優勝者の発表は僕から。\n優勝は――",
  ui_story_5031_50311202_13_dialog_content = "フィアチーム！",
  ui_story_5031_50311202_14_dialog_content = "フィア、勝ったの…？",
  ui_story_5031_50311202_15_dialog_content = "やった！勝てたよ！！",
  ui_story_5031_50311202_16_dialog_content = "ハイ！",
  ui_story_5031_50311202_17_dialog_content = "フィア選手の猛獣ショーには、少々のお茶目があったようですが…\nチームのメンバー全員が、見事なショーを見せてくれました。",
  ui_story_5031_50311202_18_dialog_content = "特にカレン選手のバレエは、\n空前の素晴らしさといっても良いでしょう。",
  ui_story_5031_50311202_19_dialog_content = "結果…全体の平均点は、\nフィアチームが1位となりました。",
  ui_story_5031_50311202_20_dialog_content = "おめでとう、フィア。",
  ui_story_5031_50311202_21_dialog_content = "チビっ子なのに、\nこんなに手強いとは思わなかったよ！",
  ui_story_5031_50311202_22_dialog_content = "今回は負けちゃったけど、\n次は負けないよ！",
  ui_story_5031_50311202_23_dialog_content = "やったわ！\nフィアも何とかうまくいったし、良かったわね！",
  ui_story_5031_50311202_24_dialog_content = "ただ、やはり気になるわ。\n優勝賞品…一体何なのかしら。",
  ui_story_5031_50311202_25_dialog_content = "本当に、フィアの心配している\n海雲クジラが…？",
  ui_story_5031_50311202_26_dialog_content = "そうそう！フィアの賞品！！\n深海から引き揚げた、唯一無二の宝物！！",
  ui_story_5031_50311202_27_dialog_content = "その通りです。賞品をお持ちしましたよ。",
  ui_story_5031_50311202_28_dialog_content = "こちらです。",
  ui_story_5031_50311202_29_dialog_content = "ル！ルルル！",
  ui_story_5031_50311202_30_dialog_content = "ひゃあ！？ここここ、これって…\nキャロじゃない！？",
  ui_story_5031_50311202_31_dialog_content = "海雲クジラの手掛かりを\n探してって、言ってあったでしょ！？",
  ui_story_5031_50311202_32_dialog_content = "全然連絡してこないと思ったら…\nここでサボってたの！？",
  ui_story_5031_50311202_33_dialog_content = "少し前に僕が海から引き揚げました。",
  ui_story_5031_50311202_34_dialog_content = "味が良さそうなので、\nスープにでもして優勝者にふるまおうかと思っていましたが…",
  ui_story_5031_50311202_35_dialog_content = "ルルル！？ルル！？",
  ui_story_5031_50311202_36_dialog_content = "キャロを食べちゃダメ！",
  ui_story_5031_50311202_37_dialog_content = "キャロはフィアの仲間なの！",
  ui_story_5031_50311202_38_dialog_content = "あなたのお仲間でしたか？\nてっきり珍しい食材かと…",
  ui_story_5031_50311202_39_dialog_content = "しかし、優勝者はあなたで、賞品としてお渡ししましたから。\nどのようにしようと、あなたのご自由に。",
  ui_story_5031_50311202_40_dialog_content = "ルル…",
  ui_story_5031_50311202_41_dialog_content = "はぁ…キャロ、油断しすぎだよ。\nもう少しでスープになるとこだったんだよ？",
  ui_story_5031_50311202_42_dialog_content = "ル…ルル！",
  ui_story_5031_50311202_43_dialog_content = "海底で海雲クジラを探してたら、\n急に網で引き上げられちゃった？",
  ui_story_5031_50311202_44_dialog_content = "しかも何日も船の中に閉じ込められてた？",
  ui_story_5031_50311202_45_dialog_content = "じゃあ、船の中で海雲クジラを見かけなかった？",
  ui_story_5031_50311202_46_dialog_content = "ル？ルル！",
  ui_story_5031_50311202_47_dialog_content = "なんだ…見なかったんだ。",
  ui_story_5031_50311202_48_dialog_content = "成績発表および、賞品授与は終了しました。\nそれでは皆様、甲板へお越しください。",
  ui_story_5031_50311202_49_dialog_content = "祝宴と花火が間もなく始まります。",
  ui_story_5031_50311202_50_dialog_content = "花火もあるの？\n急いでいい場所を取りにいかなきゃ！",
  ui_story_5031_50311202_51_dialog_content = "海雲クジラ…\nどうして海雲クジラが賞品じゃないの？",
  ui_story_5031_50311202_52_dialog_content = "結局、ぜんぶムダな努力になっちゃった！",
  ui_story_5031_50311202_53_dialog_content = "クジラが賞品のはずないでしょう？",
  ui_story_5031_50311202_54_dialog_content = "子どものクジラとて、エメラルド号には収まりませんよ。",
  ui_story_5031_50311202_55_dialog_content = "本物のクジラをご覧になったことはありますか？",
  ui_story_5031_50311202_56_dialog_content = "み、見たことなかったら、何！？",
  ui_story_5031_50311202_57_dialog_content = "あたしが探してるのは超希少種！\n簡単に見れるはずないでしょ！？",
  ui_story_5031_50311202_58_dialog_content = "ぷっ…",
  ui_story_5031_50311202_59_dialog_content = "笑わないで！！！",
  ui_story_5031_50311202_60_dialog_content = "ごめんごめん…\nでも、ムダな努力じゃないよ。",
  ui_story_5031_50311202_61_option_content = "少なくとも、勝負に勝った",
  ui_story_5031_50311202_62_dialog_content = "フィアもサーカス船のビッカーと友だちになったでしょ？",
  ui_story_5031_50311202_63_dialog_content = "ハイ！",
  ui_story_5031_50311202_64_dialog_content = "わ、わかったって！ブドウはちゃんと買ってあげる！",
  ui_story_5031_50311202_65_option_content = "キャロは助かった",
  ui_story_5031_50311202_66_dialog_content = "ルル！",
  ui_story_5031_50311202_67_dialog_content = "はぁ…ただ、最後の最後で\n優勝賞品がキャロなんて思わなかったよ…",
  ui_story_5031_50311202_68_dialog_content = "うっかりつかまっちゃったんでしょ？\n戻って海雲クジラ探しを続けて。",
  ui_story_5031_50311202_69_dialog_content = "ルルル？",
  ui_story_5031_50311202_70_dialog_content = "あたしの方は、手助けなんかいらないから！\nさっさと戻って調べて！",
  ui_story_5031_50311202_71_dialog_content = "ほらっ！",
  ui_story_5031_50311202_72_dialog_content = "ルルル～！！",
  ui_story_5031_50311202_73_dialog_content = "（キャロがはるか彼方の星みたいに…\nすごい力だ！）",
  ui_story_5031_50311202_74_dialog_content = "おや、あなたは…\n本当に珍獣の専門家だったのですか？",
  ui_story_5031_50311202_75_dialog_content = "正真正銘、ホンモノだよ！",
  ui_story_5031_50311202_76_dialog_content = "ところで、あの占いって、どうやったの？",
  ui_story_5031_50311202_77_dialog_content = "まさか、ジェノさんも空の末裔の一族で、\n不思議な感知能力を持ってるとか？",
  ui_story_5031_50311202_78_dialog_content = "いえ、あれは本物の占いですらありません。\n相手を観察して、推測しただけのことです。",
  ui_story_5031_50311202_79_dialog_content = "あの女性の服は大衆的なデザインでしたが、\n生地はペドロ要塞でしか作られていないものでした。",
  ui_story_5031_50311202_80_dialog_content = "家庭を築いているかどうかは、\n手にはめていた指輪で分かります。",
  ui_story_5031_50311202_81_dialog_content = "離れた席に夫が座っていたことは、\n彼女がしばしば振り向いて、その方を見ていたことで分かりました。",
  ui_story_5031_50311202_82_dialog_content = "そういった観察から、答えを出したのです――",
  ui_story_5031_50311202_83_dialog_content = "ジェノ、邪魔して済まないが、話したいことがある。\nステージの方に来てもらえるか？",
  ui_story_5031_50311202_84_dialog_content = "分かりました。",
  ui_story_5031_50311202_85_dialog_content = "申し訳ございませんが、\n私は失礼致します。",
  ui_story_5031_50311202_86_dialog_content = "ちょっと！まだ話の途中なのに！",
  ui_story_5031_50311202_87_dialog_content = "もう！いいところで行っちゃうなんて。",
  ui_story_5031_50311202_88_dialog_content = "花火大会、始まったわよ！",
  ui_story_5031_50311202_89_dialog_content = "ええ、きれいね。",
  ui_story_5031_50311202_90_dialog_content = "あなたたち、ここにいたんだね！",
  ui_story_5031_50311202_91_dialog_content = "み、みんな、ここにいたんだ…",
  ui_story_5031_50311202_92_dialog_content = "レインボー、たくさん抱えてる食べ物はどうしたの？\n持って帰るの？",
  ui_story_5031_50311202_93_dialog_content = "花火は見ていかないの？",
  ui_story_5031_50311202_94_dialog_content = "あたしたち、他に予定があるから！",
  ui_story_5031_50311202_95_dialog_content = "花火も悪くないけど…さっき、シエルと2人で\nパワードスーツのいい改造案を思いついたの！",
  ui_story_5031_50311202_96_dialog_content = "早く帰って試したいから！",
  ui_story_5031_50311202_97_dialog_content = "そういうこと…",
  ui_story_5031_50311202_98_dialog_content = "ごめん、みんなとおしゃべりできなくて。",
  ui_story_5031_50311202_99_dialog_content = "いいのよ、機会はまたいくらでもあるわ！",
  ui_story_5031_50311202_100_dialog_content = "じゃあ、お先に～！",
  ui_story_5031_50311202_101_dialog_content = "あの2人、とても仲良くなったようね。\n少しうらやましいわ。",
  ui_story_5031_50311202_102_dialog_content = "カレン、何言ってるの？",
  ui_story_5031_50311202_103_dialog_content = "あなたには、私とPlayerNameっていう\n親友が2人もいるでしょ！",
  ui_story_5031_50311202_104_dialog_content = "そうそう！僕たちはずっと、\n一緒に旅して、一緒に冒険してきたでしょ？",
  ui_story_5031_50311202_105_dialog_content = "今回だってそうじゃない！",
  ui_story_5031_50311202_106_dialog_content = "カレンのバレエが無かったら、\nきっと負けてたわ！",
  ui_story_5031_50311202_107_dialog_content = "そうだよ、君のおかげだよ！",
  ui_story_5031_50311202_108_dialog_content = "みずくさいわ、カレン！",
  ui_story_5031_50311202_109_dialog_content = "そうね…フフ、分かっているわ。",
  ui_story_5031_50311202_110_dialog_content = "ありがとう。",
  ui_story_5031_50311202_111_dialog_content = "ええ！",
  ui_story_5031_50311301_1_dialog_content = "昼間は気付かなかったけれど、こうしてよく見ると、\n夜空と花火に照らされたハーバーシティは本当にきれいね。",
  ui_story_5031_50311301_2_dialog_content = "そうね。白い建物が花火の色でカラフルになって、\n昼間よりずっときれいだわ。",
  ui_story_5031_50311301_3_dialog_content = "PlayerName、バイス、それからフィア。\n私、エルビスに話があるの。",
  ui_story_5031_50311301_4_dialog_content = "少し待っていてくれる？",
  ui_story_5031_50311301_5_dialog_content = "もっちろん！ここで待ってるよ。",
  ui_story_5031_50311301_6_dialog_content = "ええ、ありがとう。",
  ui_story_5031_50311301_7_dialog_content = "ようやく、これで一段落ついたね。",
  ui_story_5031_50311301_8_dialog_content = "でも、海雲クジラはまだ見つかってないよ…",
  ui_story_5031_50311301_9_dialog_content = "伝説の海雲クジラ…\nいったいどこにいったんだろ…",
  ui_story_5031_50311301_10_dialog_content = "あせっちゃダメだよ。\n急いでもどうにもならないことっていうのもあるんだ。",
  ui_story_5031_50311301_11_dialog_content = "そうね。私も朝起きて、ヘアピンが見つからない時とか…\nあせればあせるほど見つからないの。",
  ui_story_5031_50311301_12_dialog_content = "でも、あきらめかけた時にふと、\n手に持ってることに気づいたりするものよ！",
  ui_story_5031_50311301_13_dialog_content = "ほんとに？",
  ui_story_5031_50311301_14_dialog_content = "もちろん！",
  ui_story_5031_50311301_15_dialog_content = "わかった、信じる。",
  ui_story_5031_50311301_16_dialog_content = "みんな…",
  ui_story_5031_50311301_17_dialog_content = "あら？カレン、もう話は終わったの？",
  ui_story_5031_50311301_18_dialog_content = "いいえ、そうではないの。\nエルビスがどこにも見つからないのよ。",
  ui_story_5031_50311301_19_dialog_content = "団長とステージで話してるんじゃない？",
  ui_story_5031_50311301_20_dialog_content = "ステージは見に行ったわ。\nでも、2人はいなかった。",
  ui_story_5031_50311301_21_dialog_content = "エルビスさんとジェノ…",
  ui_story_5031_50311301_22_dialog_content = "まさか、あの船倉に向かった…？",
  ui_story_5031_50311301_23_dialog_content = "船倉？船の中には団員以外入れないはずではないかしら？",
  ui_story_5031_50311301_24_dialog_content = "でも、他の所にいないのなら、\nそこにいる可能性が高いよ。",
  ui_story_5031_50311301_25_dialog_content = "見にいってみよう。方向さえ合ってれば、\n2人がどこに行ったか、誰かは知ってるはず。",
  ui_story_5031_50311301_26_dialog_content = "PlayerName、船の中に妙に詳しいようね？",
  ui_story_5031_50311301_27_dialog_content = "実は、さっきフィアと僕が、\nここでエルビスさんとパトに追いかけられて…",
  ui_story_5031_50311301_28_dialog_content = "エルビスさんとパト？どういうこと？",
  ui_story_5031_50311301_29_dialog_content = "話すと長くなるんだけど、実は…",
  ui_story_5031_50311301_30_dialog_content = "PlayerName、見て！\nあそこに誰か倒れてる！",
  ui_story_5031_50311301_31_dialog_content = "あれは…ジェノ！？",
  ui_story_5031_50311301_32_dialog_content = "ほんとに？僕の絵を描いてくれるの？",
  ui_story_5031_50311301_33_dialog_content = "うん…描くのは遅いし、\nそんなにうまくないけど…",
  ui_story_5031_50311301_34_dialog_content = "別にいいよ。\nジェノが描いた絵なら、きっと一番いい絵だよ！",
  ui_story_5031_50311301_35_dialog_content = "じゃあ、明日の朝一番に、\n港で待ち合わせだよ？",
  ui_story_5031_50311301_36_dialog_content = "潮干狩りが終わったら、ジェノは絵を描いて！\nその間に、僕が海鮮スープを作ってあげる！",
  ui_story_5031_50311301_37_dialog_content = "わあ！エルビスの海鮮スープ！？",
  ui_story_5031_50311301_38_dialog_content = "いいね！じゃあ、約束だよ！",
  ui_story_5031_50311301_39_dialog_content = "また明日！",
  ui_story_5031_50311301_40_dialog_content = "うん、また明日！",
  ui_story_5031_50311301_41_dialog_content = "…",
  ui_story_5031_50311301_42_dialog_content = "…",
  ui_story_5031_50311301_43_dialog_content = "約束したのに…",
  ui_story_5031_50311301_44_dialog_content = "あんなに、約束したのに…",
  ui_story_5031_50311301_45_dialog_content = "<size=33>ジェ…</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>ジェノ…</size>",
  ui_story_5031_50311301_47_dialog_content = "ん？誰だ？",
  ui_story_5031_50311301_48_dialog_content = "ジェノ団長！",
  ui_story_5031_50311301_49_dialog_content = "エルビス？君か？戻ってきたのか？",
  ui_story_5031_50311301_50_dialog_content = "<size=45>ジェノ、しっかりして！</size>",
  ui_story_5031_50311301_51_dialog_content = "エルビス！",
  ui_story_5031_50311301_52_dialog_content = "うわっ！？",
  ui_story_5031_50311301_53_dialog_content = "わあ！！",
  ui_story_5031_50311301_54_dialog_content = "PlayerName、いきなり大声でどうしたの？\nビックリしたよ！",
  ui_story_5031_50311301_55_dialog_content = "ご…ごめん、僕もびっくりして…",
  ui_story_5031_50311301_56_dialog_content = "ジェノさん、気分は？どこかケガしてない？",
  ui_story_5031_50311301_57_dialog_content = "僕は…どうしてここに？",
  ui_story_5031_50311301_58_dialog_content = "それはこっちが聞きたいよ。",
  ui_story_5031_50311301_59_dialog_content = "どうしてこんな所に転がって寝てるの？\nあたしたち、ずっと探してたんだよ。",
  ui_story_5031_50311301_60_dialog_content = "あのね、フィア。\n別に寝てたわけじゃないと思う…",
  ui_story_5031_50311301_61_dialog_content = "説明するわね…花火も祝宴も終わった後、\nエルビスにあいさつをして帰ろうと思っていたの。",
  ui_story_5031_50311301_62_dialog_content = "だけど、どこを探しても見つからないから、\nもしかしたら船の中かもしれないと思って…",
  ui_story_5031_50311301_63_dialog_content = "勝手に見に来たの。\nそうしたら、あなたがここで気を失っていたわ。",
  ui_story_5031_50311301_64_dialog_content = "さっき…うっ…",
  ui_story_5031_50311301_65_dialog_content = "ここなら誰にも邪魔されませんよ。\nエルビス、何の話ですか？",
  ui_story_5031_50311301_66_dialog_content = "ジェノ、お前に…礼を伝えたいと思ってね。",
  ui_story_5031_50311301_67_dialog_content = "…どうしたんです、そんな急に？",
  ui_story_5031_50311301_68_dialog_content = "何の礼です？",
  ui_story_5031_50311301_69_dialog_content = "私の招待を受けてくれたことに、だ。\nハーバーシティの民に、美しい一生の思い出を残してくれた。",
  ui_story_5031_50311301_70_dialog_content = "お前が来てくれたこと…\nそれ自体、私には大きな意味をもつのだ。",
  ui_story_5031_50311301_71_dialog_content = "サーカスはあちこちを渡り歩くものですから。\nどこに留まってショーをやろうと、同じことです。",
  ui_story_5031_50311301_72_dialog_content = "それに、報酬も手厚いものでしたから。\nこちらこそお礼を言うべきでしょう。",
  ui_story_5031_50311301_73_dialog_content = "いや、ジェノ。",
  ui_story_5031_50311301_74_dialog_content = "お前への借りは、返しようがない…",
  ui_story_5031_50311301_75_dialog_content = "「借り」？それは、何のことを…",
  ui_story_5031_50311301_76_dialog_content = "うっ！？",
  ui_story_5031_50311301_77_dialog_content = "…すまない。",
  ui_story_5031_50311301_78_dialog_content = "ゲホッ！…な…なにを…",
  ui_story_5031_50311301_79_dialog_content = "何をするつもりです…？",
  ui_story_5031_50311301_80_dialog_content = "ジェノ…本当にすまない。",
  ui_story_5031_50311301_81_dialog_content = "つまり、エルビスが何かを使って、\nあなたの気を失わせた？",
  ui_story_5031_50311301_82_dialog_content = "ええ。",
  ui_story_5031_50311301_83_dialog_content = "え？あの人、悪い人だったの？",
  ui_story_5031_50311301_84_dialog_content = "フィア、真相はまだ分からないのよ。\n結論を早まってはいけないわ。",
  ui_story_5031_50311301_85_dialog_content = "<size=33>まずい。本当に見当たらない…</size>",
  ui_story_5031_50311301_86_dialog_content = "ジェノ、どうしたの？何を探して…",
  ui_story_5031_50311301_87_dialog_content = "うわ！何！？",
  ui_story_5031_50311301_88_dialog_content = "船が…揺れてる？",
  ui_story_5031_50311301_89_dialog_content = "…まさかあいつが…本当にここまでするとは。",
  ui_story_5031_50311301_90_dialog_content = "待って！！",
  ui_story_5031_50311301_91_dialog_content = "ジェ…ジェノ…ふぅ…",
  ui_story_5031_50311301_92_dialog_content = "まずは、一体どういうことか、話してもらえない？",
  ui_story_5031_50311301_93_dialog_content = "…",
  ui_story_5031_50311301_94_dialog_content = "仕方ありません。",
  ui_story_5031_50311301_95_dialog_content = "あいつが本当に「アレ」を目覚めさせたのなら、\n確かに僕にはあなたたちの力が必要です。",
  ui_story_5031_50311301_96_dialog_content = "「アレ」って？",
  ui_story_5031_50311301_97_dialog_content = "先ほど気がついた後、肌身離さず持っていた\n船のコアルームの鍵が失くなっていました。",
  ui_story_5031_50311301_98_dialog_content = "そこに、何か重要なものが？",
  ui_story_5031_50311301_99_dialog_content = "ええ。「<color=#FFB400>エネルギーコア</color>」です。",
  ui_story_5031_50311301_100_dialog_content = "「エネルギーコア」！？",
  ui_story_5031_50311301_101_dialog_content = "3人とも、詳しそうだね？",
  ui_story_5031_50311301_102_dialog_content = "「エネルギーコア」というのは旧文明の産物で…\nとても貴重な資源と考えればいいわ。",
  ui_story_5031_50311301_103_dialog_content = "まさか、この船にあるなんて…",
  ui_story_5031_50311301_104_dialog_content = "この船自体、遺跡から掘り出されたものですから。",
  ui_story_5031_50311301_105_dialog_content = "「アレ」と言うのは、\n「エネルギーコア」を守る――",
  ui_story_5031_50311301_106_dialog_content = "「<color=#FFB400>守護者</color>」のことです。",
  ui_story_5031_50311301_107_dialog_content = "コアの守護者が目覚めれば、\nエネルギーコアに近づくあらゆる生命体を無差別に攻撃します。",
  ui_story_5031_50311301_108_dialog_content = "そうなれば、\nこの船全体の危機です。",
  ui_story_5031_50311301_109_dialog_content = "あなたは、自分が気を失っている間に\nエルビスが鍵を盗んだと言いたいのね。",
  ui_story_5031_50311301_110_dialog_content = "そしてコアルームへ侵入し、\n「エネルギーコア」を奪おうとしている？",
  ui_story_5031_50311301_111_dialog_content = "おそらく、そうだと思うのです。しかし…",
  ui_story_5031_50311301_112_dialog_content = "団長！",
  ui_story_5031_50311301_113_dialog_content = "あ、レインボーお姉ちゃんとシエルお姉ちゃん！",
  ui_story_5031_50311301_114_dialog_content = "大変だよ！さっき機関室で、\nコアルームが開いてるって表示が出てたの！",
  ui_story_5031_50311301_115_dialog_content = "分かりました、今すぐ向かいましょう。",
  ui_story_5031_50311301_116_dialog_content = "警備のために雇ってた傭兵さんたちも、\nここに来る途中で気を失ってて…",
  ui_story_5031_50311301_117_dialog_content = "レインボー、危ない！",
  ui_story_5031_50311301_118_dialog_content = "危なかったぁ！\nシエル、ありがとう。",
  ui_story_5031_50311301_119_dialog_content = "あれ？この人たち…ハーバーシティの衛兵じゃない？",
  ui_story_5031_50311301_120_dialog_content = "…足止めでしょうね。",
  ui_story_5031_50311301_121_dialog_content = "…",
  ui_story_5031_50311301_122_dialog_content = "愚かな従僕どもめ…道を開けなさい！",
  ui_story_5031_50311302_1_dialog_content = "エルビス…",
  ui_story_5031_50311302_2_dialog_content = "これだけの人数、\n一体いつ、船の中に入ったのでしょう？",
  ui_story_5031_50311302_3_dialog_content = "また新しい光力が近づいてくる！",
  ui_story_5031_50311302_4_dialog_content = "数は…さっきのより多いってことだけは間違いない！",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>ドンッ――</color>",
  ui_story_5031_50311302_6_dialog_content = "あ、あたしの船が！",
  ui_story_5031_50311302_7_dialog_content = "エルビスってヤツ、あたしの船に何する気！？",
  ui_story_5031_50311302_8_dialog_content = "このままでは、ここから動けなくなりそうね。",
  ui_story_5031_50311302_9_dialog_content = "みんな、困ってる…",
  ui_story_5031_50311302_10_dialog_content = "だったら！",
  ui_story_5031_50311302_11_dialog_content = "「アームチェンジ――Ⅲ型」！",
  ui_story_5031_50311302_12_dialog_content = "「レッグチェンジ――Ⅲ型」！",
  ui_story_5031_50311302_13_dialog_content = "「エネルギー解放比率70%上昇」！",
  ui_story_5031_50311302_14_dialog_content = "えっ？",
  ui_story_5031_50311302_15_dialog_content = "シエル、何してるの！？\nチューニングはまだ終わってないんだよ！",
  ui_story_5031_50311302_16_dialog_content = "ここはあたしが引き留める！\nみんなは急いで、コアルームに行って！",
  ui_story_5031_50311302_17_dialog_content = "でも…",
  ui_story_5031_50311302_18_dialog_content = "安心して！",
  ui_story_5031_50311302_19_dialog_content = "レインボーと一緒にチューニングしたんだよ。\n「ステュクス」は絶対大丈夫！",
  ui_story_5031_50311302_20_dialog_content = "シエルの言う通りね。",
  ui_story_5031_50311302_21_dialog_content = "ここでモタモタしているわけにはいかない。\nすでにかなりの時間を浪費しているの。",
  ui_story_5031_50311302_22_dialog_content = "仲間を…信じるのよ。\nここはシエルに任せましょう。",
  ui_story_5031_50311302_23_dialog_content = "カレン…",
  ui_story_5031_50311302_24_dialog_content = "（カレン、様子が変わった）",
  ui_story_5031_50311302_25_dialog_content = "…",
  ui_story_5031_50311302_26_dialog_content = "シエル、ハイになり過ぎて\n壊したらダメだからね！",
  ui_story_5031_50311302_27_dialog_content = "そんなことしたら、\n船の弁償も、高～くつくよ！？",
  ui_story_5031_50311302_28_dialog_content = "え、ええ！？",
  ui_story_5031_50311302_29_dialog_content = "わ、分かった、安心して。",
  ui_story_5031_50311302_30_dialog_content = "シエル、頼んだわ。",
  ui_story_5031_50311302_31_dialog_content = "シエル、気を付けて！",
  ui_story_5031_50311302_32_dialog_content = "お嬢さん、こっちも多勢に無勢なんてことはしたくない。\n大人しく道を開けてもらおうか。",
  ui_story_5031_50311302_33_dialog_content = "あなたたちを足止めするぐらい、\nあたし1人で十分！",
  ui_story_5031_50311302_34_dialog_content = "…なら、遠慮はせんぞ！",
  ui_story_5031_50311302_35_dialog_content = "うう、さっきの人たちより強い、\n数も多い…",
  ui_story_5031_50311302_36_dialog_content = "こうなったら、もう…",
  ui_story_5031_50311302_37_dialog_content = "「エネルギー解放比率80%に上昇」！",
  ui_story_5031_50311302_38_dialog_content = "なんだ…出力をまだ上げる気か？",
  ui_story_5031_50311302_39_dialog_content = "クソッ、まるでバケモノだ。",
  ui_story_5031_50311302_40_dialog_content = "だが、領主様のためだ、\n絶対にやられるわけにはいかん！",
  ui_story_5031_50311302_41_dialog_content = "第一隊！隊形を維持し、\n光力の盾で陣を組んで前進、接近しろ！",
  ui_story_5031_50311302_42_dialog_content = "パワードスーツさえなければ、\nあの女は戦えないはずだ！",
  ui_story_5031_50311302_43_dialog_content = "了解！",
  ui_story_5031_50311302_44_dialog_content = "あの盾…重ねたら硬度が上がってる？",
  ui_story_5031_50311302_45_dialog_content = "今だ！第二隊、光力銃を準備、構え！",
  ui_story_5031_50311302_46_dialog_content = "まずい、盾を崩せないと、接近される…",
  ui_story_5031_50311302_47_dialog_content = "ダメ、冷静にならないと。ふぅ――",
  ui_story_5031_50311302_48_dialog_content = "硬度が上がったとしても、エネルギー供給が必要ってことは、\n強度はきっと光力と関係してる。",
  ui_story_5031_50311302_49_dialog_content = "それなら、あたしはもっと強い光力を\nぶつければいいだけ！",
  ui_story_5031_50311302_50_dialog_content = "でも「ステュクス」は今日、\nもう1回破損しちゃってる…",
  ui_story_5031_50311302_51_dialog_content = "これ以上出力を上げたら、\n「ステュクス」は…",
  ui_story_5031_50311302_52_dialog_content = "あたしね、もうちゃんと考えてるの。パワードスーツが出来たら…\nみんなのために、いろんなことをするんだ！",
  ui_story_5031_50311302_53_dialog_content = "あら、そう？じゃあ、パワードスーツが出来たら、\nあなたが一番やりたいことは何？",
  ui_story_5031_50311302_54_dialog_content = "一番やりたいことは…",
  ui_story_5031_50311302_55_dialog_content = "一番やりたいことは…",
  ui_story_5031_50311302_56_dialog_content = "友だちを助けて、仲間を守る、\n頼れる人になりたい！",
  ui_story_5031_50311302_57_dialog_content = "ごめん、レインボー…\n「ステュクス」！",
  ui_story_5031_50311302_58_dialog_content = "<size=45>「エネルギー解放比率100%に上昇」！</size>",
  ui_story_5031_50311302_59_dialog_content = "な、なんだと？\n光力の盾が破られた！？",
  ui_story_5031_50311302_60_dialog_content = "本当にバケモノか！？",
  ui_story_5031_50311302_61_dialog_content = "ふぅ…ふぅ…",
  ui_story_5031_50311302_62_dialog_content = "やっぱり、ちょっとムリだった…",
  ui_story_5031_50311302_63_dialog_content = "足のジョイントがおかしくなってる。\n光力も…",
  ui_story_5031_50311302_64_dialog_content = "ひるむな！",
  ui_story_5031_50311302_65_dialog_content = "盾が破られてもどうってことはない！\nやつのエネルギーも無限ではないんだ！",
  ui_story_5031_50311302_66_dialog_content = "これだけの人数がいて、\nたった1人の小娘に敗れるわけには行かんだろう！？",
  ui_story_5031_50311302_67_dialog_content = "…そうだ！",
  ui_story_5031_50311302_68_dialog_content = "ふぅ…はあ…この先には…行かせない…",
  ui_story_5031_50311302_69_dialog_content = "攻撃が弱まったぞ、今だ！",
  ui_story_5031_50311302_70_dialog_content = "これだけ数がいるのに、こんなに苦戦するなんて、\nそれでもハーバーシティの衛兵さん？",
  ui_story_5031_50311302_71_dialog_content = "この声は…？",
  ui_story_5031_50311302_72_dialog_content = "あっ！",
  ui_story_5031_50311302_73_dialog_content = "さ、さっきのあいつだ！",
  ui_story_5031_50311302_74_dialog_content = "もう、ハイになり過ぎちゃダメって言ったのに！\nやっぱり聞いてなかったね！",
  ui_story_5031_50311302_75_dialog_content = "「ステュクス」、もうボロボロじゃない！\nお昼からまるまるかけてた修理がムダになっちゃってるよ！",
  ui_story_5031_50311302_76_dialog_content = "レインボー！どうして戻ってきたの！？",
  ui_story_5031_50311302_77_dialog_content = "あなたが心配だったから！",
  ui_story_5031_50311302_78_dialog_content = "じゃあ、コアルームは！？",
  ui_story_5031_50311302_79_dialog_content = "団長たちに任せるよ。",
  ui_story_5031_50311302_80_dialog_content = "むっ、不意打ち！？",
  ui_story_5031_50311302_81_dialog_content = "うっ！",
  ui_story_5031_50311302_82_dialog_content = "…",
  ui_story_5031_50311302_83_dialog_content = "あれ？シエル、どうしたの？\nなんで、そんな顔してるの？",
  ui_story_5031_50311302_84_dialog_content = "…そうだよね。",
  ui_story_5031_50311302_85_dialog_content = "あたしみたいな、すぐにあせっちゃう人なんて、\n信頼とか、頼りがいとか、言う資格ないよね…",
  ui_story_5031_50311302_86_dialog_content = "今もレインボーが戻って来なかったら、\nあたし、たぶん…",
  ui_story_5031_50311302_87_dialog_content = "…",
  ui_story_5031_50311302_88_dialog_content = "シエルって時どき急に、\nちょっとおバカさんになるところ、あるよね～。",
  ui_story_5031_50311302_89_dialog_content = "えっ？",
  ui_story_5031_50311302_90_dialog_content = "ま、そういうところも、あたしは好きだけど！",
  ui_story_5031_50311302_91_dialog_content = "あたしはあなたを信じてるからこそ、\nきっと100％の力を出して衛兵を止めようとするって思ったんだよ。",
  ui_story_5031_50311302_92_dialog_content = "でも「ステュクス」の状況は、あなたの次にわかってる。\nだから、結果も予想はついたんだ。",
  ui_story_5031_50311302_93_dialog_content = "…",
  ui_story_5031_50311302_94_dialog_content = "団長たちのことも信じてるの！\n絶対に「エメラルド号」を守ってくれる！",
  ui_story_5031_50311302_95_dialog_content = "だから、安心して！",
  ui_story_5031_50311302_96_dialog_content = "これが片付いたら、\n一緒に「ステュクス」を改良しよ！",
  ui_story_5031_50311302_97_dialog_content = "必ず、ピッカピカで元気いっぱいの、\n300％出しても壊れない子にしてあげるから！",
  ui_story_5031_50311302_98_dialog_content = "…うん。",
  ui_story_5031_50311302_99_dialog_content = "でも今は、このしつこい人たちから！",
  ui_story_5031_50311302_100_dialog_content = "衛兵さんだっていうのに、\n不意打ちに、大勢で弱い者いじめ…",
  ui_story_5031_50311302_101_dialog_content = "そんなのでいいの？",
  ui_story_5031_50311302_102_dialog_content = "…",
  ui_story_5031_50311401_1_dialog_content = "ゲホッ…ゴホゴホ。",
  ui_story_5031_50311401_2_dialog_content = "これで、準備はすべて整った…",
  ui_story_5031_50311401_3_dialog_content = "後は最後のコマが到着するのを待つだけだ。",
  ui_story_5031_50311401_4_dialog_content = "エルビス様、足音が近づいてきます。",
  ui_story_5031_50311401_5_dialog_content = "よし、中に入れろ。お前たちは計画通り、急いでこの船から離れ、\n他の者たちが近づかないようにしろ。",
  ui_story_5031_50311401_6_dialog_content = "…",
  ui_story_5031_50311401_7_dialog_content = "どうしたのだ？",
  ui_story_5031_50311401_8_dialog_content = "それでよろしいのですか、エルビス様。",
  ui_story_5031_50311401_9_dialog_content = "エルビス様お一人、残していくわけには…",
  ui_story_5031_50311401_10_dialog_content = "お前の仕事はもう終わった。\n後は私が、みずから向き合わねばならんことだ。",
  ui_story_5031_50311401_11_dialog_content = "…",
  ui_story_5031_50311401_12_dialog_content = "それとも、パト。\n私のことが信じられないか？",
  ui_story_5031_50311401_13_dialog_content = "無論、信じております。そのようなつもりで\n申したのではないことは、分かっておいででしょう？",
  ui_story_5031_50311401_14_dialog_content = "ならば、信じろ。急いでここを離れてくれ。\nお前たちがここに居ては、かえって計画の邪魔になる。",
  ui_story_5031_50311401_15_dialog_content = "安心しろ、\n今のところ、すべては私の手の内だ。",
  ui_story_5031_50311401_16_dialog_content = "忘れるな――何が聞こえても、\n中に入って来てはならん！",
  ui_story_5031_50311401_17_dialog_content = "…はい。",
  ui_story_5031_50311401_18_dialog_content = "くれぐれもお気を付けください…",
  ui_story_5031_50311401_19_dialog_content = "エルビス！",
  ui_story_5031_50311401_20_dialog_content = "おや？レインボーとシエルではなく、\nカレン殿下とそのご友人と一緒とは。",
  ui_story_5031_50311401_21_dialog_content = "まあ、構わない。想定より遅かっただけのことだ。",
  ui_story_5031_50311401_22_dialog_content = "準備も整ったというのに、お前たちが一向に現われない。\n衛兵程度に手こずっているのかと心配していたところだ。",
  ui_story_5031_50311401_23_dialog_content = "まるで…私たちを待っていたみたいね？",
  ui_story_5031_50311401_24_dialog_content = "パトの姿もない…何を企んでいる…？",
  ui_story_5031_50311401_25_dialog_content = "とにかく、皆、気を付けて。",
  ui_story_5031_50311401_26_dialog_content = "そうね。",
  ui_story_5031_50311401_27_dialog_content = "あの人のすぐ近くにあるのが…「エネルギーコア」？",
  ui_story_5031_50311401_28_dialog_content = "おそらくそうだね。\nとても強い…普通じゃないエネルギーを感じる。",
  ui_story_5031_50311401_29_dialog_content = "でも、こんなに巨大な「エネルギーコア」を\nどうやって持ち出すつもり？",
  ui_story_5031_50311401_30_dialog_content = "エルビス、まずは話を聞いてください。",
  ui_story_5031_50311401_31_dialog_content = "あなたが「エネルギーコア」の力で\n何をしようとしているかは知りません。",
  ui_story_5031_50311401_32_dialog_content = "しかし、最終的な目的が何かは分かっています。\nハーバーシティの人々を「モドリー失調症」から救いたいのでしょう？",
  ui_story_5031_50311401_33_dialog_content = "ですが今、あなたがしているのは、\nハーバーシティに危険をもたらすことです。",
  ui_story_5031_50311401_34_dialog_content = "「エネルギーコア」の稼働に異常が生じれば…",
  ui_story_5031_50311401_35_dialog_content = "「守護者」を目覚めさせてしまう。",
  ui_story_5031_50311401_36_dialog_content = "…",
  ui_story_5031_50311401_37_dialog_content = "それも知っていたのですか？",
  ui_story_5031_50311401_38_dialog_content = "この大陸のありとあらゆる典籍を調べれば、\n必要とする情報はいくらでも、どこかにある。",
  ui_story_5031_50311401_39_dialog_content = "機械兵器――「コアの守護者」。",
  ui_story_5031_50311401_40_dialog_content = "旧文明の産物で、小さな都市1つなら壊滅させるに足る。",
  ui_story_5031_50311401_41_dialog_content = "「エネルギーコア」に何かが起これば、\n「コアの守護者」が目覚める。",
  ui_story_5031_50311401_42_dialog_content = "むやみに操作すれば、「コアの守護者」の攻撃を受け、\n「エネルギーコア」が自壊してしまう可能性もある。",
  ui_story_5031_50311401_43_dialog_content = "だからこそ、お前たち「真理結社」はずっと\n「エネルギーコア」を我がものにできなかった、そうだろう？",
  ui_story_5031_50311401_44_dialog_content = "…",
  ui_story_5031_50311401_45_dialog_content = "し、「真理結社」？",
  ui_story_5031_50311401_46_dialog_content = "ジェノ、まさか「真理結社」のメンバーだったの！？",
  ui_story_5031_50311401_47_dialog_content = "…話せば長くなりますが、僕のエネルギーコアに関する知識は、\n確かに真理結社から得たものです。しかし、それは重要ではありません。",
  ui_story_5031_50311401_48_dialog_content = "ジェノと「真理結社」の関係は、\nひとまず置いておきましょう。",
  ui_story_5031_50311401_49_dialog_content = "エルビス、そこまで分かっているのなら、\nなぜハーバーシティの人々を危険にさらすまねを？",
  ui_story_5031_50311401_50_dialog_content = "「ハーバーシティの人々を危険にさらす」？",
  ui_story_5031_50311401_51_dialog_content = "いいえ、カレン殿下…私は優雅な暮らしにおぼれた、\n白夜城元老院の貴族どもとは違います。",
  ui_story_5031_50311401_52_dialog_content = "民の命を危険な賭けに巻き込むようなことはしません。",
  ui_story_5031_50311401_53_dialog_content = "こうしているのはもちろん、\n考えがあってのことです。",
  ui_story_5031_50311401_54_dialog_content = "しかし、それを知る機会は訪れないでしょう。",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>ゴゴゴ――</color>",
  ui_story_5031_50311401_56_dialog_content = "な、なんの音！？うるさい！！",
  ui_story_5031_50311401_57_dialog_content = "くっ…エルビス、何をしたの？",
  ui_story_5031_50311401_58_dialog_content = "ゲストがそろったのだ。\n私の計画を始めるとしよう。",
  ui_story_5031_50311401_59_dialog_content = "カレン殿下、あなたの人柄と品格は尊敬しておりますが、\n私はハーバーシティの未来のためなら、どのようなことでもするのです。",
  ui_story_5031_50311401_60_dialog_content = "恨むのなら、恨んでくださって結構。",
  ui_story_5031_50311401_61_dialog_content = "しかし、封印がすでに揺らぎ始めたからには、\nどうあろうと、私はハーバーシティを救わねばなりません。",
  ui_story_5031_50311401_62_dialog_content = "見て、杖の宝石が…光りだしたわ！",
  ui_story_5031_50311401_63_dialog_content = "…あの宝石は…",
  ui_story_5031_50311401_64_dialog_content = "「エネルギーコア」から\nエネルギーを吸収してる！？",
  ui_story_5031_50311401_65_dialog_content = "おや？さすがは空の末裔ですね。\nそんなことまで感知できるのですか。",
  ui_story_5031_50311401_66_dialog_content = "これではますます、\n生きて帰すわけにはいかなくなりました。",
  ui_story_5031_50311401_67_dialog_content = "まぁ、最初からそのつもりでしたがね…",
  ui_story_5031_50311401_68_dialog_content = "「…コアの状態異常を検知」",
  ui_story_5031_50311401_69_dialog_content = "「自動防衛システム起動。\nシステムチェック中…」",
  ui_story_5031_50311401_70_dialog_content = "あ、大きなキューブに吊りさがってた\n大きなロボットが動き出した！",
  ui_story_5031_50311401_71_dialog_content = "大変なことになりました…\n最悪の状況です。",
  ui_story_5031_50311401_72_dialog_content = "あれが「コアの守護者」なのです。\n間もなく目覚めてしまいます…",
  ui_story_5031_50311401_73_dialog_content = "皆さん、お気を付けください。",
  ui_story_5031_50311401_74_dialog_content = "「エネルギータイプ識別：…光力」",
  ui_story_5031_50311401_75_dialog_content = "「システム判断：…敵対」",
  ui_story_5031_50311401_76_dialog_content = "「結果：攻撃モード起動」",
  ui_story_5031_50311401_77_dialog_content = "守護者のエネルギーがどんどん強くなってる！",
  ui_story_5031_50311401_78_dialog_content = "フィア、早く、後ろに隠れて！",
  ui_story_5031_50311401_79_dialog_content = "う…うん！",
  ui_story_5031_50311402_1_dialog_content = "バイス、ジェノ、私は左後方から攻撃をしかける。",
  ui_story_5031_50311402_2_dialog_content = "あなたたちは「守護者」の進行を抑えて！",
  ui_story_5031_50311402_3_dialog_content = "分かったわ！",
  ui_story_5031_50311402_4_dialog_content = "バイス、気を付けて！\nあいつの右腕にエネルギーが集中してる！",
  ui_story_5031_50311402_5_dialog_content = "攻撃が来るよ！",
  ui_story_5031_50311402_6_dialog_content = "了解！",
  ui_story_5031_50311402_7_dialog_content = "アイスブロッサム！",
  ui_story_5031_50311402_8_dialog_content = "「機体に被弾…」",
  ui_story_5031_50311402_9_dialog_content = "「損傷レベルのチェックを開始…」",
  ui_story_5031_50311402_10_dialog_content = "わ！やった！動かなくなった！",
  ui_story_5031_50311402_11_dialog_content = "カレンお姉ちゃん、カッコいい！",
  ui_story_5031_50311402_12_dialog_content = "いや、違う…ロボット内部のエネルギーは、\nまだ普通に動いてる！",
  ui_story_5031_50311402_13_dialog_content = "あなたたちは実に強い。\n私の予想を超えていました。",
  ui_story_5031_50311402_14_dialog_content = "空の末裔の能力はかねてよりうかがっていましたが、\n実際に目にすると、やはり感嘆せざるを得ませんね。",
  ui_story_5031_50311402_15_dialog_content = "しかし…残念です。",
  ui_story_5031_50311402_16_dialog_content = "いくら努力しようと、\nあなたたちの力では勝ち目はありませんよ。",
  ui_story_5031_50311402_17_dialog_content = "「チェック完了。重大な損傷なし」",
  ui_story_5031_50311402_18_dialog_content = "「敵の攻撃力情報を更新、出力を調整」",
  ui_story_5031_50311402_19_dialog_content = "こ、これは？",
  ui_story_5031_50311402_20_dialog_content = "カレン！大量のエネルギーが\nロボットの胸元に集まってる！避けて！",
  ui_story_5031_50311402_21_dialog_content = "うっ！",
  ui_story_5031_50311402_22_dialog_content = "危なかったわ…",
  ui_story_5031_50311402_23_dialog_content = "カレン、大丈夫！？",
  ui_story_5031_50311402_24_dialog_content = "大丈夫。PlayerNameのおかげね。\nただのかすり傷よ、心配無用。",
  ui_story_5031_50311402_25_dialog_content = "それならよかった…\nとんでもないエネルギーだったから…",
  ui_story_5031_50311402_26_dialog_content = "部屋が半分溶けちゃったわ…",
  ui_story_5031_50311402_27_dialog_content = "これが旧文明の兵器の力…\n実に恐ろしいわね。",
  ui_story_5031_50311402_28_dialog_content = "皆、まともに戦わないようにして。\nまずは弱点を探すのよ。",
  ui_story_5031_50311402_29_dialog_content = "ええ、カレンも気を付けて。",
  ui_story_5031_50311402_30_dialog_content = "ただ、そう言えば…おかしいわよね？",
  ui_story_5031_50311402_31_dialog_content = "何が？",
  ui_story_5031_50311402_32_dialog_content = "なんで私たちだけ狙われてるの？",
  ui_story_5031_50311402_33_dialog_content = "エネルギーコアの近くに立っているのはエルビスだし、\n力を吸い取っているのも、エルビスでしょ。",
  ui_story_5031_50311402_34_dialog_content = "そう言われてみれば、そうね。",
  ui_story_5031_50311402_35_dialog_content = "それは「コアの守護者」が…",
  ui_story_5031_50311402_36_dialog_content = "…",
  ui_story_5031_50311402_37_dialog_content = "理由を知ってるの？",
  ui_story_5031_50311402_38_dialog_content = "いえ、何でもありません。",
  ui_story_5031_50311402_39_dialog_content = "だったら、何を言いかけたの！？",
  ui_story_5031_50311402_40_dialog_content = "今さら、私の気持ちなど考えてどうする？",
  ui_story_5031_50311402_41_dialog_content = "お前はまったく変わっていないな、ジェノ。",
  ui_story_5031_50311402_42_dialog_content = "構わない、もう慣れている。\n教えてやるといい。",
  ui_story_5031_50311402_43_dialog_content = "エルビス…",
  ui_story_5031_50311402_44_dialog_content = "「コアの守護者」は光力で敵を判断するのだと、\n教えてやらないのか？",
  ui_story_5031_50311402_45_dialog_content = "つまり、光力をほぼすべて奪われてしまった私は、\nこいつにとって…",
  ui_story_5031_50311402_46_dialog_content = "「死人」同然の存在なのだと。",
  ui_story_5031_50311402_47_dialog_content = "「光力を奪われた」？",
  ui_story_5031_50311402_48_dialog_content = "確かに、エルビスからは、\nほとんど光力を感じない…",
  ui_story_5031_50311402_49_dialog_content = "僕はずっと病気のせいだと思ってたけど…",
  ui_story_5031_50311402_50_dialog_content = "原因と結果が逆です。\n光力の喪失が症状を引き起こしているのです。",
  ui_story_5031_50311402_51_dialog_content = "「モドリー失調症」とは、体内の光力を長期間にわたり吸い取られ…\n光力欠乏症を引き起こす病気なのです。",
  ui_story_5031_50311402_52_dialog_content = "この病にかかった光霊は永遠に光力を抜き取られる\n苦痛に耐えねばならず、重症の場合には…",
  ui_story_5031_50311402_53_dialog_content = "ならば、「エネルギーコア」の光力を手に入れれば、\n「モドリー失調症」を治せるということ？",
  ui_story_5031_50311402_54_dialog_content = "具体的な計画は知りませんが、\nエルビスはおそらくそのつもりでしょう。",
  ui_story_5031_50311402_55_dialog_content = "しかし…エルビス、聞いてください。",
  ui_story_5031_50311402_56_dialog_content = "「エネルギーコア」を手に入れたとしても、\n「コアの守護者」をコントロールすることはできません。",
  ui_story_5031_50311402_57_dialog_content = "僕たちが倒れた後には、\n守護者の矛先はあなたとハーバーシティに向くでしょう。",
  ui_story_5031_50311402_58_dialog_content = "きっと他にも方法があるはずです。\n一緒に…",
  ui_story_5031_50311402_59_dialog_content = "ほかに方法はない、ジェノ。",
  ui_story_5031_50311402_60_dialog_content = "この病気のために初めて民を失ったその日から、\nずっと解決方法を探してきた。",
  ui_story_5031_50311402_61_dialog_content = "この数年で、可能性のある方法は全て試してきた。\n成功する希望がどれほどわずかであろうと、あきらめたことはなかった。",
  ui_story_5031_50311402_62_dialog_content = "だが、残ったのは、たび重なる失望と、\n日に日に力を失う、この身体だけ…",
  ui_story_5031_50311402_63_dialog_content = "私は必ずこの手で成し遂げなければならない。\nもう時間がないのだ。",
  ui_story_5031_50311402_64_dialog_content = "ですが…",
  ui_story_5031_50311402_65_dialog_content = "おしゃべりしてる場合じゃないよ！\n「コアの守護者」がそっちに行ってる！",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>ドカン――</color>",
  ui_story_5031_50311402_67_dialog_content = "ジェノ！",
  ui_story_5031_50311402_68_dialog_content = "ゲホッ…",
  ui_story_5031_50311402_69_dialog_content = "大丈夫です…",
  ui_story_5031_50311402_70_dialog_content = "よかった、ビックリしたわ…",
  ui_story_5031_50311402_71_dialog_content = "エルビスのヒキョー者！",
  ui_story_5031_50311402_72_dialog_content = "おしゃべりでジェノ団長の\n注意をそらせたね！",
  ui_story_5031_50311402_73_dialog_content = "それは誤解というものだ。",
  ui_story_5031_50311402_74_dialog_content = "不本意ではあるが、\n私にはまだ、君たちが必要だ…",
  ui_story_5031_50311402_75_dialog_content = "「エネルギーコア」の力を吸収している間、\n「コアの守護者」を引き付けさせたいと言う事ね。",
  ui_story_5031_50311402_76_dialog_content = "カレン殿下、さすがです。",
  ui_story_5031_50311402_77_dialog_content = "ハーバーシティの民を案じてくださったことに免じて、\n「コアの守護者」のことを少し、お話して差し上げましょう。",
  ui_story_5031_50311402_78_dialog_content = "「真理結社」と私との違いは、\n私が彼らにないものを持っていることです。",
  ui_story_5031_50311402_79_dialog_content = "私は自身の血統をもってエネルギーコアと契約を結び、\nその力を自らのために使うことができる。",
  ui_story_5031_50311402_80_dialog_content = "エネルギーコアの吸収が終われば、\nコアの守護者は私の命令を聞くようになるでしょう。",
  ui_story_5031_50311402_81_dialog_content = "あなたたちは安心してこの船と共に、海の底でお眠りください。\n私の民を案ずるには及びません。",
  ui_story_5031_50311402_82_dialog_content = "エルビス…どうしても私たちの命を奪うつもりね。",
  ui_story_5031_50311402_83_dialog_content = "申し訳ございません。ですが、私も元老院の貴族どもに\nこのことを知られる危険を冒すわけにはいかないのです。",
  ui_story_5031_50311402_84_dialog_content = "…ならばもう、話すことは無い。",
  ui_story_5031_50311402_85_dialog_content = "出発点がたとえ善意であろうと、\n私の友人を傷つけることは許さない。",
  ui_story_5031_50311402_86_dialog_content = "ジェノ、あなたの召喚する幻影には、\nあなたの光力が宿っている。そうね？",
  ui_story_5031_50311402_87_dialog_content = "ええ。",
  ui_story_5031_50311402_88_dialog_content = "さきほどの衛兵たちと同じレベルの幻影を、\nどれほど生み出せる？",
  ui_story_5031_50311402_89_dialog_content = "同時に操るのなら、およそ10体といったところです。",
  ui_story_5031_50311402_90_dialog_content = "カレン、何か作戦？",
  ui_story_5031_50311402_91_dialog_content = "バイス、ジェノ、あなたたちは\n守護者を引き付けておいて。",
  ui_story_5031_50311402_92_dialog_content = "何をどうするにも、まず「エネルギーコア」を正常な状態に戻し、\n守護者を再び眠らせることが大前提になる。",
  ui_story_5031_50311402_93_dialog_content = "その後にすることは明確…",
  ui_story_5031_50311402_94_dialog_content = "エルビスを阻止する。",
  ui_story_5031_50311501_1_dialog_content = "速射感知！",
  ui_story_5031_50311501_2_dialog_content = "うまく引き付けられたわ！",
  ui_story_5031_50311501_3_dialog_content = "カレン、今よ！",
  ui_story_5031_50311501_4_dialog_content = "急いでください。これほどの数の幻影は、\n僕でも長くは出せません。",
  ui_story_5031_50311501_5_dialog_content = "分かった、頼んだわ。",
  ui_story_5031_50311501_6_dialog_content = "ゴホッ、ゴホゴホッ…",
  ui_story_5031_50311501_7_dialog_content = "さすがはカレン殿下…",
  ui_story_5031_50311501_8_dialog_content = "ジェノと知り合って1日も経たないというのに、\nやつの能力を使った守護者の足止め策を思いつくとは。",
  ui_story_5031_50311501_9_dialog_content = "戦局を見極める観察力も確かだ。\nそこに空の末裔の能力が加わって…",
  ui_story_5031_50311501_10_dialog_content = "あなたを見くびらずにいて正解でした。",
  ui_story_5031_50311501_11_dialog_content = "うっ！？",
  ui_story_5031_50311501_12_dialog_content = "カレン、どうしたの！？",
  ui_story_5031_50311501_13_dialog_content = "身体に…力が…入らない…",
  ui_story_5031_50311501_14_dialog_content = "力が抜けていく…",
  ui_story_5031_50311501_15_dialog_content = "フィア、ここに隠れて！\n動いちゃダメだよ！",
  ui_story_5031_50311501_16_dialog_content = "PlayerName、そんな風に突っ込んでいったら、\nロボットにやられちゃうよ！",
  ui_story_5031_50311501_17_dialog_content = "…あれ？ロボット、ぜんぜん反応しない？",
  ui_story_5031_50311501_18_dialog_content = "カレン！",
  ui_story_5031_50311501_19_dialog_content = "PlayerName…うっ。",
  ui_story_5031_50311501_20_dialog_content = "（どういうこと？\nカレンの光力が急速に弱まってる…）",
  ui_story_5031_50311501_21_dialog_content = "まずい…",
  ui_story_5031_50311501_22_dialog_content = "<size=45>カレンに何をした！？</size>",
  ui_story_5031_50311501_23_dialog_content = "辛いでしょう？\n光力を急激に吸い取られる感覚は。",
  ui_story_5031_50311501_24_dialog_content = "万が一に備えて、\nカレン殿下には「<color=#FFB400>保険</color>」をかけておいたのです。",
  ui_story_5031_50311501_25_dialog_content = "「保険」？一体いつ…",
  ui_story_5031_50311501_26_dialog_content = "…まさか、このドレスが！？",
  ui_story_5031_50311501_27_dialog_content = "ご明察。",
  ui_story_5031_50311501_28_dialog_content = "あなたたちが船の奥へ入る方法を聞いた時から、\nこのようなことになるだろうと予想していたのです。",
  ui_story_5031_50311501_29_dialog_content = "カレン殿下の着ているドレスには、\n特殊な加工が施されています。",
  ui_story_5031_50311501_30_dialog_content = "「<color=#FFB400>光の糸</color>」が効力を発揮すると、\n着ているものの光力を急激に吸い取るのです。",
  ui_story_5031_50311501_31_dialog_content = "ですから、カレン殿下…光力は使わない方が身のためです。\nそうすれば、少しは楽になりますよ。",
  ui_story_5031_50311501_32_dialog_content = "なんてことを…！",
  ui_story_5031_50311501_33_dialog_content = "ごめんなさい…彼を見くびっていたわ。",
  ui_story_5031_50311501_34_dialog_content = "君のせいじゃない。\nカレン、今は…",
  ui_story_5031_50311501_35_dialog_content = "ジェノさん！危ない！",
  ui_story_5031_50311501_36_dialog_content = "くっ！",
  ui_story_5031_50311501_37_dialog_content = "大丈夫！？",
  ui_story_5031_50311501_38_dialog_content = "腕が…",
  ui_story_5031_50311501_39_dialog_content = "動かなくなってしまったようです…",
  ui_story_5031_50311501_40_dialog_content = "血が出てるわ、動いちゃダメ！",
  ui_story_5031_50311501_41_dialog_content = "「敵の負傷を確認。追撃開始」",
  ui_story_5031_50311501_42_dialog_content = "あっ！バイスお姉ちゃん、\n守護者がそっちに行ってる！",
  ui_story_5031_50311501_43_dialog_content = "しまった…早い！",
  ui_story_5031_50311501_44_dialog_content = "射程が…近すぎるわ、間に合わない！",
  ui_story_5031_50311501_45_dialog_content = "やめろ！…ぐっ…",
  ui_story_5031_50311501_46_dialog_content = "ジェ、ジェノさん！？",
  ui_story_5031_50311501_47_dialog_content = "…",
  ui_story_5031_50311501_48_dialog_content = "気を失ってる…",
  ui_story_5031_50311501_49_dialog_content = "ああああ、どうしよどうしよどうしよ！？",
  ui_story_5031_50311501_50_dialog_content = "あっ…そうだ！\nあたしにはこれがある！",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5031_50311501_52_dialog_content = "「…？」",
  ui_story_5031_50311501_53_dialog_content = "当たり～！師匠からもらった護身用の銃、\n持ってきててよかった！",
  ui_story_5031_50311501_54_dialog_content = "ど、どうだ！デクノボー！！",
  ui_story_5031_50311501_55_dialog_content = "「正体不明の攻撃を被弾。損傷レベル：0」",
  ui_story_5031_50311501_56_dialog_content = "「ターゲットの光力消耗未検知。\n判断：優先的に除去」",
  ui_story_5031_50311501_57_dialog_content = "えええ！？何で急にあたしに向かってくるの！？",
  ui_story_5031_50311501_58_dialog_content = "あ！！",
  ui_story_5031_50311501_59_dialog_content = "フィア！",
  ui_story_5031_50311501_60_dialog_content = "…",
  ui_story_5031_50311501_61_dialog_content = "まずい、このままじゃ本当にやられる…",
  ui_story_5031_50311501_62_dialog_content = "今戦えるのは、僕しかいない。\n僕があせったらダメだ…",
  ui_story_5031_50311501_63_dialog_content = "最優先は、エルビスを阻止すること…\nそうすれば、「コアの守護者」も止められる。",
  ui_story_5031_50311501_64_dialog_content = "…",
  ui_story_5031_50311501_65_dialog_content = "カレン、ここで休んでて。\n光力は使わないでね。",
  ui_story_5031_50311501_66_dialog_content = "PlayerName…何をするつもり？",
  ui_story_5031_50311501_67_dialog_content = "僕がエルビスを止める。",
  ui_story_5031_50311501_68_dialog_content = "啓光の長官たちとサメヤマの「特訓」が、\nやっと役に立つ時が来たよ。",
  ui_story_5031_50311501_69_dialog_content = "でも…",
  ui_story_5031_50311501_70_dialog_content = "安心して、カレン。",
  ui_story_5031_50311501_71_dialog_content = "僕には光力がないけど、\nエルビスだって、病人だ…",
  ui_story_5031_50311501_72_dialog_content = "負けたりしないよ。",
  ui_story_5031_50311501_73_dialog_content = "…気を付けて。",
  ui_story_5031_50311501_74_dialog_content = "英雄らしい立派な発言です。\n胸に刻ませて頂きましたよ。",
  ui_story_5031_50311501_75_dialog_content = "ですが、「病人」はあんまりですね。",
  ui_story_5031_50311501_76_dialog_content = "話はもういい…",
  ui_story_5031_50311501_77_dialog_content = "口を閉じて――",
  ui_story_5031_50311501_78_dialog_content = "僕と戦え！",
  ui_story_5031_50311501_79_dialog_content = "フフ…",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName！危ない！</size>",
  ui_story_5031_50311501_81_dialog_content = "「最高指令によりデフォルト命令を上書き。ターゲット更新」",
  ui_story_5031_50311501_82_dialog_content = "うわああ！！",
  ui_story_5031_50311501_83_dialog_content = "PlayerName！",
  ui_story_5031_50311501_84_dialog_content = "そ、そんな…",
  ui_story_5031_50311501_85_dialog_content = "どうして…",
  ui_story_5031_50311501_86_dialog_content = "惜しかったですね、PlayerName。\nあと少しでした。",
  ui_story_5031_50311501_87_dialog_content = "申し訳ありませんが、\nエネルギーの吸収は終わりました。",
  ui_story_5031_50311501_88_dialog_content = "今や私こそが「コアの守護者」の主です。",
  ui_story_5031_50311501_89_dialog_content = "そうでなければ、あなたのような光力のない存在を\n逃してしまいますからね。",
  ui_story_5031_50311501_90_dialog_content = "「最高指揮権を更新。\nマニュアル操作による戦闘に切り替え」",
  ui_story_5031_50311501_91_dialog_content = "「自動防御システムオフ」",
  ui_story_5031_50311501_92_dialog_content = "（痛い…！）",
  ui_story_5031_50311501_93_dialog_content = "（両足の感覚がない…）",
  ui_story_5031_50311501_94_dialog_content = "まだ動けるのは――",
  ui_story_5031_50311501_95_dialog_content = "バイスさんだけのようですね？",
  ui_story_5031_50311501_96_dialog_content = "やれ！彼女を片付けて、\n次の目的地へ急ぐぞ。",
  ui_story_5031_50311501_97_dialog_content = "「最新の指示を確認、ターゲット変更」",
  ui_story_5031_50311501_98_dialog_content = "（マズい、バイス！）",
  ui_story_5031_50311501_99_dialog_content = "<size=33>バイス…早く逃げて…</size>",
  ui_story_5031_50311501_100_dialog_content = "おや？まだ立ち上がれるのですか？",
  ui_story_5031_50311501_101_dialog_content = "<size=33>え？</size>",
  ui_story_5031_50311501_102_dialog_content = "カレン殿下、その状態でそれほどのエネルギーを爆発させるとは…\nまこと、尊敬に値します。",
  ui_story_5031_50311501_103_dialog_content = "しかし、率直に申し上げて…\nご自身の死期を早めるだけですよ。",
  ui_story_5031_50311501_104_dialog_content = "<size=33>カ、カレン！？</size>",
  ui_story_5031_50311501_105_dialog_content = "全部、私の…",
  ui_story_5031_50311501_106_dialog_content = "カレン殿下？",
  ui_story_5031_50311501_107_dialog_content = "全部…私のせい…",
  ui_story_5031_50311501_108_dialog_content = "ああ、光力が尽きて、\n意識を失いかけているようですね。",
  ui_story_5031_50311501_109_dialog_content = "実に恐ろしい。そのような状態で、\n無意識に仲間を守ろうとなさるとは。",
  ui_story_5031_50311501_110_dialog_content = "「活動しているターゲットを新たに発見。攻撃しますか？」",
  ui_story_5031_50311501_111_dialog_content = "いや、彼女はもはや脅威ではない。",
  ui_story_5031_50311501_112_dialog_content = "<size=45>カレン、動いちゃダメだ…！</size>",
  ui_story_5031_50311501_113_dialog_content = "（うっ、声が出ない）",
  ui_story_5031_50311501_114_dialog_content = "（だったら…）",
  ui_story_5031_50311501_115_option_content = "強制感知！",
  ui_story_5031_50311501_116_dialog_content = "お前の治める街が暗鬼の攻撃を受けたとして…\nお前はなんとする？",
  ui_story_5031_50311501_117_dialog_content = "（あれ？ソルラドさんの声？）",
  ui_story_5031_50311501_118_dialog_content = "（これは…夢？\nカレンが意識を失いかけてるから？）",
  ui_story_5031_50311501_119_dialog_content = "ただちに部隊を組織して、防ぎます。",
  ui_story_5031_50311501_120_dialog_content = "その時、別の暗鬼の一群が\n手薄な場所を狙って攻撃してきたならば？",
  ui_story_5031_50311501_121_dialog_content = "私が待機していた軍を率いて駆け付けます。",
  ui_story_5031_50311501_122_dialog_content = "では、それと同時に暗鬼が地中に掘った道を通り、\n街中に現れたならば？",
  ui_story_5031_50311501_123_dialog_content = "兵士たちに陣を任せ、私が…",
  ui_story_5031_50311501_124_dialog_content = "そこで最初に暗鬼の攻撃を受けた城壁が\n再び危険におちいったならば？",
  ui_story_5031_50311501_125_dialog_content = "…",
  ui_story_5031_50311501_126_dialog_content = "わ、私が暗鬼をすべて倒します。",
  ui_story_5031_50311501_127_dialog_content = "暗鬼をすべて倒しきることなどできぬ。\nそれは余もお前も理解しているはずだ。",
  ui_story_5031_50311501_128_dialog_content = "…",
  ui_story_5031_50311501_129_dialog_content = "優れた君主には、まだまだ足りぬ…",
  ui_story_5031_50311501_130_dialog_content = "白夜城をお前に任せられる日も遠かろう。",
  ui_story_5031_50311501_131_dialog_content = "ち、父上？",
  ui_story_5031_50311501_132_dialog_content = "北境へ送り、ベツレヘムに師事までさせたというのに、\nまったく成長しておらぬ。",
  ui_story_5031_50311501_133_dialog_content = "力が足りぬ。知恵が足りぬ…",
  ui_story_5031_50311501_134_dialog_content = "…だから、ご友人を失うのです。",
  ui_story_5031_50311501_135_dialog_content = "彼らは傷つき、命を落とす――\nすべてあなたのせいですよ、カレン殿下。",
  ui_story_5031_50311501_136_dialog_content = "わ…私は…",
  ui_story_5031_50311501_137_dialog_content = "カレン…あなたを信じて、\n指示に従ったのに…",
  ui_story_5031_50311501_138_dialog_content = "その結果、どうなったと思う？",
  ui_story_5031_50311501_139_dialog_content = "私もPlayerNameもあなたのせいで、\nここで命を落とすことになったのよ。",
  ui_story_5031_50311501_140_dialog_content = "バイス、ごめんなさい…私は…",
  ui_story_5031_50311501_141_dialog_content = "カレン！よく見て！\nあれはバイスじゃない！",
  ui_story_5031_50311501_142_dialog_content = "この声は…",
  ui_story_5031_50311501_143_dialog_content = "PlayerName…？",
  ui_story_5031_50311501_144_dialog_content = "そうだよ、僕だ！",
  ui_story_5031_50311501_145_dialog_content = "ごめん…カレンがずっと心の中でこんな風に苦しんでたなんて、\nまったく考えもしなかった。",
  ui_story_5031_50311501_146_dialog_content = "でも、バイスは絶対にあんなこと言わないよ。\n君の目の前にいるのは幻だ、本物じゃない！",
  ui_story_5031_50311501_147_dialog_content = "また逃げるの？\n責任から逃がれようとするの？",
  ui_story_5031_50311501_148_dialog_content = "実に嘆かわしい。\n口先では他人を守ると言っておきながら、これほど弱いとは。",
  ui_story_5031_50311501_149_dialog_content = "君主とは、お前のような者であってはならないのだ。",
  ui_story_5031_50311501_150_dialog_content = "私は…",
  ui_story_5031_50311501_151_dialog_content = "カレン、聞いて。",
  ui_story_5031_50311501_152_dialog_content = "いつでもお姫様として、\n責任を背負ってる必要はないんだ！",
  ui_story_5031_50311501_153_dialog_content = "僕やバイスの前では、君はカレンなんだ！\nただのカレンなんだよ！",
  ui_story_5031_50311501_154_dialog_content = "えっ？",
  ui_story_5031_50311501_154X1_dialog_content = "カレン、覚えてる？\nバイスが前に言ったこと。",
  ui_story_5031_50311501_154X2_dialog_content = "自分の執着に囚われちゃだめだ！",
  ui_story_5031_50311501_154X3_dialog_content = "私の、執着…",
  ui_story_5031_50311501_154X4_dialog_content = "あの時は、まるで底なしの闇に落ちたみたいで…\n永遠に目を覚まさないかもって、一度は思ったわ。",
  ui_story_5031_50311501_154X5_dialog_content = "少しでも気を抜くと自分を見失ってしまう気がして…\n今までの自分を一生懸命思い出して、考え続けたの。",
  ui_story_5031_50311501_154X6_dialog_content = "それから、不思議な光景をたくさん見たの。\nまるで自分がそこにいるみたいな感覚…",
  ui_story_5031_50311501_154X7_dialog_content = "現実そっくりの幻覚に、\n試されてるみたいだったわ。",
  ui_story_5031_50311501_154X8_dialog_content = "でも、私は意識の海の中で、\n一筋の光をつかむことができたから、最後までがんばることができたの。",
  ui_story_5031_50311501_154X9_dialog_content = "「一筋の光」…この間もそう言っていたわね。\n具体的には何なのかしら？",
  ui_story_5031_50311501_154X10_dialog_content = "あの時は…思い出したの。\nあなたと、それからPlayerNameと、一緒に経験したいろんなこと。",
  ui_story_5031_50311501_154X11_dialog_content = "そうしたら、知らず知らずのうちに、\n心が落ち着いていたの。",
  ui_story_5031_50311501_154X12_dialog_content = "そうだよ、カレン。あきらめちゃダメだ。\n自分を見失っちゃダメだ！",
  ui_story_5031_50311501_155_dialog_content = "僕たちは、一緒に戦って、\n行動してきた仲間なんだよ。",
  ui_story_5031_50311501_156_dialog_content = "お互いに背中を任せられる、\n戦友なんだ！",
  ui_story_5031_50311501_157_dialog_content = "どんな困難の前でも、僕たちは君が「君主」として\n責任を果たすことなんて、望んじゃいない！！",
  ui_story_5031_50311501_158_dialog_content = "1人で全部抱え込んで、\n僕たちを守ろうとしなくていいんだよ！",
  ui_story_5031_50311501_159_dialog_content = "一緒に行動して、一緒に方法を考えて、\n一緒に立ち向かうべきなんだ！",
  ui_story_5031_50311501_160_dialog_content = "PlayerName…",
  ui_story_5031_50311501_161_dialog_content = "何が起こっても、僕とバイスは絶対に――\n君を責めるなんてことしない！",
  ui_story_5031_50311501_162_dialog_content = "だから、しっかりして、カレン！\n目の前の幻に惑わされないで！！",
  ui_story_5031_50311501_163_dialog_content = "本物のバイスは、僕たちを守るためにまだ戦ってる。\nあきらめてない！！",
  ui_story_5031_50311501_164_dialog_content = "バイスには君が必要なんだ！",
  ui_story_5031_50311501_165_dialog_content = "…",
  ui_story_5031_50311501_166_dialog_content = "あなたの言う通りね、PlayerName。",
  ui_story_5031_50311501_167_dialog_content = "仲間がまだ戦っているなら、\n悩んだり悔んだりしている場合ではないわ…",
  ui_story_5031_50311501_168_dialog_content = "ならば、お前は自らの犯した罪から\n目をそらすのだな？",
  ui_story_5031_50311501_169_dialog_content = "お前が敵を軽んじ、\n己の能力が足りぬがゆえに――",
  ui_story_5031_50311501_170_dialog_content = "今の結果を招いたのよ。",
  ui_story_5031_50311501_171_dialog_content = "その通りよ。でも私はもう、\n自分が正しかったかどうかなんてことに、こだわらない。",
  ui_story_5031_50311501_172_dialog_content = "…",
  ui_story_5031_50311501_173_dialog_content = "そんなことに意味などないから。\n過ちを犯したのなら…",
  ui_story_5031_50311501_174_dialog_content = "全力でそれを正す。",
  ui_story_5031_50311501_175_dialog_content = "それがあなたの考える「王道」だというのなら――",
  ui_story_5031_50311501_176_dialog_content = "その信念を、貫けるといいわね。",
  ui_story_5031_50311501_176X1_dialog_content = "ええ、必ず。",
  ui_story_5031_50311501_176X2_dialog_content = "だって、私は…",
  ui_story_5031_50311501_176X3_dialog_content = "私の光を見つけたから。",
  ui_story_5031_50311501_177_dialog_content = "あっ、景色が――",
  ui_story_5031_50311501_178_dialog_content = "バイス、ごめんなさい。\n待たせたわね。",
  ui_story_5031_50311501_179_dialog_content = "カレン！",
  ui_story_5031_50311501_180_dialog_content = "「警告：強力な光力を検知。危険レベル高と判断」",
  ui_story_5031_50311501_181_dialog_content = "「ただちにターゲットの排除を実行」",
  ui_story_5031_50311501_182_dialog_content = "光よ、闇を照らせ！",
  ui_story_5031_50311501_183_dialog_content = "そ、そんなはずが…",
  ui_story_5031_50311501_184_dialog_content = "「<color=#FFB400>光の糸</color>」が、\nまだ光力を吸い続けているはずだ！",
  ui_story_5031_50311501_185_dialog_content = "カレンから…光力があふれてきてる？",
  ui_story_5031_50311501_186_dialog_content = "どういうこと…？",
  ui_story_5031_50311501_187_dialog_content = "意味なく自分を疑って、あせっても…\n考えが乱れるだけ。",
  ui_story_5031_50311501_188_dialog_content = "戦局はほんの一瞬で変わる。どんな身分であろうと、\n目を向けるべきは目の前の戦場。心の中の恐怖に囚われるべきではない…",
  ui_story_5031_50311501_189_dialog_content = "バイス、立ち向かいましょう。一緒に。",
  ui_story_5031_50311501_190_dialog_content = "カレン…身体は大丈夫なの？",
  ui_story_5031_50311501_191_dialog_content = "なぜだか分からないけれど、\n今、私の身体からは新しい力が湧いているの。",
  ui_story_5031_50311501_192_dialog_content = "ただ、どんな理由であろうと、\n今の私がするべきことはたった1つ――",
  ui_story_5031_50311501_193_dialog_content = "あなたと一緒に、目の前の敵を倒すこと。",
  ui_story_5031_50311501_194_dialog_content = "そうね！",
  ui_story_5031_50311501_195_dialog_content = "「警告：強力な光力を検知。危険レベル極高と判断」",
  ui_story_5031_50311501_196_dialog_content = "「決戦モード起動」",
  ui_story_5031_50311502_1_dialog_content = "「警告…機体損傷レベルが70％を超過」",
  ui_story_5031_50311502_2_dialog_content = "「右腕の接続停止。自動修復不能。」",
  ui_story_5031_50311502_3_dialog_content = "バイス、大丈夫？",
  ui_story_5031_50311502_4_dialog_content = "ええ、大丈夫よ。遠距離からけん制してただけだから、\nそんなに力は使ってないわ！",
  ui_story_5031_50311502_5_dialog_content = "それならよかった。\n次は右に集中攻撃をしかけましょう。",
  ui_story_5031_50311502_6_dialog_content = "あいつの右腕はもう使えないわ。\n攻撃にも防御にも影響があるはず。",
  ui_story_5031_50311502_7_dialog_content = "分かったわ！",
  ui_story_5031_50311502_8_dialog_content = "カレン殿下、本当に私を驚かせてくださいますね。",
  ui_story_5031_50311502_9_dialog_content = "このような立場ですが、\nやはり尊敬の念を禁じ得ません。",
  ui_story_5031_50311502_10_dialog_content = "ですが、私も失敗するわけにはいかないのです。",
  ui_story_5031_50311502_11_dialog_content = "先に失礼することをお許しください。皆さんの美しいお芝居を\nのん気に楽しんではいられないのです。",
  ui_story_5031_50311502_12_dialog_content = "エルビス、待ちなさい！",
  ui_story_5031_50311502_13_dialog_content = "あいつらを止めろ。",
  ui_story_5031_50311502_14_dialog_content = "バイス、危ない！\n守護者に背中を向けてはダメよ！",
  ui_story_5031_50311502_15_dialog_content = "うっ！？",
  ui_story_5031_50311502_16_dialog_content = "…",
  ui_story_5031_50311502_17_dialog_content = "…まずいわ、逃げられた…",
  ui_story_5031_50311502_18_dialog_content = "構わないわ。\nエルビスのことは船を出てから考えましょう。",
  ui_story_5031_50311502_19_dialog_content = "それもそうね…",
  ui_story_5031_50311502_20_dialog_content = "今はまず「守護者」の問題を片付けないと。",
  ui_story_5031_50311502_21_dialog_content = "それなら…あら？",
  ui_story_5031_50311502_22_dialog_content = "どうしたの、カレン？",
  ui_story_5031_50311502_23_dialog_content = "（カレンの光力が急に強くなった？）",
  ui_story_5031_50311502_24_dialog_content = "ドレスが光力を吸収しなくなったようね。",
  ui_story_5031_50311502_25_dialog_content = "エルビスが離れたからかしら。",
  ui_story_5031_50311502_26_dialog_content = "そういえば、今までは着ていても\n何ともなかったものね。",
  ui_story_5031_50311502_27_dialog_content = "ってことは、エルビスが操って初めて、\n光力を吸い取る機能が働く？",
  ui_story_5031_50311502_28_dialog_content = "そういうことなら、\nもう様子を見る必要はないわね。",
  ui_story_5031_50311502_29_dialog_content = "敵味方の区別もつかない愚かな機械が船を壊してしまう前に、\n私たちが引導を渡してやりましょう。",
  ui_story_5031_50311502_30_dialog_content = "ええ！ジェノが目覚めたら、\nお礼を言ってもらわなきゃね。",
  ui_story_5031_50311502_31_dialog_content = "お前たち、謀反（むほん）でも起こすつもりか！？",
  ui_story_5031_50311502_32_dialog_content = "エルビス様は幼なじみである団長とお話しになっています。\nどなたであっても、船に入れるわけには参りません。",
  ui_story_5031_50311502_33_dialog_content = "私たちも命令を受けているのです。\nご理解頂きたい。",
  ui_story_5031_50311502_34_dialog_content = "お前たちの様子からすると、\nタダの番犬ではなさそうだな。",
  ui_story_5031_50311502_35_dialog_content = "それに、先ほどからの\n船の中の爆発音…",
  ui_story_5031_50311502_36_dialog_content = "「幼なじみ」と言ったか？\nお互い恨みでもあるのではないか？",
  ui_story_5031_50311502_37_dialog_content = "お前たち、自分のずいぶんやせ細った領主様が心配ではないのか？\nあの団長に軽く殴られただけでも持たないだろう？",
  ui_story_5031_50311502_38_dialog_content = "…お引き取り下さい。",
  ui_story_5031_50311502_39_dialog_content = "ほう？どういう意味だ？\n私に刃を向けようというのか？",
  ui_story_5031_50311502_40_dialog_content = "覚悟はできているのだろうな？\n私は事の一切をありのままに報告するぞ…",
  ui_story_5031_50311502_41_dialog_content = "パト、無礼はやめなさい。",
  ui_story_5031_50311502_42_dialog_content = "エルビス様！",
  ui_story_5031_50311502_43_dialog_content = "おやおや、これはエルビス閣下。\n積もる話は終わったのですかな？",
  ui_story_5031_50311502_44_dialog_content = "マシュー様、お待たせして申し訳ございません。\n旧友と大事な話がありましてね。",
  ui_story_5031_50311502_45_dialog_content = "パトたちは命令に従っただけです。\nどうかお責めにならないよう、お願い致します。",
  ui_story_5031_50311502_46_dialog_content = "ならば、もう船の様子を見ても？",
  ui_story_5031_50311502_47_dialog_content = "どうぞご自由に。",
  ui_story_5031_50311502_48_dialog_content = "<size=33>エルビス様、よろしいのですか？</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>構わない。もうすぐ爆発する。</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>それより、急いで向かわねばならん所が…</size>",
  ui_story_5031_50311502_51_dialog_content = "ああ、そうでした、エルビス閣下。",
  ui_story_5031_50311502_52_dialog_content = "…何でしょう？",
  ui_story_5031_50311502_53_dialog_content = "お尋ねするが、\n船の上でカレン殿下をお見かけになりましたかな？",
  ui_story_5031_50311502_54_dialog_content = "いいえ。\n船の中にいらっしゃるのですか？",
  ui_story_5031_50311502_55_dialog_content = "おかしいですな。祝宴が終わってから\nここでお待ちしていたのですが、殿下のお姿は見えませんでした。",
  ui_story_5031_50311502_56_dialog_content = "船も下りず、あなたがたにも会わず…\n殿下は船に残って何をされているのやら？",
  ui_story_5031_50311502_57_dialog_content = "船上で新しく知り合ったご友人と\nお別れでもなさっているのでしょう。",
  ui_story_5031_50311502_58_dialog_content = "1日中お祭り騒ぎでしたからね。\n仲良くなったことでしょう。",
  ui_story_5031_50311502_59_dialog_content = "お目付け役と言えば聞こえはいいですが、\n今日は一日中、おケガでもしないかと気が気でなりませんでした。",
  ui_story_5031_50311502_60_dialog_content = "ですから、分かっておるのです。\n殿下はサーカス団の方と、そう深くは関わっておらぬはず。",
  ui_story_5031_50311502_61_dialog_content = "ですが、バイスさんとシエルさんは元々お知り合いでしょう。",
  ui_story_5031_50311502_62_dialog_content = "PlayerNameさんもレインボーさんと\n楽しそうにお話しされていましたし…",
  ui_story_5031_50311502_63_dialog_content = "お話をさえぎって申し訳ありませんが、\nエルビス閣下。",
  ui_story_5031_50311502_64_dialog_content = "…はい？",
  ui_story_5031_50311502_65_dialog_content = "私は先ほど、殿下以外のことは口にしておりません。",
  ui_story_5031_50311502_66_dialog_content = "なぜお会いになっていないのに、\n殿下がそやつらと一緒にいると、断定されたのです？",
  ui_story_5031_50311502_67_dialog_content = "…",
  ui_story_5031_50311502_68_dialog_content = "あの4人は仲がよろしいのでは？\nいつも一緒に行動していらっしゃいました。",
  ui_story_5031_50311502_69_dialog_content = "あなたも今日初めて会ったのでしょう？\nなぜ仲がいいと分かるのです？",
  ui_story_5031_50311502_70_dialog_content = "私とあのぎっちり着込んだ相棒も…まぁ、仲は良い。\nあいつは今ここにおりません…",
  ui_story_5031_50311502_71_dialog_content = "…",
  ui_story_5031_50311502_72_dialog_content = "パト。",
  ui_story_5031_50311502_73_dialog_content = "はっ。",
  ui_story_5031_50311502_74_dialog_content = "フン、真実を見抜かれ、\n口止めをしようという訳ですかな？",
  ui_story_5031_50311502_75_dialog_content = "その陰湿さ、\nなかなか面白い。",
  ui_story_5031_50311502_76_dialog_content = "ご存じないかもしれませんが、\n我らの城主様は冷たく見えて、実は娘を溺愛しておられる。",
  ui_story_5031_50311502_77_dialog_content = "そのお目付けを仰せつかった我々が、\n簡単にやられるとでもお思いですかな？",
  ui_story_5031_50311502_78_dialog_content = "ローウェイ！出番だ！",
  ui_story_5031_50311502_79_dialog_content = "何だ？",
  ui_story_5031_50311502_80_dialog_content = "…マシュー、無駄口が多い。",
  ui_story_5031_50311502_81_dialog_content = "チッ、うるさい！",
  ui_story_5031_50311502_82_dialog_content = "お2人だけですか？",
  ui_story_5031_50311502_83_dialog_content = "たった2人で、私の衛兵たちとやり合うおつもりで？",
  ui_story_5031_50311502_84_dialog_content = "違うな、1人だ。",
  ui_story_5031_50311502_85_dialog_content = "ここはお前に任せたぞ、ローウェイ。\n私は殿下を助けにいく。",
  ui_story_5031_50311502_86_dialog_content = "…",
  ui_story_5031_50311502_87_dialog_content = "必要ないわ…",
  ui_story_5031_50311502_88_dialog_content = "この声は…",
  ui_story_5031_50311502_89_dialog_content = "ど…どうなっている！？",
  ui_story_5031_50311502_90_dialog_content = "エルビスの引き留め、ご苦労だったわ。",
  ui_story_5031_50311502_91_dialog_content = "ずいぶん手間がはぶけた。",
  ui_story_5031_50311502_92_dialog_content = "カレン殿下！ご無事で何よりです。",
  ui_story_5031_50311502_93_dialog_content = "そ、そんなはずは！？",
  ui_story_5031_50311502_94_dialog_content = "「コアの守護者」はどうなった！？\nなぜ船がまだ爆発しない？",
  ui_story_5031_50311502_95_dialog_content = "カレンの全力の一撃で、\n今はただのスクラップよ。",
  ui_story_5031_50311502_96_dialog_content = "あ～、あの「コアの守護者」の構造、\n参考にできそうだったな～！",
  ui_story_5031_50311502_97_dialog_content = "あたしたちが駆け付けた時にはもう\n動かなくなっちゃってて、残念。",
  ui_story_5031_50311502_98_dialog_content = "大丈夫だよ、スクラップでも、\n研究価値は十分あるから。",
  ui_story_5031_50311502_99_dialog_content = "それもそうだね～。",
  ui_story_5031_50311502_100_dialog_content = "なぜだ！？「光の糸」で抑え込んでいたはずだ。\nどこからそんな力が出る！？",
  ui_story_5031_50311502_101_dialog_content = "…いや、おかしい。\n「光の糸」の吸収が止まっている…？",
  ui_story_5031_50311502_102_dialog_content = "「光の糸」、あなたが操っていたんじゃないの？",
  ui_story_5031_50311502_103_dialog_content = "まさか…吸収量の限界を超えたというのか！？",
  ui_story_5031_50311502_104_dialog_content = "そんなはずはない！\n光霊2、3人分の光力を吸い取れるはずだ！",
  ui_story_5031_50311502_105_dialog_content = "何が原因かは、重要ではないわ。",
  ui_story_5031_50311502_106_dialog_content = "重要なのは、エルビス。\nお前の計画が失敗したこと。",
  ui_story_5031_50311502_107_dialog_content = "抵抗は止めなさい。逃がしはしないわ。",
  ui_story_5031_50311502_108_dialog_content = "いや、そうはいかない…私は失敗できない！\n失敗は許されないのだ！",
  ui_story_5031_50311502_109_dialog_content = "「<color=#FFB400>封印</color>」が今にも…",
  ui_story_5031_50311502_110_dialog_content = "…パト！",
  ui_story_5031_50311502_111_dialog_content = "はっ！",
  ui_story_5031_50311502_112_dialog_content = "つまらん抵抗はよせ。",
  ui_story_5031_50311502_113_dialog_content = "…チッ…",
  ui_story_5031_50311502_114_dialog_content = "エルビス様、今です！",
  ui_story_5031_50311502_115_dialog_content = "これだけの人数がいるのだ。\nお前を逃がしでもしたら、とんだ笑い草だ。",
  ui_story_5031_50311502_116_dialog_content = "うっ！",
  ui_story_5031_50311502_117_dialog_content = "…おい、冗談だろう？軽く触っただけだぞ。\nそんな簡単に…",
  ui_story_5031_50311502_118_dialog_content = "弱っているにも程があるだろう？",
  ui_story_5031_50311502_119_dialog_content = "エルビス様！",
  ui_story_5031_50311502_120_dialog_content = "お前の相手はここだ。",
  ui_story_5031_50311502_121_dialog_content = "チッ…！",
  ui_story_5031_50311502_122_dialog_content = "1人も逃がさない。",
  ui_story_5031_50311601_1_dialog_content = "レインボー、シエルちゃんは任せたよ！",
  ui_story_5031_50311601_2_dialog_content = "安心して～。\nシエルはあたしがちゃんと面倒みるから！",
  ui_story_5031_50311601_3_dialog_content = "ファムも一緒にシエル姉の面倒をみる！",
  ui_story_5031_50311601_4_dialog_content = "サプリも！",
  ui_story_5031_50311601_5_dialog_content = "め、メルトもです…",
  ui_story_5031_50311601_6_dialog_content = "わ！すっごく頼もしい！",
  ui_story_5031_50311601_7_dialog_content = "ガ、ガルー先輩、ありがとうございます。\n残るのを許可してくれて…",
  ui_story_5031_50311601_8_dialog_content = "いいのいいの、\n最近は特にクエストもないし。",
  ui_story_5031_50311601_9_dialog_content = "ここでゆっくり羽根を伸ばしてね～。",
  ui_story_5031_50311601_10_dialog_content = "ほんとにいいんですか…？\nあの、エネルギーコアは放っておいても？",
  ui_story_5031_50311601_11_dialog_content = "あ～、あれはただの「小型コア」だよ。\n啓光にとっては、そんなめずらしいものでもないし。",
  ui_story_5031_50311601_12_dialog_content = "「エネルギーコア」に似てるけど、いろんな面で本物にはかなわないの。\n特にエネルギーの純度なんて、お話にならないね～。",
  ui_story_5031_50311601_13_dialog_content = "それに、あの領主がめちゃくちゃに操作しちゃったから、\n今じゃほとんど使いものにならないよ。",
  ui_story_5031_50311601_14_dialog_content = "研究価値があるとしたら…「ステュクス」改良のアイデアが、\nなにか浮かぶかもね？",
  ui_story_5031_50311601_15_dialog_content = "それにしても…悔しいなぁ。この船のこと、まだ研究し足りないのに、\nどうしてこんな時に呼び戻されちゃうの…？",
  ui_story_5031_50311601_15X1_dialog_content = "シエルちゃん、コア修理のお手伝いをする時は、\nしっかりエネルギーの伝達系統を見とくんだよ！",
  ui_story_5031_50311601_15X2_dialog_content = "ノートにちゃんとまとめといてね。\nあたしも見せてもらうから！",
  ui_story_5031_50311601_15X3_dialog_content = "わ、分かりました…",
  ui_story_5031_50311601_16_dialog_content = "あ、内緒話してる～？",
  ui_story_5031_50311601_17_dialog_content = "サプリにも聞かせて！",
  ui_story_5031_50311601_18_dialog_content = "わ、私たちが聞いてもいいなら、\nそもそも内緒話じゃないでしょ…",
  ui_story_5031_50311601_19_dialog_content = "あ、それもそっか。",
  ui_story_5031_50311601_20_dialog_content = "じゃあ、聞かな～い。",
  ui_story_5031_50311601_21_dialog_content = "よしよし、「いい子」だね～。",
  ui_story_5031_50311601_22_dialog_content = "何ですと！？",
  ui_story_5031_50311601_23_dialog_content = "うわ、うるさい！誰？",
  ui_story_5031_50311601_24_dialog_content = "本気でおっしゃっておられるのですか、カレン殿下？",
  ui_story_5031_50311601_25_dialog_content = "ここに残り、執政を代行すると！？",
  ui_story_5031_50311601_26_dialog_content = "ええ。",
  ui_story_5031_50311601_27_dialog_content = "しかし、エルビスは殿下に刃を向けたのですぞ。\nすでに大逆の罪に値する！",
  ui_story_5031_50311601_28_dialog_content = "城主殿下がお許しにならんでしょう！",
  ui_story_5031_50311601_29_dialog_content = "だから、2人の手助けが必要なのよ。",
  ui_story_5031_50311601_30_dialog_content = "…非常にイヤな予感がしますな。",
  ui_story_5031_50311601_31_dialog_content = "あなたもローウェイも、\n報告する時にこのことを伏せておいてほしいの。",
  ui_story_5031_50311601_32_dialog_content = "それから、2人は私と一緒に\nハーバーシティにしばらく留まって。",
  ui_story_5031_50311601_33_dialog_content = "なりません！",
  ui_story_5031_50311601_34_dialog_content = "申し訳ございませんが、カレン殿下…\n我らはイルンティ様の命を受けております。",
  ui_story_5031_50311601_35_dialog_content = "私にはイルンティ様に\n絶対の忠誠を保つ義務があるのです。",
  ui_story_5031_50311601_36_dialog_content = "…",
  ui_story_5031_50311601_37_dialog_content = "分かっているわ、マシュー。\nあなたの忠誠心には、少しの疑いも抱いていない。",
  ui_story_5031_50311601_38_dialog_content = "ただ、あなたとローウェイに\n面倒をかけたくないだけよ。",
  ui_story_5031_50311601_39_dialog_content = "身体の傷が、全部で17針…\nそれに消耗したせいで、一時的に光力が使えなくなっているわ。",
  ui_story_5031_50311601_40_dialog_content = "裁判長や城主様に知られたら、\nきっと面倒なことになるでしょうね？",
  ui_story_5031_50311601_41_dialog_content = "うっ、それは…",
  ui_story_5031_50311601_42_dialog_content = "もちろん、私自身の不注意で、2人には関係ないことよ。\n今の私はどこも悪くはない。",
  ui_story_5031_50311601_43_dialog_content = "お医者様が言うには、しばらく休養をとれば、\n完全に回復するらしいわ。",
  ui_story_5031_50311601_44_dialog_content = "2人が不必要な責めを負いたくないと言うのなら、\n私も協力を惜しまないわ。",
  ui_story_5031_50311601_45_dialog_content = "…",
  ui_story_5031_50311601_46_dialog_content = "なぜです？",
  ui_story_5031_50311601_47_dialog_content = "え？",
  ui_story_5031_50311601_48_dialog_content = "なぜここに残ることにこだわるのです？",
  ui_story_5031_50311601_49_dialog_content = "なぜエルビスの罪を隠そうとするのです？",
  ui_story_5031_50311601_50_dialog_content = "１つに…彼がしたことはすべて、\nハーバーシティの民のためだから。",
  ui_story_5031_50311601_51_dialog_content = "2つに…ハーバーシティは長い間白夜城の属領で、\n領主のエルビスもかつて白夜城で学んでいた。",
  ui_story_5031_50311601_52_dialog_content = "それにもかかわらず、困難に直面した時、彼は白夜城に助けを求めなかった。\n自分だけで調査を進め、白夜城は警戒さえしていた。",
  ui_story_5031_50311601_53_dialog_content = "それがどういうことか、2人には分かる？",
  ui_story_5031_50311601_54_dialog_content = "…",
  ui_story_5031_50311601_55_dialog_content = "エルビスは、私たち白夜城がこの問題を解決できない、\nあるいは、助けの手を伸べることはないと考えていたのよ。",
  ui_story_5031_50311601_56_dialog_content = "属領の領主であるにも関わらず、私たちを信じられない。\nそれこそ、謀反の種でしょう。",
  ui_story_5031_50311601_57_dialog_content = "次の領主が同じような問題に突き当たった時、\nエルビスと同じ選択をしないという保証がないわ。",
  ui_story_5031_50311601_58_dialog_content = "真相を明らかにしないままでは、問題が先延ばしされるだけ。\nそして、永遠にトゲが突き刺さったままになるでしょう。",
  ui_story_5031_50311601_59_dialog_content = "私はきちんと調べたいの。\nエルビスの本当の目的は何だったのか。",
  ui_story_5031_50311601_60_dialog_content = "そして、種が芽を出す前に、私たちがこの手で、\nトゲを根ごと抜き取らなければいけないの。",
  ui_story_5031_50311601_61_dialog_content = "…",
  ui_story_5031_50311601_62_dialog_content = "フフ…私からすれば、あなたはいつでも単純で、\n皆から守られてばかりいるお姫様でしかありませんが…",
  ui_story_5031_50311601_63_dialog_content = "…？",
  ui_story_5031_50311601_64_dialog_content = "しかし――",
  ui_story_5031_50311601_65_dialog_content = "今のお言葉には、\nなかなか貫禄があったと言わざるを得ませんな。",
  ui_story_5031_50311601_66_dialog_content = "そうだろう、ローウェイ？",
  ui_story_5031_50311601_67_dialog_content = "そう。",
  ui_story_5031_50311601_68_dialog_content = "それなら…",
  ui_story_5031_50311601_69_dialog_content = "ですが！",
  ui_story_5031_50311601_70_dialog_content = "…",
  ui_story_5031_50311601_71_dialog_content = "イルンティ様に隠し通すことなど、\n絶対にできませぬ。",
  ui_story_5031_50311601_72_dialog_content = "したがって、今晩食事をとる頃には、\nクーリエ隊を通して、イルンティ様にありのままをご報告させていただく。",
  ui_story_5031_50311601_73_dialog_content = "そうだ、クーリエ隊はどこだ？",
  ui_story_5031_50311601_74_dialog_content = "ホワ…ホワイト…なんだった？ローウェイ？",
  ui_story_5031_50311601_75_dialog_content = "…",
  ui_story_5031_50311601_76_dialog_content = "「ホワイトパール通り」、レストラン「ハッピーガーデン」の隣。",
  ui_story_5031_50311601_77_dialog_content = "ああ、そうだ、そこだ。",
  ui_story_5031_50311601_78_dialog_content = "では今晩、お前が届けてくれ、頼んだぞ。",
  ui_story_5031_50311601_79_dialog_content = "…",
  ui_story_5031_50311601_80_dialog_content = "なぜお前が行かない？",
  ui_story_5031_50311601_81_dialog_content = "私はまだ付近の見回りが残っているのだ！",
  ui_story_5031_50311601_82_dialog_content = "このような危険な状況下では、\n総合力で優れた者がカレン殿下の安全をお守りするのが道理だろう！",
  ui_story_5031_50311601_83_dialog_content = "…",
  ui_story_5031_50311601_84_dialog_content = "なんだ？やる気か？",
  ui_story_5031_50311601_85_dialog_content = "ふん、望むところ。",
  ui_story_5031_50311601_86_dialog_content = "よかろう！あそこの空き地で手合わせといくぞ！\n今日は必ず、お前に参ったと言わせてやる！！",
  ui_story_5031_50311601_87_dialog_content = "あり得ない。",
  ui_story_5031_50311601_88_dialog_content = "…",
  ui_story_5031_50311601_89_dialog_content = "カレン、話はついた？",
  ui_story_5031_50311601_90_dialog_content = "あの2人、なんで歩きながらケンカしてるの？",
  ui_story_5031_50311601_91_dialog_content = "そういう人たちなのよ。\nいつもケンカばかりして、それなのに離れない…",
  ui_story_5031_50311601_92_dialog_content = "報告の件は…",
  ui_story_5031_50311601_93_dialog_content = "話はついたわ。",
  ui_story_5031_50311601_94_dialog_content = "よかったわ…",
  ui_story_5031_50311601_95_dialog_content = "あの2人、なんか変な人たちだけど、\n意外に話は通じるのね。",
  ui_story_5031_50311601_96_dialog_content = "それはそうと、あなたたちの身体は、\n本当に大丈夫？",
  ui_story_5031_50311601_97_dialog_content = "あなたたちまでここに残る必要はないのよ。",
  ui_story_5031_50311601_98_dialog_content = "今の状況で、カレン1人残して調査を任せるなんて、\n私たちにできるはずないでしょ！",
  ui_story_5031_50311601_98X1_dialog_content = "あの後、光力が制御不能になったみたいにあふれてて、\n船から出てきてすぐに、気を失ったのよ…？",
  ui_story_5031_50311601_98X2_dialog_content = "本当にビックリしたわ！",
  ui_story_5031_50311601_98X3_dialog_content = "ごめんなさい…心配をかけたわね。",
  ui_story_5031_50311601_98X4_dialog_content = "でもカレン、どうして急に新しい力に目覚めたの？\n本当に不思議ね。",
  ui_story_5031_50311601_98X5_dialog_content = "あの時の感覚は…\nバイスが言っていた通りだったわ。",
  ui_story_5031_50311601_98X6_dialog_content = "心の中にある、私をずっと悩ませてきたものが見えた。",
  ui_story_5031_50311601_98X7_dialog_content = "現実のように責め立てられて…\n辛くて息が詰まりそうだったわ。",
  ui_story_5031_50311601_98X8_dialog_content = "カレン…",
  ui_story_5031_50311601_98X9_dialog_content = "でも、PlayerNameが私の意識につながって、\n奥底から私を引き出してくれたの。",
  ui_story_5031_50311601_98X10_dialog_content = "そして私は、あなたたちのことを思い出した。\nそれが、私の一筋の光。",
  ui_story_5031_50311601_98X11_dialog_content = "PlayerName、バイス、ありがとう。",
  ui_story_5031_50311601_98X12_dialog_content = "カレン自身で成し遂げたことだよ。\n自分の悩みに打ち勝って、自分の心と意志を完全に自分のものにしたんだ。",
  ui_story_5031_50311601_98X13_dialog_content = "そうね。でもPlayerNameの言葉が、\n心に効くのも事実ね。",
  ui_story_5031_50311601_98X14_dialog_content = "不思議な話だわ。",
  ui_story_5031_50311601_98X15_dialog_content = "そ、そうかな？",
  ui_story_5031_50311601_98X16_dialog_content = "僕はただ、思ったことをそのまま言ってるだけだよ。",
  ui_story_5031_50311601_98X17_dialog_content = "それがすごいことなのよ。",
  ui_story_5031_50311601_98X18_dialog_content = "そうね。",
  ui_story_5031_50311601_98X19_dialog_content = "でも、カレン。しばらくはゆっくり休んだほうがいいわ。\n光力の回復も急ぐことはないし。",
  ui_story_5031_50311601_98X20_dialog_content = "まだ扱いに慣れてないうちは、\n光力が暴走して、気を失いやすいわ。",
  ui_story_5031_50311601_98X21_dialog_content = "新しい力の訓練とか、\n無理にやったらダメよ！",
  ui_story_5031_50311601_98X22_dialog_content = "確かに、カレンならやっちゃいそうだ。",
  ui_story_5031_50311601_98X23_dialog_content = "ええ、覚えておくわ。",
  ui_story_5031_50311601_98X24_dialog_content = "あなたたちに心配をかけないためにも。",
  ui_story_5031_50311601_98X25_dialog_content = "新しい力については…完全に身体が回復してから、\nバイスと一緒に規則性を見つけて、コツをつかんでいくことにする。",
  ui_story_5031_50311601_98X26_dialog_content = "ええ、そうしましょ！",
  ui_story_5031_50311601_99_dialog_content = "心配いらないわ。\n私もPlayerNameも身体は丈夫だし。そうよね？",
  ui_story_5031_50311601_100_dialog_content = "そうだよ、カレンもたまには僕たちに頼ってよ。",
  ui_story_5031_50311601_101_dialog_content = "僕たちが君の面倒を見ることだって、\nあっていいじゃない！",
  ui_story_5031_50311601_102_dialog_content = "フフ…そういうことなら、お願いするわ。",
  ui_story_5031_50311601_103_dialog_content = "任せて！",
  ui_story_5031_50311601_104_dialog_content = "この後はどうするの？",
  ui_story_5031_50311601_105_dialog_content = "こんな騒ぎになっちゃったから…\n今のハーバーシティは、やらなきゃいけないことが山積みだね。",
  ui_story_5031_50311601_106_dialog_content = "領主の代わりなんて、カレン、\nきっと忙しくなるよ？",
  ui_story_5031_50311601_107_dialog_content = "確かにそうね。ただ、正式に引き継ぐ前に、\n会っておきたい人がいるわ。",
  ui_story_5031_50311601_108_dialog_content = "誰？",
  ui_story_5031_50311601_109_dialog_content = "エルビスよ。",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>つづく…</color>"
}
return config
